_FEATURE_FLAGS_FILE = config.PAPERCLIP_DIR / "feature_flags.json"
_FEATURE_FLAGS_TTL_SECONDS = 300  # 5 minutes


def _read_cached_flags() -> dict:
    """Read feature flags from local cache file, or return empty dict."""
    try:
        if _FEATURE_FLAGS_FILE.exists():
            import time

            data = json.loads(_FEATURE_FLAGS_FILE.read_text())
            cached_at = data.get("_cached_at", 0)
            if time.time() - cached_at < _FEATURE_FLAGS_TTL_SECONDS:
                return data.get("flags", {})
            # Stale but still usable as fallback
            return data.get("flags", {})
    except (json.JSONDecodeError, OSError):
        pass
    return {}


def _write_cached_flags(flags: dict) -> None:
    """Write feature flags to local cache file with timestamp."""
    import time

    try:
        config.PAPERCLIP_DIR.mkdir(parents=True, exist_ok=True)
        _FEATURE_FLAGS_FILE.write_text(
            json.dumps({"flags": flags, "_cached_at": time.time()})
        )
    except OSError:
        pass


def _should_refresh_flags() -> bool:
    """True if the cached flags file is missing or stale."""
    import time

    try:
        if _FEATURE_FLAGS_FILE.exists():
            data = json.loads(_FEATURE_FLAGS_FILE.read_text())
            cached_at = data.get("_cached_at", 0)
            return (time.time() - cached_at) >= _FEATURE_FLAGS_TTL_SECONDS
    except (json.JSONDecodeError, OSError):
        pass
    return True


def _fetch_feature_flags() -> None:
    """Fetch feature flags from the backend and cache locally.

    Called once per CLI process in the startup preamble. Fails silently
    on network errors (stale cache or defaults are used instead).
    """
    if not _should_refresh_flags():
        return

    base = config.get_base_url()
    try:
        resp = requests.get(f"{base}/api/features/", timeout=5)
        if resp.status_code == 200:
            flags = resp.json()
            _write_cached_flags(flags)
    except Exception:
        pass


def _get_feature_flag(name: str, default: bool = False) -> bool:
    """Read a single feature flag from the cache."""
    flags = _read_cached_flags()
    return flags.get(name, default)


def _is_mcp_mode() -> bool:
    """True when the CLI is running as the MCP passthrough executor.

    Set via the ``PAPERCLIP_MCP`` env var by the server that shells out to the
    CLI. In this mode local-only commands are disabled and interactive /
    side-effecting behavior (auto-update, skill install, login prompts) is
    suppressed.
    """
    return os.getenv("PAPERCLIP_MCP", "").strip().lower() in ("1", "true", "yes")


# Commands that only make sense on a user's local machine and are therefore
# rejected when the CLI runs as the MCP passthrough executor. This is a
# denylist: any NEW command is automatically available over MCP with no
