# Global API key storage (set at CLI invocation, never persisted)
_api_key: str | None = None


def _set_api_key(ctx, param, value):
    """Callback to store API key from CLI or env var."""
    global _api_key
    if value:
        _api_key = value
        os.environ["PAPERCLIP_API_KEY"] = value
    return value


def _ensure_auth() -> Credentials | None:
    """Return valid credentials, triggering interactive login if needed.

    If an API key is provided via --api-key or PAPERCLIP_API_KEY env var,
    no OAuth credentials are needed. Returns None in that case.
    """
    if _api_key:
        return None

    creds = Credentials.load()
    if creds:
        return creds

    if not sys.stdin.isatty():
        click.echo(
            f"{RED}[error] Not authenticated. Run: paperclip login{RESET}", err=True
        )
        click.echo(
            f"{RED}       Or use --api-key flag or PAPERCLIP_API_KEY env var{RESET}",
            err=True,
        )
        sys.exit(1)

    click.echo(f"{DIM}Not signed in — starting login...{RESET}")
    base = _get_base_url()
    creds = run_login(base_url=base)
    click.echo(f"{GREEN}✓{RESET} Authenticated as {BOLD}{creds.email}{RESET}\n")

    _maybe_install_skill(base)
    return creds


def _maybe_install_skill(base_url: str) -> None:
    """Offer to install the agent skill if none is detected in the current project."""
    cwd = Path.cwd()
    known_paths = [
        cwd / ".claude" / "skills" / "paperclip" / "SKILL.md",
        cwd / ".cursor" / "skills" / "paperclip" / "SKILL.md",
        cwd / ".agents" / "skills" / "paperclip" / "SKILL.md",
    ]
    if any(p.exists() for p in known_paths):
        try:
            refresh_installed_skills(_get_skills_url())
        except Exception:
            pass
        return

    if not sys.stdin.isatty():
        return

    if click.confirm("  Install Paperclip skill for your coding agent?", default=True):
        install_skill(base_url)


def _is_local_server() -> bool:
    base = _get_base_url()
    return "localhost" in base or "127.0.0.1" in base


def _is_prod_server() -> bool:
    """True when connected to the production server (not local/staging)."""
    base = _get_base_url()
    if "localhost" in base or "127.0.0.1" in base:
        return False
    if "staging" in base:
        return False
    return True


_PAPERCLIP_REEXEC = "PAPERCLIP_REEXEC"


def _re_exec() -> None:
    """Re-execute the current command so the just-installed code is used.

    Uses os.execv to replace the process in-place. Sets an env var guard
    to prevent infinite re-exec loops if something goes wrong.
    """
    if os.environ.get(_PAPERCLIP_REEXEC):
        return

    exe = sys.executable
    argv = sys.argv[:]

    paperclip_bin = shutil.which("paperclip")
    if paperclip_bin:
        argv = [paperclip_bin] + sys.argv[1:]
        exe = paperclip_bin

    os.environ[_PAPERCLIP_REEXEC] = "1"
    try:
        os.execv(exe, argv)
    except OSError:
        pass


