_PAPER_ID_RE = re.compile(
    r"\b(bio_[a-f0-9]+|PMC\d+|med_[a-f0-9]+|arx_[a-zA-Z0-9_.]+)\b"
)

# Pattern for doc_ids in map output: "  [ok] Title  (PMC123)" or "  [ok] Title  (fda_abc)"
_MAP_DOC_ID_RE = re.compile(
    r"^\s+\[(ok|error)\]\s+.+?\(("
    r"(?:bio_|med_|PMC|arx_|fda_|tri_|pat_)[a-zA-Z0-9_.]+|"
    r"NCT\d+|"
    r"[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}"
    r")\)\s*$"
)


def _extract_repo_flags(args: list[str]) -> tuple[list[str], str | None, bool]:
    """Strip ``--commit`` and ``--add`` flags from args before proxying to server.

    Returns ``(clean_args, commit_message, add_to_repo)``.
    """
    clean: list[str] = []
    commit_msg: str | None = None
    add_to_repo = False
    i = 0
    while i < len(args):
        if args[i] == "--commit" and i + 1 < len(args):
            commit_msg = args[i + 1]
            i += 2
        elif args[i] == "--add":
            add_to_repo = True
            i += 1
        else:
            clean.append(args[i])
            i += 1
    return clean, commit_msg, add_to_repo


def _auto_annotate_map_results(output: str) -> int:
    """Parse map output and annotate repo papers with their per-paper answers.

    Returns number of papers annotated.
    """
    active = _get_active_repo_name()
    if not active:
        return 0

    lines = output.split("\n")
    annotated = 0
    i = 0
    while i < len(lines):
        m = _MAP_DOC_ID_RE.match(lines[i])
        if m and m.group(1) == "ok":
            doc_id = m.group(2)
            answer_lines: list[str] = []
            j = i + 1
            while j < len(lines) and lines[j].startswith("    "):
                answer_lines.append(lines[j].strip())
                j += 1
            answer = " ".join(answer_lines)[:300]
            if answer:
                try:
                    from .. import repo

                    repo.annotate_paper(doc_id, answer)
                    annotated += 1
                except Exception:
                    pass
            i = j
        else:
            i += 1
    return annotated


def _repo_commit(message: str, repo_name: str | None = None) -> bool:
    """Commit the active repo with the given message. Returns True on success."""
    try:
        from .. import repo

        repo.commit(message, repo_name=repo_name)
        return True
    except Exception:
        return False


def _repo_add_paper_ids(paper_ids: list[str], note: str | None = None) -> dict:
    """Add papers to the active repo. Returns add result dict."""
    from .. import repo

    result = repo.add_papers(paper_ids)
    if note and result.get("added"):
        for pid in result["added"]:
            try:
                repo.annotate_paper(pid, note)
            except Exception:
                pass
    return result


