def _extract_query_from_raw(raw: str) -> str:
    """Pull the bare query string out of a search args string."""
    try:
        tokens = shlex.split(raw)
    except ValueError:
        return raw.strip()
    parts: list[str] = []
    skip = False
    for tok in tokens:
        if skip:
            skip = False
            continue
        if tok in _SEARCH_FLAGS_WITH_ARG:
            skip = True
            continue
        if tok.startswith("-"):
            continue
        parts.append(tok)
    return " ".join(parts)


def _execute_with_source_filter(command: str, raw: str) -> None:
    """Dispatch a search/sql command, fanning out across selected sources.

    If the user already passed ``-s`` in ``raw`` or no filter is stored,
    this is equivalent to calling ``_execute(command, raw)`` once.
    """
    if command == "search" and not sources_mod._raw_has_source_flag(raw) and not sources_mod._raw_has_vdir_path(raw):
        click.echo(
            "Error: search requires a source flag (-s).\n\n"
            "Available sources:\n"
            "  -s pmc          PubMed Central papers\n"
            "  -s biorxiv      bioRxiv preprints\n"
            "  -s medrxiv      medRxiv preprints\n"
            "  -s arxiv        arXiv preprints\n"
            "  -s abstracts    Abstract-grain search across all scholarly corpora\n"
            "  -s fda          FDA regulatory documents (US)\n"
            "  -s fda/jp       PMDA regulatory documents (Japan)\n"
            "  -s fda/eu       EMA regulatory documents (EU)\n"
            "  -s trials       Clinical trials (all registries)\n"
            "  -s trials/us    ClinicalTrials.gov (US)\n"
            "  -s trials/eu    EU Clinical Trials Register\n"
            "  -s trials/jp    JRCT (Japan)\n"
            "  -s trials/cn    ChiCTR (China)\n"
            "  -s proteins     UniProt + PDB + ChEMBL protein databases\n"
            "  -s uniprot      Alias for -s proteins\n\n"
            "Examples:\n"
            '  paperclip search -s pmc "CRISPR delivery"\n'
            '  paperclip search -s fda "pembrolizumab"\n'
            '  paperclip search -s trials/us "breast cancer HER2"\n',
            err=True,
        )
        raise SystemExit(1)

    selected = sources_mod.get_selected()
    show_abstracts_hint = (
        command == "search" and sources_mod.abstracts_excluded_by_default(selected, raw)
    )
    plan = sources_mod.plan_requests(raw, selected, command=command)

    if len(plan) == 1:
        _, only_raw = plan[0]
        if plan[0][0]:
            only_raw = sources_mod.inject_source_flag(raw, plan[0][0])
        _execute_argv(command, shlex.split(only_raw))
    else:
        for i, (source, base_raw) in enumerate(plan):
            scoped_raw = sources_mod.inject_source_flag(base_raw, source)
            label = source if source else "default"
            click.echo(
                f"{DIM}── source: {BOLD}{label}{RESET}{DIM} ({i + 1}/{len(plan)}) ──{RESET}",
                err=True,
            )
            _execute_argv(command, shlex.split(scoped_raw))

    if show_abstracts_hint:
        query = _extract_query_from_raw(raw)
        hint_cmd = (
            f'paperclip search -s abstracts "{query}"'
            if query
            else "paperclip search -s abstracts ..."
        )
        click.echo(
            f"\n{DIM}Tip: also search titles and abstracts across all scholarly corpora:\n"
            f"  {RESET}{hint_cmd}{RESET}",
            err=True,
        )


# ── SDK client construction ───────────────────────────────────────


_client_singleton: PaperclipClient | None = None


def _build_client() -> PaperclipClient:
    """Construct a :class:`PaperclipClient` from current process state.

    Resolution order:

    1. Trusted internal subject + secret → :class:`InternalSubjectAuth`.
    2. ``PAPERCLIP_BEARER_TOKEN`` env → :class:`BearerAuth`.
    3. ``--api-key`` / ``PAPERCLIP_API_KEY`` → :class:`APIKeyAuth`.
    4. Otherwise → :class:`FileCredentialsAuth` (after :func:`_ensure_auth`).
    """
    base = _get_base_url()
    ua = f"paperclip/{__version__}"

    internal_subject = os.getenv("PAPERCLIP_INTERNAL_SUBJECT", "").strip()
    internal_secret = os.getenv("PAPERCLIP_INTERNAL_SECRET", "").strip()
    if internal_subject and internal_secret:
        return PaperclipClient(
            auth=InternalSubjectAuth(internal_secret, internal_subject),
            base_url=base,
            user_agent=ua,
        )

    bearer = os.getenv("PAPERCLIP_BEARER_TOKEN", "").strip()
    if bearer:
        return PaperclipClient(auth=BearerAuth(bearer), base_url=base, user_agent=ua)

    if _api_key:
        return PaperclipClient(auth=APIKeyAuth(_api_key), base_url=base, user_agent=ua)

    creds = _ensure_auth()

    if creds is not None:
        return PaperclipClient(
            auth=FileCredentialsAuth(credentials=creds), base_url=base, user_agent=ua
        )

    click.echo(f"{RED}[error] No authentication available.{RESET}", err=True)
    sys.exit(1)


def _get_client(*, force_new: bool = False) -> PaperclipClient:
    """Return a cached :class:`PaperclipClient`, rebuilding if requested."""
    global _client_singleton
    if force_new or _client_singleton is None:
        _client_singleton = _build_client()
    return _client_singleton


def _is_refresh_network_error(exc: AuthError) -> bool:
    """Detect the "OAuth refresh hit a network issue" case inside an :class:`AuthError`.

    The CLI previously showed a distinct "Could not reach the server" message
    when refreshing the ID token failed. Preserve that output by sniffing the
    wrapped cause.
    """
    cause = exc.__cause__
    if cause is None:
        return False
    if isinstance(cause, (requests.ConnectionError, requests.Timeout)):
        return True
    msg = str(cause).lower()
    return "reach the server" in msg


def _emit_auth_error(exc: AuthError) -> None:
    """Print a user-facing auth/permission error and exit.

    HTTP 403 (feature/permission denied) must not be reported as an invalid
    API key — credentials can be valid while the account lacks access.
    """
    if isinstance(exc, ForbiddenError):
        detail = (exc.detail or str(exc) or "").strip()
        message = detail or (
            "Access denied — your account does not have permission "
            "for this operation."
        )
        click.echo(f"{RED}[error] {message}{RESET}", err=True)
        sys.exit(1)
    if _is_refresh_network_error(exc):
        click.echo(
            f"{RED}[error] Could not reach the server. Please try again.{RESET}",
            err=True,
        )
        sys.exit(1)
    if _api_key:
        click.echo(
            f"{RED}[error] Authentication failed (API key invalid).{RESET}",
            err=True,
        )
        sys.exit(1)
    if _is_mcp_mode():
        click.echo(f"{RED}[error] Authentication failed.{RESET}", err=True)
        sys.exit(1)


# ── Command execution + rendering ─────────────────────────────────


_update_and_skills_checked = False


def _auto_update_and_refresh_skills(*, once: bool = False) -> None:
    """Silent auto-update + skill refresh, matching previous ``_execute`` preamble.

    When ``once=True`` (interactive shell), the check runs only on the first
    call per process so subsequent shell commands don't re-hit the update
    endpoint on every keystroke.
    """
    global _update_and_skills_checked
    if once and _update_and_skills_checked:
        return

    # Under MCP passthrough the executor is a fresh, non-interactive subprocess
    # with a per-session config dir — skip auto-update, skill refresh, and the
    # feature-flag fetch (repos are force-enabled by ``_is_paper_repos_enabled``).
    if _is_mcp_mode():
        _update_and_skills_checked = True
        return

    base = _get_base_url()
    try:
        if auto_update(base):
            _re_exec()
    except Exception:
        pass

    try:
        maybe_refresh_skills(_get_skills_url())
    except Exception:
        pass

    try:
        _fetch_feature_flags()
    except Exception:
        pass

    _update_and_skills_checked = True


def _repo_only_requested(args: list[str]) -> bool:
    """True when repo-scoping is requested via the global flag or inline token."""
    return _repo_only_flag or ("--repo-only" in args)


def _strip_scope_flags(args: list[str]) -> list[str]:
    """Remove --repo-only and --corpus tokens from the arg list."""
    return [a for a in args if a not in ("--repo-only", "--corpus")]


def _augment_search_args_for_repo(args: list[str]) -> list[str]:
    """Inject ``--document-ids`` only when repo-scoping is explicitly requested.

    Default: full corpus. ``--repo-only`` opts in to scoping.
    ``--corpus`` forces full corpus even when ``--repo-only`` is set.
    """
    force_corpus = "--corpus" in args
    repo_only = _repo_only_requested(args)
    args = _strip_scope_flags(args)

    if force_corpus or not repo_only:
        return args

    active = _get_active_repo_name()
    if not active:
        return args

    ids: set[str] = set()

    try:
        from . import repo

        repo_ids = repo.get_repo_paper_ids(active)
        if repo_ids:
            ids.update(repo_ids)
    except Exception:
        pass

    try:
        from . import repo

        ids = repo.get_repo_paper_ids(active)
    except Exception:
        return args

    if not ids:
        return args

    return list(args) + ["--document-ids", ",".join(ids)]


def _augment_map_args_for_repo(args: list[str]) -> list[str]:
    """Inject ``--document-ids`` only when repo-scoping is explicitly requested.

    Default: full corpus. ``--repo-only`` opts in to scoping.
    ``--corpus`` forces full corpus even when ``--repo-only`` is set.
    ``--from`` and explicit ``--document-ids`` also bypass augmentation.
    """
    force_corpus = "--corpus" in args
    repo_only = _repo_only_requested(args)
    args = _strip_scope_flags(args)

    if force_corpus or not repo_only:
        return args

    has_from = False
    has_doc_ids = False
    for a in args:
        if a == "--from":
            has_from = True
        if a in ("--document-ids", "--document_ids"):
            has_doc_ids = True
    if has_from or has_doc_ids:
        return args

    active = _get_active_repo_name()
    if not active:
        return args

    try:
        from . import repo

        ids = repo.get_repo_paper_ids(active)
    except Exception:
        return args

    if not ids:
        return args

    return list(args) + ["--document-ids", ",".join(ids)]


def _prepare_map_worker_args(args: list[str]) -> tuple[list[str], str]:
    """Validate trusted map workers and inject the active exhaustive repo."""
    prepared = _normalize_map_recovery_args(args)
    control_flags = ("--resume", "--retry-failed", "--cancel")

    def has_control_flag() -> bool:
        return any(
            token == flag or token.startswith(f"{flag}=")
            for token in prepared
            for flag in control_flags
        )

    worker = "quick-reader"
    if "--worker" in prepared:
        index = prepared.index("--worker")
        if index + 1 >= len(prepared):
            raise click.UsageError("--worker requires a value")
        worker = prepared[index + 1].strip().lower()
        prepared[index + 1] = worker
    else:
        for index, token in enumerate(prepared):
            if token.startswith("--worker="):
                worker = token.split("=", 1)[1].strip().lower()
                if not worker:
                    raise click.UsageError("--worker requires a value")
                prepared[index] = f"--worker={worker}"
                break
    allowed = {
        "quick-reader",
        "eligibility-screen",
        "scorecard-verifier",
        "scorecard-verifier-fast",
        "structured-extraction",
        "exhaustive-extraction",
    }
    if worker not in allowed:
        raise click.UsageError(
            "unknown map worker; choose quick-reader, eligibility-screen, "
            "scorecard-verifier, scorecard-verifier-fast, "
            "structured-extraction, or exhaustive-extraction"
        )
    if "--claim-schema" in prepared:
        index = prepared.index("--claim-schema")
        if index + 1 >= len(prepared):
            raise click.UsageError("--claim-schema requires JSON")
        try:
            schema = json.loads(prepared[index + 1])
        except json.JSONDecodeError as exc:
            raise click.UsageError(f"invalid --claim-schema JSON: {exc}") from exc
        if not isinstance(schema, dict):
            raise click.UsageError("--claim-schema must be a JSON object")
    if worker == "exhaustive-extraction":
        if "--claim-schema" not in prepared and not has_control_flag():
            raise click.UsageError(
                "exhaustive-extraction requires --claim-schema JSON"
            )
        if "--repo" not in prepared:
            active = _get_active_repo_name()
            if active:
                prepared.extend(["--repo", active])
            elif not has_control_flag():
                raise click.UsageError(
                    "exhaustive-extraction requires --repo NAME or an active repo"
                )
    if worker == "structured-extraction" and not has_control_flag():
        schema_value = None
        for index, token in enumerate(prepared):
            if token in {"--output-schema", "--output_schema"}:
                if index + 1 >= len(prepared):
                    raise click.UsageError("--output-schema requires JSON Schema")
                schema_value = prepared[index + 1]
                break
            if token.startswith(("--output-schema=", "--output_schema=")):
                schema_value = token.split("=", 1)[1]
                break
        if schema_value is None:
            raise click.UsageError(
                "structured-extraction requires --output-schema JSON Schema"
            )
        try:
            output_schema = json.loads(schema_value)
        except json.JSONDecodeError as exc:
            raise click.UsageError(f"invalid --output-schema JSON: {exc}") from exc
        if not isinstance(output_schema, dict) or not output_schema:
            raise click.UsageError(
                "--output-schema must be a non-empty JSON Schema object"
            )
        if "--claim-schema" in prepared:
            raise click.UsageError(
                "structured-extraction rejects --claim-schema; use only --output-schema"
            )
        if "--repo" in prepared:
            raise click.UsageError("structured-extraction does not persist to repos; remove --repo")
    if worker == "quick-reader" and has_control_flag():
        return prepared, "resume"
    return prepared, worker


def _normalize_map_recovery_args(args: list[str]) -> list[str]:
    """Canonicalize map recovery controls around one ``--resume`` map ID.

    Recovery uses ``--resume MAP_ID [--retry-failed]`` so there is one
    unambiguous map-ID argument.
    """
    prepared: list[str] = []
    resume_id: str | None = None
    retry_failed = False
    index = 0

    def set_resume_id(value: str) -> None:
        nonlocal resume_id
        value = value.strip()
        if not value:
            raise click.UsageError("--resume requires a map ID")
        if resume_id is not None and resume_id != value:
            raise click.UsageError("map recovery accepts only one map ID")
        resume_id = value

    while index < len(args):
        token = args[index]
        if token == "--resume":
            if index + 1 >= len(args):
                raise click.UsageError("--resume requires a map ID")
            set_resume_id(args[index + 1])
            index += 2
            continue
        if token.startswith("--resume="):
            set_resume_id(token.split("=", 1)[1])
            index += 1
            continue
        if token == "--retry-failed":
            if index + 1 < len(args) and args[index + 1].startswith("m_"):
                raise click.UsageError(
                    "use --resume MAP_ID --retry-failed; "
                    "--retry-failed does not accept a map ID"
                )
            retry_failed = True
            index += 1
            continue
        if token.startswith("--retry-failed="):
            raise click.UsageError(
                "use --resume MAP_ID --retry-failed; "
                "--retry-failed does not accept a map ID"
            )
        prepared.append(token)
        index += 1

    if retry_failed and resume_id is None:
        raise click.UsageError("--retry-failed requires --resume MAP_ID")
    if resume_id is not None:
        prepared.extend(["--resume", resume_id])
    if retry_failed:
        prepared.append("--retry-failed")
    return prepared


def _execute_argv(command: str, args: list[str]) -> ExecuteResult | None:
    """Run ``command`` with raw ``args`` and render the response.

    ``args`` is a list of argv tokens, NOT a pre-joined shell string.
    """
    _auto_update_and_refresh_skills()

    # Extract repo flags (--commit, --add) before proxying to server
    args, commit_msg, add_to_repo = _extract_repo_flags(args)

    if command == "map":
        try:
            args, worker = _prepare_map_worker_args(args)
        except click.UsageError as exc:
            click.echo(f"{RED}[error] {exc}{RESET}", err=True)
            sys.exit(2)
        if worker == "structured-extraction" and (commit_msg or add_to_repo):
            click.echo(
                f"{RED}[error] structured-extraction does not support --commit or --add{RESET}",
                err=True,
            )
            sys.exit(2)
        args = _augment_map_args_for_repo(args)
        _render_map(args, commit_msg=commit_msg, worker=worker)
        return

    if command == "search":
        args = _augment_search_args_for_repo(args)
        # Validate --ranking flag
        _VALID_RANKINGS = {"bm25", "vector", "hybrid", "analogical"}
        for i, a in enumerate(args):
            if a == "--ranking" and i + 1 < len(args):
                val = args[i + 1].lower()
                if val not in _VALID_RANKINGS:
                    click.echo(
                        f"{RED}[error] Invalid --ranking '{args[i+1]}'. "
                        f"Must be one of: {', '.join(sorted(_VALID_RANKINGS))}{RESET}",
                        err=True,
                    )
                    sys.exit(1)
                args[i + 1] = val
                break

    client = _get_client()
    if command == "search-workflow":
        final = _consume_workflow_with_retry(client, args)
        result = ExecuteResult(
            output=final.output,
            exit_code=final.exit_code,
            elapsed_ms=final.elapsed_ms,
            result_id=final.result_id,
            cwd=final.cwd,
            result_data=final.result_data,
        )
    else:
        result = _execute_with_retry(client, command, args)
    if command == "search-workflow" and result.exit_code != 0:
        detail = result.output or ""
        if "command not found" in detail.lower():
            raise click.ClickException(
                "This Paperclip server does not support YAML search workflows. "
                "Run against the updated local unified stack."
            )
        _render_execute_result(command, args, result)
        raise SystemExit(result.exit_code or 1)
    _render_execute_result(command, args, result)

    # Post-command repo operations for search
    active_repo = _get_active_repo_name()
    if active_repo and command == "search" and result.exit_code == 0:
        if add_to_repo:
            paper_ids = _PAPER_ID_RE.findall(result.output or "")
            if paper_ids:
                try:
                    add_result = _repo_add_paper_ids(paper_ids)
                    n = len(add_result.get("added", []))
                    if n:
                        click.echo(f"{DIM}  auto-added {n} papers to repo{RESET}")
                except Exception:
                    pass

    if commit_msg and active_repo:
        if _repo_commit(commit_msg):
            click.echo(f"{DIM}  committed: {commit_msg}{RESET}")
    return result


def _execute_with_retry(
    client: PaperclipClient, command: str, args: list[str]
) -> ExecuteResult:
    """Call :meth:`PaperclipClient.execute` with CLI error handling.

    Maps SDK exceptions to the exact error strings / exit codes the previous
    ``_execute`` printed, and preserves the OAuth ``401 → re-login → retry``
    dance.

    A 429 (rate limit OR the "too many concurrent long-running commands" cap on
    map/verify/commit) is retried with exponential backoff. This is safe because
    the server rejects on the concurrency gate BEFORE executing the command, so
    a retry never double-runs — it just waits for a slot. Without this, a commit
    that momentarily collided with other verifies would hard-fail and its claims
    would be dropped.
    """
    import random as _random
    import time as _time

    def _exec_retry_429(cl: PaperclipClient) -> ExecuteResult:
        attempts = 6
        for i in range(attempts):
            try:
                result = cl.execute(command, args=args, cwd=config.get_cli_cwd())
                if result.cwd:
                    config.set_cli_cwd(result.cwd)
                return result
            except RateLimitError as exc:
                if i == attempts - 1:
                    raise
                base_wait = min(2 * (2 ** i), 30)
                wait = round(base_wait * _random.uniform(0.75, 1.25), 2)
                click.echo(
                    f"{YELLOW}[waiting] {exc} Retrying in {wait}s "
                    f"({i + 1}/{attempts - 1})...{RESET}",
                    err=True,
                )
                _time.sleep(wait)
        raise RateLimitError("retry budget exhausted")  # unreachable

    try:
        return _exec_retry_429(client)
    except ForbiddenError as exc:
        _emit_auth_error(exc)
    except AuthError as exc:
        if _is_refresh_network_error(exc) or _api_key or _is_mcp_mode():
            _emit_auth_error(exc)
        Credentials.delete()
        click.echo(f"{DIM}Session expired — re-authenticating...{RESET}", err=True)
        _ensure_auth()
        click.echo(f"{DIM}Retrying...{RESET}", err=True)
        new_client = _get_client(force_new=True)
        try:
            return _exec_retry_429(new_client)
        except ForbiddenError as retry_exc:
            _emit_auth_error(retry_exc)
        except AuthError:
            click.echo(f"{RED}[error] Authentication failed.{RESET}", err=True)
            sys.exit(1)
        except (NetworkError, ServerError, PaperclipError):
            click.echo(
                f"{RED}[error] Something went wrong. Please try again.{RESET}", err=True
            )
            sys.exit(1)
    except RateLimitError as e:
        msg = str(e) if str(e) else "Too many requests. Please wait a moment."
        click.echo(f"{YELLOW}[rate limit] {msg}{RESET}", err=True)
        sys.exit(1)
    except RequestTimeoutError:
        click.echo(f"{RED}[error] Request timed out{RESET}", err=True)
        if command in ("search", "map", "sql", "lookup"):
            click.echo(
                f"{DIM}Try: narrower query, add --since 1y, or --source pmc{RESET}",
                err=True,
            )
        sys.exit(1)
    except NetworkError:
        click.echo(f"{RED}[error] Could not reach the server.{RESET}", err=True)
        click.echo(
            f"{DIM}       If this persists, try: paperclip login{RESET}", err=True
        )
        sys.exit(1)
    except ServerError:
        click.echo(
            f"{RED}[error] Something went wrong. Please try again.{RESET}", err=True
        )
        sys.exit(1)
    except PaperclipError:
        click.echo(
            f"{RED}[error] Something went wrong. Please try again.{RESET}", err=True
        )
        sys.exit(1)


def _consume_workflow_with_retry(
    client: PaperclipClient, args: list[str]
) -> WorkflowResultEvent:
    """Consume a workflow stream with the standard CLI auth and 429 recovery."""
    import random as _random
    import time as _time

    def _retry_429(cl: PaperclipClient) -> WorkflowResultEvent:
        attempts = 6
        for i in range(attempts):
            try:
                return _consume_workflow_stream(cl.stream("search-workflow", args))
            except RateLimitError as exc:
                if i == attempts - 1:
                    raise
                base_wait = min(2 * (2**i), 30)
                wait = round(base_wait * _random.uniform(0.75, 1.25), 2)
                click.echo(
                    f"{YELLOW}[waiting] {exc} Retrying in {wait}s "
                    f"({i + 1}/{attempts - 1})...{RESET}",
                    err=True,
                )
                _time.sleep(wait)
        raise RateLimitError("retry budget exhausted")  # unreachable

    try:
        return _retry_429(client)
    except ForbiddenError as exc:
        _emit_auth_error(exc)
    except AuthError as exc:
        if _is_refresh_network_error(exc) or _api_key or _is_mcp_mode():
            _emit_auth_error(exc)
        Credentials.delete()
        click.echo(f"{DIM}Session expired — re-authenticating...{RESET}", err=True)
        _ensure_auth()
        click.echo(f"{DIM}Retrying...{RESET}", err=True)
        new_client = _get_client(force_new=True)
        try:
            return _retry_429(new_client)
        except ForbiddenError as retry_exc:
            _emit_auth_error(retry_exc)
        except AuthError:
            click.echo(f"{RED}[error] Authentication failed.{RESET}", err=True)
            sys.exit(1)
        except (NetworkError, ServerError, PaperclipError):
            click.echo(
                f"{RED}[error] Something went wrong. Please try again.{RESET}", err=True
            )
            sys.exit(1)
    except RateLimitError as exc:
        msg = str(exc) if str(exc) else "Too many requests. Please wait a moment."
        click.echo(f"{YELLOW}[rate limit] {msg}{RESET}", err=True)
        sys.exit(1)
    except RequestTimeoutError:
        click.echo(f"{RED}[error] Request timed out{RESET}", err=True)
        sys.exit(1)
    except NetworkError:
        click.echo(f"{RED}[error] Could not reach the server.{RESET}", err=True)
        click.echo(
            f"{DIM}       If this persists, try: paperclip login{RESET}", err=True
        )
        sys.exit(1)
    except (ServerError, PaperclipError):
        click.echo(
            f"{RED}[error] Something went wrong. Please try again.{RESET}", err=True
        )
        sys.exit(1)


def _strip_response_envelope(text: str) -> tuple[str, bool]:
    """Strip the server-side ResponseManager envelope from large MCP responses.

    The MCP server wraps responses >50KB in a "Large Response Saved" envelope
    with metadata headers and a truncated preview.  The CLI should show the raw
    content instead, since the user (or shell redirect) expects cat-like output.

    Returns (stripped_content, was_truncated).

    Server format::

        🔄 Large Response Saved
        ...metadata lines...
        Preview (first N characters):
        ------------------------------------------------------------
        <content>
        ------------------------------------------------------------
    """
    if "Large Response Saved" not in text:
        return _strip_tool_response_header(text), False

    lines = text.split("\n")

    # Content starts after the first "----…" separator that follows a
    # "Preview (first … characters):" line.
    start = 0
    for i, line in enumerate(lines):
        if re.match(r"^-{20,}$", line.strip()):
            start = i + 1
            break
    else:
        return _strip_tool_response_header(text), False

    # Content ends before the trailing "----…" / "[… content truncated …]" / blank
    end = len(lines)
    truncated = False
    for i in range(len(lines) - 1, start - 1, -1):
        s = lines[i].strip()
        if "content truncated" in s:
            truncated = True
            continue
        if not s or re.match(r"^-{20,}$", s):
            continue
        end = i + 1
        break

    content = "\n".join(lines[start:end]).strip()
    content = content if content else text
    return _strip_tool_response_header(content), truncated


def _strip_tool_response_header(text: str) -> str:
    """Strip the 'Tool Response: …' / 'Generated: …' / '====…' header."""
    if not text.startswith("Tool Response:"):
        return text
    lines = text.split("\n")
    for i, line in enumerate(lines):
        if re.match(r"^={20,}$", line.strip()):
            rest = "\n".join(lines[i + 1 :]).strip()
            return rest if rest else text
    return text


def _render_execute_result(
    command: str, args: list[str], result: ExecuteResult
) -> None:
    """Format an :class:`ExecuteResult` exactly like the pre-SDK CLI did."""
    if result.download_url:
        filename = result.download_filename or "download.bin"
        if not sys.stdout.isatty():
            _stream_binary_to_stdout(result.download_url)
            return
        click.echo(
            f"{DIM}Binary file ({filename}). Redirect to save locally, e.g.:{RESET}"
        )
        raw = _format_argv_for_hint(args)
        click.echo(f"  {command} {raw} > {filename}".rstrip())
        return

    output = result.output or ""

    if _maybe_handle_mcp_binary(output):
        return

    output, was_truncated = _strip_response_envelope(output)

    if output:
        click.echo(output)
        if was_truncated and sys.stdout.isatty():
            raw = _format_argv_for_hint(args)
            click.echo(
                f"\n{DIM}--- truncated (preview only) ---\n"
                f"To save full results:  paperclip {command} {raw} > output.txt{RESET}",
                err=True,
            )

    active_repo = _get_active_repo_name()
    result_id = result.result_id
    if active_repo and command == "search":
        try:
            from . import repo

            repo.record_search(shlex.join(args), result_id)
        except Exception:
            pass

    elapsed = result.elapsed_ms
    tag = _repo_tag()
    footer_parts = []
    if _is_mcp_mode():
        # Under MCP passthrough the server merges this process's stderr back
        # into the tool output, so any footer would be fused onto the payload
        # (breaking machine-read outputs like `citations --count-only`).
        # Timing is chrome the model never acts on — drop it and keep only
        # the result id, which agents need for `map --from`.
        if result_id:
            footer_parts.append(f"{DIM}[saved to {result_id}]{RESET}")
    elif elapsed is not None:
        label = f"{elapsed}ms" if elapsed < 1000 else f"{elapsed / 1000:.1f}s"
        if result_id:
            footer_parts.append(f"{DIM}[{label}, saved to {result_id}]{RESET}")
        else:
            footer_parts.append(f"{DIM}[{label}]{RESET}")
    if tag:
        footer_parts.append(tag)
    if footer_parts:
        # The timing/repo footer is UI chrome, not command output. When stdout
        # is piped (e.g. `paperclip cat meta.json | jq`), send it to stderr so
        # it never corrupts machine-readable output; keep it on stdout only for
        # interactive terminals.
        click.echo("  ".join(footer_parts), err=not sys.stdout.isatty())


def _format_argv_for_hint(args: list[str]) -> str:
    """Reconstruct the original ``raw`` shell string for the redirect hint line."""
    return shlex.join(args) if args else ""


def _maybe_handle_mcp_binary(output: str) -> bool:
    """Detect an MCP-path binary_download JSON payload and stream or hint.

    Returns ``True`` if the payload was handled (caller should not print
    anything else) and ``False`` otherwise.
    """
    stripped = output.strip() if output else ""
    if (
        not stripped
        or '"binary_download"' not in stripped
        or '"download_url"' not in stripped
    ):
        return False
    try:
        payload = json.loads(stripped)
    except json.JSONDecodeError:
        return False
    if not isinstance(payload, dict) or payload.get("type") != "binary_download":
        return False
    url = payload.get("download_url", "")
    fname = payload.get("filename") or "download.bin"
    if url and not sys.stdout.isatty():
        _stream_binary_to_stdout(url)
        return True
    if url:
        click.echo(
            f"{DIM}Binary file ({fname}). Redirect to save locally, e.g.:{RESET}"
        )
        click.echo(f"  paperclip cat <path> > {fname}")
        return True
    return False


def _stream_binary_to_stdout(url: str) -> None:
    """Fetch a signed download URL and stream bytes to stdout.

    Used when the user redirects or pipes binary output, e.g.
        paperclip cat /papers/<id>/figures/fig1.jpg > fig1.jpg

    Error messages are intentionally URL-free: ``requests`` exception strings
    normally embed the full failing URL (including the signature), which
    would then land in terminal recorders, piped logs, CI capture, agent
    transcripts, etc. We strip them down to a status code or a generic
    network error.
    """
    try:
        with requests.get(url, stream=True, timeout=120) as r:
            r.raise_for_status()
            for chunk in r.iter_content(chunk_size=65536):
                if chunk:
                    sys.stdout.buffer.write(chunk)
            sys.stdout.buffer.flush()
    except requests.HTTPError as e:
        status = e.response.status_code if e.response is not None else "?"
        click.echo(
            f"{RED}[error] Download failed (HTTP {status}). "
            f"Re-run the command to get a fresh link.{RESET}",
            err=True,
        )
        sys.exit(1)
    except requests.RequestException:
        click.echo(f"{RED}[error] Download failed (network).{RESET}", err=True)
        sys.exit(1)


def _render_map(
    args: list[str],
    *,
    commit_msg: str | None = None,
    worker: str = "quick-reader",
) -> None:
    """Run a streaming map command and render progress + final result."""
    client = _get_client()
    repo_name = None
    if "--repo" in args:
        repo_index = args.index("--repo")
        if repo_index + 1 < len(args):
            repo_name = args[repo_index + 1]

    def _do_stream(events_iter):
        output = _consume_map_stream(events_iter)
        _post_map_repo_actions(
            output, commit_msg, worker=worker, repo_name=repo_name
        )

    def _run_stream(active_client, stream_args: list[str]) -> None:
        import random as _random
        import time as _time

        for attempt in range(6):
            try:
                _do_stream(active_client.stream("map", stream_args))
                return
            except RateLimitError:
                if attempt == 5:
                    raise
                delay = _random.uniform(0.0, min(30.0, 2.0 * (2**attempt)))
                click.echo(
                    f"{YELLOW}[rate limit] Retrying map in {delay:.1f}s...{RESET}",
                    err=True,
                )
                _time.sleep(delay)

    try:
        stream_args = args
        recovered = False
        while True:
            try:
                _run_stream(client, stream_args)
                break
            except _MapStreamInterrupted as exc:
                if recovered or not exc.run_id:
                    raise
                recovered = True
                stream_args = ["--resume", exc.run_id]
                click.echo(
                    f"{YELLOW}[recovery] Stream interrupted; resuming "
                    f"{exc.run_id}...{RESET}",
                    err=True,
                )
        return
    except _MapStreamInterrupted as exc:
        click.echo(f"{RED}[error] Stream ended without result{RESET}", err=True)
        if exc.run_id:
            click.echo(
                f"{DIM}       Resume later with: paperclip map --resume "
                f"{exc.run_id}{RESET}",
                err=True,
            )
        sys.exit(1)
    except ForbiddenError as exc:
        _emit_auth_error(exc)
    except AuthError as exc:
        if _is_refresh_network_error(exc) or _api_key or _is_mcp_mode():
            _emit_auth_error(exc)
        Credentials.delete()
        click.echo(f"{DIM}Session expired — re-authenticating...{RESET}", err=True)
        _ensure_auth()
        try:
            retry_client = _get_client(force_new=True)
            _run_stream(retry_client, stream_args)
            return
        except ForbiddenError as retry_exc:
            _emit_auth_error(retry_exc)
        except AuthError:
            click.echo(f"{RED}[error] Authentication failed.{RESET}", err=True)
            sys.exit(1)
        except Exception:
            click.echo(
                f"{RED}[error] Something went wrong. Please try again.{RESET}", err=True
            )
            sys.exit(1)
    except RateLimitError as e:
        msg = str(e) if str(e) else "Too many requests. Please wait a moment."
        click.echo(f"{YELLOW}[rate limit] {msg}{RESET}", err=True)
        sys.exit(1)
    except RequestTimeoutError:
        click.echo(f"{RED}[error] Request timed out{RESET}", err=True)
        click.echo(
            f"{DIM}Tip: re-run search with -n 5 to limit papers, then map again.{RESET}",
            err=True,
        )
        sys.exit(1)
    except NetworkError:
        click.echo(f"{RED}[error] Could not reach the server.{RESET}", err=True)
        click.echo(
            f"{DIM}       If this persists, try: paperclip login{RESET}", err=True
        )
        sys.exit(1)
    except (ServerError, PaperclipError):
        click.echo(
            f"{RED}[error] Something went wrong. Please try again.{RESET}", err=True
        )
        sys.exit(1)


class _MapStreamInterrupted(PaperclipError):
    """A map stream ended after exposing a recoverable run ID."""

    def __init__(self, run_id: str | None):
        super().__init__("Map stream ended without a final result")
        self.run_id = run_id


def _consume_map_stream(events) -> str:
    """Drain a map event stream, rendering progress lines and the final result.

    Returns the map output text for downstream processing (auto-annotation).
    """
    wrote_progress = False
    got_result = False
    got_result_id = False
    run_id = None
    output_text = ""
    try:
        for ev in events:
            if isinstance(ev, MapProgressEvent):
                if ev.run_id:
                    run_id = ev.run_id
                # Progress uses carriage-return / clear-line escapes meant for a TTY.
                # Suppress it under MCP passthrough so it doesn't pollute the output.
                if _is_mcp_mode():
                    continue
                bar = _progress_bar(ev.completed + ev.failed, ev.total)
                status = f"{DIM}  {bar}  {ev.completed + ev.failed}/{ev.total} papers"
                if ev.run_id:
                    status += f"  run {ev.run_id}"
                if ev.failed:
                    status += f" ({ev.failed} failed)"
                status += f"  [{ev.elapsed_s:g}s]{RESET}"
                click.echo(f"{CLR}\r{status}", nl=False, err=True)
                wrote_progress = True
            elif isinstance(ev, MapResultEvent):
                if wrote_progress:
                    click.echo("", err=True)
                if ev.output:
                    click.echo(ev.output)
                    output_text = ev.output
                if ev.elapsed_ms is not None:
                    label = (
                        f"{ev.elapsed_ms}ms"
                        if ev.elapsed_ms < 1000
                        else f"{ev.elapsed_ms / 1000:.1f}s"
                    )
                    if ev.result_id:
                        click.echo(f"{DIM}[{label}, saved to {ev.result_id}]{RESET}")
                    else:
                        click.echo(f"{DIM}[{label}]{RESET}")
                got_result = True
                got_result_id = bool(ev.result_id)
                if ev.exit_code != 0:
                    sys.exit(1)
    except (NetworkError, RequestTimeoutError) as exc:
        if wrote_progress:
            click.echo("", err=True)
        raise _MapStreamInterrupted(run_id) from exc

    if not got_result or (not output_text.strip() and not got_result_id):
        if wrote_progress:
            click.echo("", err=True)
        raise _MapStreamInterrupted(run_id)

    return output_text


def _consume_workflow_stream(events) -> WorkflowResultEvent:
    """Render step-level workflow events and return the terminal result event."""
    final = None
    last_event = None
    for event in events:
        if isinstance(event, WorkflowProgressEvent):
            event_key = (
                event.status,
                event.step,
                event.step_index,
                event.paper_count,
                event.result_id,
            )
            if event_key == last_event:
                continue
            last_event = event_key
            elapsed = f"{event.elapsed_s:g}s"
            if event.status == "started":
                click.echo(
                    f"{DIM}Starting workflow {event.workflow} "
                    f"({event.total_steps} steps){RESET}",
                    err=True,
                )
            elif event.status == "step_started":
                click.echo(
                    f"{DIM}[{event.step_index}/{event.total_steps}] "
                    f"{event.step}: {event.operation} running… [{elapsed}]{RESET}",
                    err=True,
                )
            elif event.status == "step_completed":
                click.echo(
                    f"{DIM}[{event.step_index}/{event.total_steps}] "
                    f"{event.step}: {event.paper_count or 0:,} papers "
                    f"[{event.result_id}] [{elapsed}]{RESET}",
                    err=True,
                )
            elif event.status == "failed":
                click.echo(
                    f"{RED}[error] Workflow failed at {event.step}: "
                    f"{event.error or 'unknown error'}{RESET}",
                    err=True,
                )
        elif isinstance(event, WorkflowResultEvent):
            final = event
    if final is None:
        raise NetworkError("Search workflow stream ended without a final result.")
    return final


def _post_map_repo_actions(
    output: str,
    commit_msg: str | None,
    *,
    worker: str = "quick-reader",
    repo_name: str | None = None,
) -> None:
    """Auto-annotate papers from map results and optionally commit."""
    active = repo_name or _get_active_repo_name()
    if not active:
        return
    n = (
        0
        if worker
        in {
            "exhaustive-extraction",
            "structured-extraction",
            "resume",
        }
        else _auto_annotate_map_results(output)
    )
    if worker == "structured-extraction":
        return
    if n:
        click.echo(f"{DIM}  auto-annotated {n} papers from map results{RESET}")
    if commit_msg:
        if _repo_commit(commit_msg, repo_name=active):
            click.echo(f"{DIM}  committed: {commit_msg}{RESET}")


def _progress_bar(done: int, total: int, width: int = 20) -> str:
    if total <= 0:
        return "[" + "." * width + "]"
    filled = int(width * done / total)
    return "[" + "#" * filled + "." * (width - filled) + "]"


