def _check_update_hint(base: str) -> str | None:
    """Return an update hint string if a newer version is available, else None.

    Uses a cached, non-blocking check so the dashboard stays fast.
    """
    try:
        latest = check_update_available(base)
        if latest:
            return latest
    except Exception:
        pass
    return None


