_PASSTHROUGH = dict(
    ignore_unknown_options=True,
    allow_extra_args=True,
    help_option_names=[],
)


def _execute_search_config(args: list[str]) -> bool:
    """Handle local search-config operations; return whether one was handled."""
    if "--config-guide" in args:
        if args != ["--config-guide"]:
            raise click.UsageError(
                "--config-guide cannot be combined with other search arguments"
            )
        from .config_guide import load_search_config_guide

        guide = load_search_config_guide()
        click.echo(guide, nl=not guide.endswith("\n"))
        return True

    config_path: str | None = None
    parameter_overrides: list[str] = []
    input_overrides: list[str] = []
    save_as: str | None = None
    background = False
    confirm = False
    detach = False
    unexpected: list[str] = []
    i = 0
    while i < len(args):
        arg = args[i]
        if arg == "--config":
            if i + 1 >= len(args):
                raise click.UsageError("--config requires a YAML file path")
            config_path = args[i + 1]
            i += 2
        elif arg.startswith("--config="):
            config_path = arg.split("=", 1)[1]
            i += 1
        elif arg in ("--set", "--input"):
            if i + 1 >= len(args):
                raise click.UsageError(f"{arg} requires NAME=VALUE")
            (parameter_overrides if arg == "--set" else input_overrides).append(
                args[i + 1]
            )
            i += 2
        elif arg.startswith("--set="):
            parameter_overrides.append(arg.split("=", 1)[1])
            i += 1
        elif arg.startswith("--input="):
            input_overrides.append(arg.split("=", 1)[1])
            i += 1
        elif arg == "--save-as":
            if i + 1 >= len(args):
                raise click.UsageError("--save-as requires an alias")
            save_as = args[i + 1]
            i += 2
        elif arg.startswith("--save-as="):
            save_as = arg.split("=", 1)[1]
            i += 1
        elif arg in {"--background", "--batch"}:
            background = True
            i += 1
        elif arg == "--confirm":
            confirm = True
            i += 1
        elif arg == "--detach":
            detach = True
            i += 1
        else:
            unexpected.append(arg)
            i += 1
    if config_path is None:
        return False
    if unexpected:
        raise click.UsageError(
            "--config cannot be combined with a query or ordinary search options: "
            + " ".join(unexpected)
        )
    from .search_config import SearchConfigError, load_search_config

    try:
        spec = load_search_config(
            config_path,
            parameter_overrides=tuple(parameter_overrides),
            input_overrides=tuple(input_overrides),
        )
    except SearchConfigError as exc:
        raise click.UsageError(str(exc)) from exc
    if background:
        if save_as:
            raise click.UsageError(
                "--save-as is not supported for background search configs"
            )
        if input_overrides or spec.get("inputs") or spec.get("resolved_inputs"):
            raise click.UsageError(
                "background search configs do not support result-set inputs"
            )
        request = {"operation": "search_workflow", "workflow_spec": spec}
        _submit_batch_request("search", args, request, confirm, detach)
        return True
    if confirm or detach:
        raise click.UsageError("--confirm and --detach require --background")
    payload = json.dumps(spec, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
    encoded = base64.urlsafe_b64encode(payload).decode("ascii")
    workflow_args = ["--spec", encoded]
    if save_as:
        workflow_args.extend(["--save-as", save_as])
    _execute_argv("search-workflow", workflow_args)
    return True


def _parse_batch_request(command: str, args: list[str]) -> tuple[dict, bool, bool]:
    """Parse options for durable background grep and search jobs."""
    request: dict = {
        "operation": command,
        "query": "",
        "limit": None,
        "all": False,
        "count_only": False,
        "ignore_case": True,
        "section": None,
        "source": None,
        "boolean": False,
        "include_evidence": True,
    }
    confirm = False
    detach = False
    positional: list[str] = []
    index = 0
    while index < len(args):
        token = args[index]
        if token == "--":
            positional.extend(args[index + 1 :])
            break
        if token in {"--background", "--batch"}:
            index += 1
        elif token == "--confirm":
            confirm = True
            index += 1
        elif token == "--detach":
            detach = True
            index += 1
        elif token == "--all":
            request["all"] = True
            index += 1
        elif token == "--bool":
            if command != "grep":
                raise click.UsageError("--bool is supported only for background grep")
            request["boolean"] = True
            index += 1
        elif token == "--no-evidence":
            if command != "grep":
                raise click.UsageError(
                    "--no-evidence is supported only for background grep"
                )
            request["include_evidence"] = False
            index += 1
        elif token in ("-c", "--count-only"):
            request["count_only"] = True
            index += 1
        elif token == "-i":
            request["ignore_case"] = True
            index += 1
        elif token == "--case-sensitive":
            request["ignore_case"] = False
            index += 1
        elif token in ("-n", "--limit"):
            if index + 1 >= len(args):
                raise click.UsageError(f"{token} requires a positive integer")
            try:
                request["limit"] = int(args[index + 1])
            except ValueError as exc:
                raise click.UsageError(f"{token} requires a positive integer") from exc
            index += 2
        elif token.startswith("--limit="):
            try:
                request["limit"] = int(token.split("=", 1)[1])
            except ValueError as exc:
                raise click.UsageError("--limit requires a positive integer") from exc
            index += 1
        elif token.startswith("-n") and len(token) > 2:
            try:
                request["limit"] = int(token[2:])
            except ValueError as exc:
                raise click.UsageError("-n requires a positive integer") from exc
            index += 1
        elif token in ("-s", "--source", "--section"):
            if index + 1 >= len(args):
                raise click.UsageError(f"{token} requires a value")
            key = "section" if token == "--section" else "source"
            request[key] = args[index + 1]
            index += 2
        elif token.startswith("--source="):
            request["source"] = token.split("=", 1)[1]
            index += 1
        elif token.startswith("--section="):
            request["section"] = token.split("=", 1)[1]
            index += 1
        elif token.startswith("-"):
            if command == "grep" and any(
                value.startswith("/papers") for value in args[index + 1 :]
            ):
                positional.append(token)
                index += 1
            else:
                raise click.UsageError(f"{token} is not supported in background mode")
        else:
            positional.append(token)
            index += 1

    if command == "grep":
        paper_paths = [value for value in positional if value.startswith("/papers")]
        query_parts = [value for value in positional if not value.startswith("/papers")]
        if len(paper_paths) != 1:
            raise click.UsageError("background grep requires the /papers/ path")
        if paper_paths and any(path.rstrip("/") != "/papers" for path in paper_paths):
            raise click.UsageError("background grep currently supports only /papers/")
        if len(query_parts) != 1:
            raise click.UsageError("background grep requires one PATTERN and /papers/")
        request["query"] = query_parts[0]
        if not request["boolean"] and not request["include_evidence"]:
            raise click.UsageError("--no-evidence requires --bool")
    else:
        if not positional:
            raise click.UsageError("background search requires a query")
        if request["limit"] is None:
            raise click.UsageError("background search requires -n")
        request["query"] = " ".join(positional)
    return request, confirm, detach


def _render_batch_quote(command: str, args: list[str], quote: dict) -> None:
    estimated = int(quote.get("estimated_matching_documents") or 0)
    document_limit = int(quote.get("document_limit") or 50_000)
    returned = int(quote.get("will_return_documents") or 0)
    click.echo(f"Estimated matching documents: {estimated:,}")
    request = quote.get("request") or {}
    if request.get("count_only"):
        click.echo("This operation will count exact matches across the full corpus.")
    elif estimated > document_limit:
        click.echo(
            f"This operation will return results from up to {returned:,} documents."
        )
    else:
        click.echo(f"This operation will return results from {returned:,} documents.")
    if request.get("boolean") and not request.get("count_only"):
        click.echo(f"Document limit: {document_limit:,}")
    elif request.get("operation") == "grep" and not request.get("count_only"):
        click.echo(
            f"Occurrence limit: {int(quote.get('occurrence_limit') or 100_000):,}"
        )
    click.echo(
        f"Estimated run time: {int(quote.get('estimated_runtime_seconds') or 0):,} seconds"
    )
    click.echo(
        f"Estimated queue delay: {int(quote.get('estimated_queue_delay_seconds') or 0):,} seconds"
    )
    confirmation = [value for value in args if value != "--confirm"]
    confirmation.append("--confirm")
    click.echo(f"Confirm with:\n  {shlex.join(['paperclip', command, *confirmation])}")


def _poll_batch_job(client: PaperclipClient, job_id: str) -> dict:
    delay = 1.0
    while True:
        job = client.batch.status(job_id)
        status = job.get("status")
        progress = job.get("progress") or {}
        if status in {"complete", "failed", "cancelled", "expired"}:
            return job
        corpus = progress.get("corpus")
        scanned = progress.get("documents_scanned")
        detail = f" corpus={corpus}" if corpus else ""
        if scanned is not None:
            detail += f" scanned={int(scanned):,}"
        click.echo(f"Job {job_id}: {status}{detail}", err=True)
        time.sleep(delay)
        delay = min(delay * 1.5, 10.0)


def _submit_batch_request(
    command: str,
    args: list[str],
    request: dict,
    confirm: bool,
    detach: bool,
) -> None:
    client = _get_client()
    try:
        if not confirm:
            _render_batch_quote(command, args, client.batch.quote(request))
            return
        job = client.batch.confirm(request)
        job_id = str(job["job_id"])
        click.echo(f"Background job submitted: {job_id}")
        if detach:
            return
        try:
            job = _poll_batch_job(client, job_id)
        except KeyboardInterrupt:
            click.echo(
                f"\nJob continues in the background. "
                f"Check it with: paperclip jobs status {job_id}",
                err=True,
            )
            return
        status = job.get("status")
        if status != "complete":
            detail = job.get("error") or status
            raise click.ClickException(f"Background job {status}: {detail}")
        progress = job.get("progress") or {}
        if request.get("count_only"):
            click.echo(f"Matching documents: {int(progress.get('matching_docs') or 0):,}")
            if not request.get("boolean"):
                click.echo(f"Occurrences: {int(progress.get('occurrences') or 0):,}")
            return
        destination = f"paperclip-job-{job_id}.jsonl"
        client.batch.download(job_id, destination)
        click.echo(f"Result: {destination}")
        result_id = (job.get("result") or {}).get("result_id")
        if result_id:
            click.echo(f"Result ID: {result_id}")
        if (job.get("result") or {}).get("document_limit_reached"):
            document_limit = int(job.get("document_limit") or 50_000)
            click.echo(f"Document limit reached: {document_limit:,}")
        if (job.get("result") or {}).get("output_limit_reached"):
            click.echo("Output limit reached: 256 MiB")
    except PaperclipError as exc:
        raise click.ClickException(str(exc)) from exc


def _execute_batch_request(command: str, args: list[str]) -> None:
    request, confirm, detach = _parse_batch_request(command, args)
    _submit_batch_request(command, args, request, confirm, detach)


class _PaperclipGroup(click.Group):
    """Catch-all group that forwards unknown commands to the server.

    Unregistered subcommands (search, lookup, sql, grep, cat, head, ls, scan,
    bash, pull, ask-image, python, map, etc.) are sent as-is to
    :func:`_execute_argv`, which dispatches to the SDK.
    """

    def get_command(self, ctx: click.Context, cmd_name: str):
        if cmd_name == "skills":
            return self._make_removed_skills_cmd()
        # git / repos are aliases for repo. Normalize before the feature gate
        # so every name is gated identically.
        if cmd_name in ("repos", "git"):
            cmd_name = "repo"
        if cmd_name in _REPO_COMMANDS and not _is_paper_repos_enabled():
            # When the user has turned repos off locally, show a clear
            # "disabled" message. (A server-side flag still falls through to
            # the historical bash-proxy behavior.)
            if not config.repos_enabled():
                return self._make_repos_disabled_cmd(cmd_name)
            return self._make_bash_proxy(cmd_name)
        rv = super().get_command(ctx, cmd_name)
        if rv is not None:
            return rv
        return self._make_bash_proxy(cmd_name)

    @staticmethod
    def _make_removed_skills_cmd() -> click.Command:
        @click.command("skills", context_settings=_PASSTHROUGH, hidden=True)
        @click.argument("args", nargs=-1, type=click.UNPROCESSED)
        def removed(args: tuple) -> None:
            del args
            raise click.UsageError(
                "The plural `paperclip skills` interface was replaced by "
                "`paperclip routines`. The singular `paperclip skill` command "
                "still loads core and domain-reference skills."
            )

        return removed

    @staticmethod
    def _make_repos_disabled_cmd(cmd_name: str) -> click.Command:
        @click.command(
            cmd_name,
            context_settings=_PASSTHROUGH,
            help=f"'{cmd_name}' is unavailable — paper repositories are disabled.",
        )
        @click.argument("args", nargs=-1, type=click.UNPROCESSED)
        def disabled(args: tuple) -> None:
            click.echo(
                f"{YELLOW}Paper repositories are disabled.{RESET} "
                f"The {BOLD}{cmd_name}{RESET} command is unavailable.",
                err=True,
            )
            click.echo(
                f"{DIM}Run {RESET}{BOLD}paperclip repos-feature enable{RESET}"
                f"{DIM} to turn the feature back on.{RESET}",
                err=True,
            )
            raise SystemExit(2)

        return disabled

    @staticmethod
    def _make_bash_proxy(cmd_name: str) -> click.Command:
        @click.command(
            cmd_name,
            context_settings=_PASSTHROUGH,
            help=f"Run '{cmd_name}' on the paper filesystem.",
        )
        @click.argument("args", nargs=-1, type=click.UNPROCESSED)
        @click.pass_context
        def proxy(ctx, args: tuple) -> None:
            global _api_key

            filtered_args: list[str] = []
            i = 0
            while i < len(args):
                if args[i] == "--api-key" and i + 1 < len(args):
                    _api_key = args[i + 1]
                    i += 2
                elif args[i].startswith("--api-key="):
                    _api_key = args[i].split("=", 1)[1]
                    i += 1
                else:
                    filtered_args.append(args[i])
                    i += 1

            active = _get_active_repo_name()

            if cmd_name == "search" and _execute_search_config(filtered_args):
                return

            if cmd_name in {"grep", "search"} and any(
                option in filtered_args for option in {"--background", "--batch"}
            ):
                _execute_batch_request(cmd_name, filtered_args)
                return

            if active and cmd_name in ("cat", "head", "tail", "grep", "scan", "bash"):
                joined = shlex.join(filtered_args)
                ids_in_cmd = _PAPER_ID_RE.findall(joined)
                if ids_in_cmd:
                    try:
                        from . import repo

                        repo_ids = set(repo.get_repo_paper_ids())
                        outside = [pid for pid in ids_in_cmd if pid not in repo_ids]
                        if outside:
                            click.echo(
                                f"{DIM}(note: {', '.join(outside)} not in repo '{active}'){RESET}",
                                err=True,
                            )
                    except Exception:
                        pass

            if cmd_name in _FILTERABLE_CMDS:
                raw = shlex.join(filtered_args)
                _execute_with_source_filter(cmd_name, raw)
            else:
                _execute_argv(cmd_name, filtered_args)

        return proxy

    def resolve_command(self, ctx: click.Context, args):
        cmd_name = args[0] if args else None
        if cmd_name and not cmd_name.startswith("-"):
            cmd = self.get_command(ctx, cmd_name)
            if cmd is not None:
                return cmd_name, cmd, args[1:]
        return super().resolve_command(ctx, args)

    def invoke(self, ctx):
        if ctx.invoked_subcommand in ("config", "login"):
            if _api_key:
                click.echo(
                    f"{RED}[error] --api-key is not allowed for '{ctx.invoked_subcommand}' command{RESET}",  # noqa: E501
                    err=True,
                )
                sys.exit(1)
        return super().invoke(ctx)


def _peel_folder_alias(args: list[str]) -> list[str]:
    """Treat ``-f`` / ``--folder`` as ``--repo`` on the repo command group."""
    from . import repo as repo_mod

    out: list[str] = []
    i = 0
    while i < len(args):
        tok = args[i]
        if tok == "--":
            out.extend(args[i:])
            break
        if tok in ("-f", "--folder") and i + 1 < len(args) and not args[i + 1].startswith("-"):
            repo_mod.set_repo_override(repo_mod.normalize_repo_folder(args[i + 1]))
            i += 2
            continue
        if tok.startswith("--folder="):
            repo_mod.set_repo_override(
                repo_mod.normalize_repo_folder(tok.split("=", 1)[1])
            )
            i += 1
            continue
        out.append(tok)
        i += 1
    return out


class _RepoGroup(click.Group):
    """Repo command group shared by ``git``, ``repo``, and ``repos``.

    ``checkout`` is the default name; ``switch`` is also accepted.
    ``--repo`` is the default override; ``-f`` / ``--folder`` still work
    (one-shot, no sticky checkout).
    """

    def parse_args(self, ctx: click.Context, args: list[str]) -> list[str]:
        return super().parse_args(ctx, _peel_folder_alias(args))

    def get_command(self, ctx: click.Context, cmd_name: str):
        if cmd_name == "switch":
            cmd_name = "checkout"
        return super().get_command(ctx, cmd_name)


@click.group(cls=_PaperclipGroup, invoke_without_command=True)
@click.version_option(package_name="gxl-paperclip")
@click.option("--debug", is_flag=True, help="Enable debug logging")
@click.option("--repo-only", "repo_only", is_flag=True, help="Restrict search/map to the active repo's papers (default: full corpus)")
@click.option(
    "--repo",
    "-f",
    "--folder",
    "repo_name",
    default=None,
    help="Use this repo for one command (does not change sticky checkout). Preferred. -f / --folder still work.",
)
@click.option(
    "--api-key",
    callback=_set_api_key,
    expose_value=False,
    help=(
        "API key for authentication (alternative to OAuth). "
        "Can also be set via PAPERCLIP_API_KEY env var."
    ),
    envvar="PAPERCLIP_API_KEY",
)
@click.pass_context
def main(ctx, debug: bool, repo_only: bool, repo_name: str | None):
    """Paperclip — search biomedical papers, regulatory documents, and clinical trials from the command line.

    \b
    Quick start:
        paperclip search -s pmc "protein design"
        paperclip search -s pmc,biorxiv,medrxiv "protein design"
        paperclip search -s fda "DeepHealth 510k"
        paperclip search -s trials/us "HER2 breast cancer"
        paperclip search -s pmc --min-embedding-similarity 0.7 --min-bm25-score 5 "protein design"
        paperclip cat /papers/bio_dca47d15/meta.json
        paperclip cat /fda/<uuid>/meta.json

    \b
    Search requires -s/--source. Common sources:
        pmc, biorxiv, medrxiv, arxiv, abstracts
        fda, fda/jp, fda/eu
        trials, trials/us, trials/eu, trials/jp, trials/cn
        proteins
    Combine sources with commas, for example: -s pmc,biorxiv,medrxiv
    `-s abstracts` searches only title/abstract chunks across PMC, arXiv,
    bioRxiv/medRxiv, and the residual abstract-only corpus.

    \b
    Paper repos (persistent, sticky). ``git`` is preferred; ``repo``/``repos`` work too:
        paperclip git init my-topic "Description"
        paperclip git checkout my-topic            # all subsequent commands scoped here
        paperclip search -s pmc "query"             # search all PMC (record search in active repo)
        paperclip --repo-only search -s pmc "query" # restrict search to repo papers
        paperclip git add PMC123 bio_456

    Sign-in happens automatically on first use.
    Use --api-key or set PAPERCLIP_API_KEY env var for non-interactive authentication.
    Run `paperclip skill` for the full command and filesystem guide.
    Run `paperclip routines --help` to browse and enable guided workflows.
    """
    level = logging.DEBUG if debug else logging.WARNING
    logging.basicConfig(level=level, format="%(levelname)s: %(message)s")

    ctx.ensure_object(dict)
    ctx.obj["repo_only"] = repo_only

    if _is_mcp_mode() and ctx.invoked_subcommand in MCP_DISABLED_COMMANDS:
        click.echo(
            f"{RED}[error] '{ctx.invoked_subcommand}' is not available over MCP. "
            f"Run it from the paperclip CLI on your own machine.{RESET}",
            err=True,
        )
        sys.exit(2)

    global _repo_only_flag
    _repo_only_flag = repo_only

    if repo_name and _is_paper_repos_enabled():
        from . import repo

        repo_name = repo.normalize_repo_folder(repo_name)
        repo_name = repo_name.strip().replace(" ", "-").lower()
        try:
            m = repo._load_manifest(repo_name)
            if m is None:
                click.echo(
                    f"{RED}[error] Repo '{repo_name}' not found.{RESET}", err=True
                )
                sys.exit(1)
            repo.set_repo_override(repo_name)
        except Exception as e:
            click.echo(f"{RED}[error] {e}{RESET}", err=True)
            sys.exit(1)

    if ctx.invoked_subcommand is None:
        _show_dashboard()


# ── batch jobs ────────────────────────────────────────────────────


@main.group("batch")
def batch_cmd():
    """List, inspect, cancel, read, and download background jobs."""


main.add_command(batch_cmd, "jobs")


@batch_cmd.command("list")
@click.option("--limit", type=click.IntRange(1, 100), default=50, show_default=True)
def batch_list_cmd(limit: int):
    """List recent batch jobs."""
    try:
        jobs = _get_client().batch.list(limit=limit)
    except PaperclipError as exc:
        raise click.ClickException(str(exc)) from exc
    if not jobs:
        click.echo("No background jobs.")
        return
    for job in jobs:
        request = job.get("request") or {}
        query = str(
            request.get("query")
            or (request.get("workflow_spec") or {}).get("name")
            or ""
        )
        position = job.get("queue_position")
        queue = f" queue={position}" if position else ""
        click.echo(
            f"{job['job_id']}  {job['status']:<9} {job['operation']:<6}{queue}  {query}"
        )


@batch_cmd.command("status")
@click.argument("job_id")
def batch_status_cmd(job_id: str):
    """Show one batch job."""
    try:
        job = _get_client().batch.status(job_id)
    except PaperclipError as exc:
        raise click.ClickException(str(exc)) from exc
    click.echo(json.dumps(job, indent=2, sort_keys=True))


@batch_cmd.command("cancel")
@click.argument("job_id")
def batch_cancel_cmd(job_id: str):
    """Request cancellation of one batch job."""
    try:
        job = _get_client().batch.cancel(job_id)
    except PaperclipError as exc:
        raise click.ClickException(str(exc)) from exc
    click.echo(f"{job_id}: {job['status']}")


@batch_cmd.command("read")
@click.argument("job_id")
@click.option("--head", type=click.IntRange(1), default=None, help="Show first N rows.")
@click.option("--offset", type=click.IntRange(0), default=0, show_default=True)
@click.option(
    "--limit",
    "byte_limit",
    type=click.IntRange(1, 1024 * 1024),
    default=64 * 1024,
    show_default=True,
    help="Maximum bytes to read.",
)
@click.option("--grep", "contains", default=None, help="Keep rows containing this text.")
def batch_read_cmd(
    job_id: str,
    head: int | None,
    offset: int,
    byte_limit: int,
    contains: str | None,
):
    """Read part of a completed JSON Lines result."""
    try:
        batch = _get_client().batch
        if head is None:
            text = batch.read(
                job_id, offset=offset, limit=byte_limit, contains=contains
            )
        else:
            rows: list[str] = []
            next_offset = offset
            while len(rows) < head:
                page = batch.read_page(
                    job_id,
                    offset=next_offset,
                    limit=byte_limit,
                    contains=contains,
                )
                rows.extend(page["text"].splitlines(keepends=True))
                if page["eof"] or page["next_offset"] <= next_offset:
                    break
                next_offset = page["next_offset"]
            text = "".join(rows[:head])
    except PaperclipError as exc:
        raise click.ClickException(str(exc)) from exc
    click.echo(text, nl=not text.endswith("\n"))


@batch_cmd.command("download")
@click.argument("job_id")
@click.option("-o", "--output", default=None, help="Destination JSON Lines file.")
def batch_download_cmd(job_id: str, output: str | None):
    """Download a completed result with an atomic rename."""
    destination = output or f"paperclip-job-{job_id}.jsonl"
    try:
        _get_client().batch.download(job_id, destination)
    except PaperclipError as exc:
        raise click.ClickException(str(exc)) from exc
    click.echo(destination)


