@main.command("config")
@click.option("--url", help="Set server base URL (e.g. http://localhost:8002)")
@click.option("--show", is_flag=True, help="Show current configuration")
@click.option(
    "--sources",
    "sources_args",
    multiple=True,
    help="Set source filter (e.g. --sources pmc --sources fda)",
)
@click.option("--sources-list", is_flag=True, help="Show current source filter")
@click.option("--sources-clear", is_flag=True, help="Remove source filter")
def config_cmd(
    url: str | None,
    show: bool,
    sources_args: tuple,
    sources_list: bool,
    sources_clear: bool,
):
    """Configure Paperclip settings and show connection diagnostics.

    \b
    Examples:
        paperclip config                          # show diagnostics
        paperclip config --url http://localhost:8002
        paperclip config --sources pmc --sources fda
        paperclip config --sources-list
        paperclip config --sources-clear
    """
    from . import repo as repo_mod

    if sources_clear:
        sources_mod.print_status()
        return

    if sources_list:
        sources_mod.print_status()
        return

    if sources_args:
        sources_mod.print_status()
        return

    state = _load_state()

    if url and not show:
        state["base_url"] = url.rstrip("/")
        state.pop("mcp_url", None)
        _save_state(state)
        click.echo(f"{GREEN}✓{RESET} Server URL set: {url}")
        return

    base = _get_base_url()
    click.echo(f"\n  {BOLD}Paperclip{RESET}")
    click.echo(f"  Server:  {base}")
    if "base_url" not in state and "mcp_url" not in state:
        click.echo(f"           {YELLOW}(default){RESET}")
    creds = Credentials.load()
    api_key = state.get("api_key")
    env_bearer = os.getenv("PAPERCLIP_BEARER_TOKEN", "").strip()
    env_api_key = os.getenv("PAPERCLIP_API_KEY", "").strip()
    if env_bearer:
        click.echo(f"  Auth:    {GREEN}✓{RESET} bearer token (env)")
    elif env_api_key:
        click.echo(f"  Auth:    {GREEN}✓{RESET} API key (env)")
    elif api_key:
        click.echo(f"  Auth:    {GREEN}✓{RESET} API key")
    elif creds:
        click.echo(f"  Auth:    {GREEN}✓{RESET} {creds.email}")
    else:
        click.echo(f"  Auth:    {YELLOW}✗{RESET} (run: paperclip login)")
    click.echo(f"  Config:  {config.PAPERCLIP_DIR}")

    try:
        resp = requests.get(f"{base}/health", timeout=3)
        if resp.ok:
            click.echo(f"  Health:  {GREEN}✓{RESET} server reachable")
        else:
            click.echo(f"  Health:  {RED}✗{RESET} {resp.status_code}")
    except Exception:
        click.echo(f"  Health:  {RED}✗{RESET} unreachable")

    selected = sources_mod.get_selected()
    if selected:
        click.echo(f"  Sources: {sources_mod.describe(selected)}")
    else:
        click.echo(f"  Sources: {DIM}all (no filter){RESET}")

    click.echo()


