@main.command()
@click.argument("name", required=False)
def skill(name: str | None):
    """Print core Paperclip docs or load a named domain reference skill.

    The installed agent skill and the MCP instructions are lightweight
    pointers; this command returns the full ground-truth documentation:
    filesystem layout, command reference, workflows, citation format, and
    SQL schemas. Pass a domain name such as ``patents`` to load that reference.
    """
    if name is None:
        _skill_system_impl()
        return

    from .skill import fetch_skill_content

    normalized = name.removesuffix(".md")
    if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_-]*", normalized):
        raise click.UsageError("invalid skill name")
    if any(
        item.get("name") == normalized and item.get("listed") is True
        for item in _fetch_skills_index()
        if isinstance(item, dict)
    ):
        raise click.UsageError(
            f'`{normalized}` is a routine; use '
            f"`paperclip routines show {normalized}`"
        )
    content = fetch_skill_content(_get_skills_url(), normalized)
    if content is None:
        raise click.ClickException(f'Failed to fetch skill "{normalized}"')
    click.echo(content)


