@routines.command("route")
@click.argument("intent")
def routines_route(intent: str):
    """Load the enabled routine matching a concise intent."""
    from .skill import fetch_skill_content

    try:
        response = requests.post(
            f"{_get_base_url()}/api/skills/route",
            json={"intent": intent},
            timeout=10,
            headers=skill_request_headers(),
        )
        response.raise_for_status()
        result = response.json()
    except requests.exceptions.HTTPError as exc:
        if getattr(exc.response, "status_code", None) == 401:
            click.echo(
                f"{RED}[error] Not signed in.{RESET}\n"
                f"  Run `paperclip login` then "
                f"`paperclip routines enable <name>` first.",
                err=True,
            )
            raise SystemExit(1) from exc
        raise click.ClickException(f"Failed to route routine: {exc}") from exc
    except Exception as exc:
        raise click.ClickException(f"Failed to route routine: {exc}") from exc

    status_value = result.get("status")
    if status_value == "no_match":
        click.echo("No enabled routine matched this intent.", err=True)
        raise SystemExit(1)
    if status_value == "ambiguous":
        names = ", ".join(
            str(item.get("name"))
            for item in result.get("candidates", [])
            if isinstance(item, dict)
        )
        click.echo(f"Ambiguous routine intent; candidates: {names}", err=True)
        raise SystemExit(2)
    match = result.get("match")
    name = match.get("name") if isinstance(match, dict) else None
    if not isinstance(name, str) or not name:
        raise click.ClickException("Routine router returned an invalid match")
    content = fetch_skill_content(_get_skills_url(), name)
    if content is None:
        raise click.ClickException(f'Failed to fetch routed routine "{name}"')
    click.echo(content)


@routines.command(
    "run",
    context_settings={"ignore_unknown_options": True, "allow_extra_args": True},
)
@click.argument("name")
@click.argument("operation")
@click.option(
    "--dir",
    "target_dir",
    default=".",
    help="Local analysis directory helpers may read and write.",
)
@click.option("--json", "json_output", is_flag=True, help="Request JSON output.")
@click.argument("operation_args", nargs=-1, type=click.UNPROCESSED)
def routines_run(
    name: str,
    operation: str,
    target_dir: str,
    json_output: bool,
    operation_args: tuple[str, ...],
):
    """Run a named trusted helper from a verified temporary bundle."""
    from .skill_runtime import SkillRuntimeError, run_remote_helper

    name = _validate_routine_name(name)
    _routine_catalog_entry(name)
    try:
        result = run_remote_helper(
            skills_url=_get_skills_url(),
            bundle_url=_get_skill_runtime_url(),
            skill=name,
            operation=operation,
            directory=target_dir,
            arguments=operation_args,
            json_output=json_output,
        )
    except SkillRuntimeError as exc:
        raise click.ClickException(str(exc)) from exc
    if result.stdout:
        click.echo(result.stdout, nl=not result.stdout.endswith("\n"))
    if result.stderr:
        click.echo(result.stderr, err=True, nl=not result.stderr.endswith("\n"))
    if result.returncode:
        raise SystemExit(result.returncode)


def _skill_system_impl():
    """Print core Paperclip docs with available routines and domain references."""
    from .skill import fetch_full_skill

    content = fetch_full_skill(_get_skills_url())
    if content is None:
        click.echo("Failed to fetch skill documentation from server.", err=True)
        raise SystemExit(1)

    sections: list[str] = []

    enabled = _fetch_enabled_skills(fail_silently=True)
    auth_failed = enabled is _ENABLE_AUTH_FAILED
    if enabled and not auth_failed:
        sections.append("")
        sections.append("## Available routines")
        sections.append("")
        sections.append(
            "If the user's request matches a routine below, load it with "
            "`paperclip routines show <name>` and follow its instructions."
        )
        sections.append("")
        sections.append("| Routine | Use when |")
        sections.append("|---------|----------|")
        for item in enabled:
            triggers = item.get("triggers", "")
            if isinstance(triggers, list):
                triggers = ", ".join(str(value) for value in triggers)
            name = item.get("name", "")
            sections.append(f"| `{name}` | {triggers} |")
        sections.append("")

    references = _fetch_skill_references()
    if references:
        sections.append("")
        sections.append("## Domain references")
        sections.append("")
        sections.append(
            "For deep work in a specific domain, load the reference with "
            "`paperclip skill <name>` before proceeding."
        )
        sections.append("")
        sections.append("| Reference | Use when |")
        sections.append("|-----------|----------|")
        for item in references:
            triggers = item.get("triggers", "")
            if isinstance(triggers, list):
                triggers = ", ".join(str(value) for value in triggers)
            name = item.get("name", "")
            sections.append(f"| `{name}` | {triggers} |")
        sections.append("")

    if sections:
        content = content.rstrip() + "\n" + "\n".join(sections) + "\n"
    click.echo(content)


