@main.command()
def update():
    """Update Paperclip to the latest version and refresh agent skills."""
    base = _get_base_url()
    click.echo(f"  {DIM}Current version: {__version__}{RESET}")
    click.echo(f"  {DIM}Checking for updates...{RESET}")

    latest = fetch_latest_version(base)
    if latest is None:
        click.echo(
            f"  {DIM}Could not check for binary updates (server unreachable).{RESET}"
        )
    elif not needs_update(latest):
        click.echo(f"  {GREEN}✓{RESET} Already up to date (v{__version__})")
    else:
        click.echo(f"  {BOLD}New version available: v{latest}{RESET}")

        if not is_managed_install():
            click.echo(
                f"\n  {YELLOW}Paperclip was not installed via the standard installer.{RESET}"
            )
            click.echo("  To update, re-run the installer:")
            click.echo(f"    {BOLD}curl -fsSL {base}/install.sh | bash{RESET}")
        else:
            click.echo(f"  {DIM}Downloading...{RESET}")
            ok, msg = perform_update(base)
            if ok:
                click.echo(f"\n  {GREEN}✓{RESET} Updated to v{msg}")
                click.echo(
                    f"  {DIM}Restart your shell or run a new command to use the new version.{RESET}"
                )
            else:
                click.echo(f"\n  {RED}Update failed: {msg}{RESET}")
                click.echo(f"  {DIM}You can update manually:{RESET}")
                click.echo(f"    {BOLD}curl -fsSL {base}/install.sh | bash{RESET}")

    click.echo(f"\n  {DIM}Refreshing agent skills...{RESET}")
    find_and_refresh_all_skills(_get_skills_url())


