@main.command()
@click.option(
    "--keep-credentials",
    is_flag=True,
    help="Keep credentials (only remove binary + skills)",
)
def uninstall(keep_credentials: bool):
    """Remove Paperclip from this machine."""
    removed = []
    bin_path = Path.home() / ".local" / "bin" / "paperclip"
    install_dir = config.PAPERCLIP_DIR

    if bin_path.exists():
        bin_path.unlink()
        removed.append(str(bin_path))

    if install_dir.exists():
        if keep_credentials:
            lib_dir = install_dir / "lib"
            if lib_dir.exists():
                shutil.rmtree(lib_dir)
                removed.append(str(lib_dir))
        else:
            shutil.rmtree(install_dir)
            removed.append(str(install_dir))

    cwd = Path.cwd()
    skill_dirs = [
        cwd / ".claude" / "skills" / "paperclip",
        cwd / ".cursor" / "skills" / "paperclip",
        cwd / ".agents" / "skills" / "paperclip",
    ]
    for d in skill_dirs:
        if d.exists():
            shutil.rmtree(d)
            removed.append(str(d))

    if removed:
        click.echo(f"{GREEN}✓{RESET} Removed:")
        for r in removed:
            click.echo(f"    {r}")
        click.echo(
            f"\n  {DIM}To reinstall: curl -fsSL https://paperclip.gxl.ai/install.sh | bash{RESET}"
        )
    else:
        click.echo("Nothing to remove — Paperclip doesn't appear to be installed.")


