@main.group("repo", cls=_RepoGroup, invoke_without_command=True)
@click.option("-n", "limit", type=int, default=10, help="Number of repos to show (default 10, 0 = all).")
@click.pass_context
def repo_cmd(ctx, limit):
    """List repos or show repo details.

    ``paperclip git`` is the preferred name. ``repo`` and ``repos`` are the
    same command group.

    \b
    Examples:
        paperclip git                   # list 10 most recent repos
        paperclip git -n 0              # list all repos
        paperclip git info <name>       # overview of a specific repo
        paperclip git status            # current papers, claims, [OK]/[X]
        paperclip git claims            # claims as JSON (with doc_id + line pins)
        paperclip git log               # commit history
        paperclip git history           # command audit trail
    """
    if ctx.invoked_subcommand is not None:
        return

    from datetime import datetime, timezone

    from . import repo

    try:
        repos = repo.list_repos()
        if not repos:
            click.echo(
                f"{DIM}No repos. Create one with: paperclip git init <name>{RESET}"
            )
            return
        active = repo.get_active_repo()

        def _parse_date(r):
            raw = r.get("created_at", "")
            if not raw:
                return datetime.min.replace(tzinfo=timezone.utc)
            try:
                return datetime.fromisoformat(raw.replace("Z", "+00:00"))
            except (ValueError, TypeError):
                return datetime.min.replace(tzinfo=timezone.utc)

        repos.sort(key=_parse_date, reverse=True)

        active_repo = None
        rest = []
        for r in repos:
            if r["name"] == active:
                active_repo = r
            else:
                rest.append(r)

        if limit > 0:
            rest = rest[: limit - (1 if active_repo else 0)]

        ordered = ([active_repo] if active_repo else []) + rest
        total = len(repos)

        shown = len(ordered)
        header = f"\n  {BOLD}Paper Repos{RESET} ({shown}"
        if shown < total:
            header += f" of {total}, use -n 0 for all"
        header += ")\n"
        click.echo(header)

        now = datetime.now(timezone.utc)
        for r in ordered:
            marker = f"{GREEN}●{RESET}" if r["name"] == active else f"{DIM}○{RESET}"
            papers = f"{DIM}({r['paper_count']} papers){RESET}"
            dt = _parse_date(r)
            if dt == datetime.min.replace(tzinfo=timezone.utc):
                date_str = ""
            else:
                delta = now - dt
                if delta.days == 0:
                    date_str = f"{DIM}today{RESET}"
                elif delta.days == 1:
                    date_str = f"{DIM}yesterday{RESET}"
                elif delta.days < 7:
                    date_str = f"{DIM}{delta.days}d ago{RESET}"
                else:
                    date_str = f"{DIM}{dt.strftime('%b %d')}{RESET}"
            desc = f"  {DIM}{r['description'][:50]}{RESET}" if r.get("description") else ""
            click.echo(f"    {marker} {r['name']}  {papers}  {date_str}{desc}")
        click.echo(f"\n  {DIM}Switch: paperclip git checkout <name>{RESET}\n")
    except AuthError:
        click.echo(
            f"{RED}[error] Authentication failed (API key invalid).{RESET}", err=True
        )
        sys.exit(1)


@repo_cmd.command("init")
@click.argument("name")
@click.argument("description", required=False, default="")
@click.option(
    "--from-library",
    "from_library",
    is_flag=True,
    help="Seed repo with matched papers from your library",
)
@click.option(
    "-s",
    "--search",
    "lib_query",
    default=None,
    help="Filter library papers by keyword (with --from-library)",
)
def init_cmd(name: str, description: str, from_library: bool, lib_query: str | None):
    """Create a new paper repo.

    \b
    Examples:
        paperclip git init kras-resistance "KRAS G12C resistance mechanisms"
        paperclip git init my-review
        paperclip git init lit-review --from-library            # seed with all library papers
        paperclip git init subset --from-library -s "CRISPR"    # seed with matching library papers
    """
    from . import repo

    try:
        m = repo.init_repo(name, description)
        click.echo(f"{GREEN}✓{RESET} Created repo: {BOLD}{m['name']}{RESET}")
        if description:
            click.echo(f"  {DIM}{description}{RESET}")

        if from_library:
            papers = repo.library_get_papers()
            if not papers:
                click.echo(f"  {DIM}Library is empty — nothing to seed.{RESET}")
            else:
                corpus_papers = {
                    pid: p for pid, p in papers.items() if not pid.startswith("ref_")
                }
                if lib_query:
                    q = lib_query.lower()
                    corpus_papers = {
                        pid: p
                        for pid, p in corpus_papers.items()
                        if q in (p.get("title", "") or "").lower()
                        or q in (p.get("authors", "") or "").lower()
                        or q in (p.get("journal", "") or "").lower()
                    }
                if corpus_papers:
                    titles = {
                        pid: p["title"]
                        for pid, p in corpus_papers.items()
                        if p.get("title")
                    }
                    dois = {
                        pid: p["doi"]
                        for pid, p in corpus_papers.items()
                        if p.get("doi")
                    }
                    result = repo.add_papers(
                        list(corpus_papers.keys()), titles=titles, dois=dois
                    )
                    meta = {}
                    for pid, p in corpus_papers.items():
                        m = {}
                        for k in (
                            "authors",
                            "journal",
                            "year",
                            "pub_year",
                            "cited_by_count",
                            "entry_key",
                            "source",
                        ):
                            if p.get(k):
                                m[k] = p[k]
                        if m:
                            meta[pid] = m
                    if meta:
                        repo.update_paper_metadata(meta)
                    click.echo(
                        f"  {GREEN}+{RESET} Added {len(result['added'])} papers from library"
                    )
                else:
                    filter_msg = f' matching "{lib_query}"' if lib_query else ""
                    click.echo(f"  {DIM}No matched library papers{filter_msg}.{RESET}")
        else:
            click.echo(f"  {DIM}Add papers: paperclip git add PMC123 bio_456{RESET}")
            click.echo(f"  {DIM}Or from library: paperclip git add --from-library{RESET}")
    except AuthError:
        click.echo(
            f"{RED}[error] Authentication failed (API key invalid).{RESET}", err=True
        )
        sys.exit(1)
    except ValueError as e:
        click.echo(f"{RED}[error] {e}{RESET}", err=True)
        sys.exit(1)


