def _repo_picker(repos: list[dict], active: str | None) -> int | None:
    """Interactive picker for repos. Returns selected index or None."""
    if not sys.stdin.isatty():
        click.echo(f"\n  {BOLD}Paper Repos{RESET} ({len(repos)})\n")
        for r in repos:
            marker = f"{GREEN}●{RESET}" if r["name"] == active else f"{DIM}○{RESET}"
            click.echo(
                f"  {marker} {BOLD}{r['name']}{RESET}  {DIM}({r['paper_count']} papers){RESET}"
            )
            if r["description"]:
                click.echo(f"    {DIM}{r['description']}{RESET}")
        click.echo()
        return None

    try:
        import termios
        import tty
    except (ImportError, AttributeError):
        return None

    n = len(repos)
    idx = 0
    for i, r in enumerate(repos):
        if r["name"] == active:
            idx = i
            break

    fd = sys.stdin.fileno()
    old = termios.tcgetattr(fd)

    def render(first: bool = False) -> None:
        import shutil

        cols = shutil.get_terminal_size((80, 24)).columns

        if not first:
            sys.stdout.write(f"\033[{n}A\r")
        for i, r in enumerate(repos):
            marker = f"{GREEN}●{RESET}" if r["name"] == active else f"{DIM}○{RESET}"
            papers = f"({r['paper_count']} papers)"
            name = r["name"]
            if i == idx:
                prefix = f"  › "
                # visible: prefix + "○ " + name + "  " + papers + "  " + desc
                used = len(prefix) + 2 + len(name) + 2 + len(papers)
            else:
                prefix = f"    "
                used = len(prefix) + 2 + len(name) + 2 + len(papers)

            desc_text = r.get("description") or ""
            if desc_text:
                max_desc = cols - used - 4
                if max_desc > 10:
                    desc_text = desc_text[:max_desc]
                    desc = f"  {DIM}{desc_text}{RESET}"
                else:
                    desc = ""
            else:
                desc = ""

            papers_fmt = f"{DIM}{papers}{RESET}"
            if i == idx:
                sys.stdout.write(
                    f"{CLR}  {CYAN}› {RESET}{marker} {BOLD}{name}{RESET}  {papers_fmt}{desc}\n"
                )
            else:
                sys.stdout.write(f"{CLR}    {marker} {name}  {papers_fmt}{desc}\n")
        sys.stdout.write(f"{CLR}  {DIM}↑/↓ navigate · enter select · q quit{RESET}")
        sys.stdout.flush()

    click.echo(f"\n  {BOLD}Paper Repos{RESET} ({n})\n")
    render(first=True)

    try:
        tty.setcbreak(fd)
        while True:
            ch = os.read(fd, 1)
            if ch == b"\x1b":
                b = os.read(fd, 1)
                if b == b"[":
                    arrow = os.read(fd, 1)
                    if arrow == b"A":
                        idx = (idx - 1) % n
                    elif arrow == b"B":
                        idx = (idx + 1) % n
                render()
            elif ch in (b"\r", b"\n"):
                sys.stdout.write("\n\n")
                sys.stdout.flush()
                return idx
            elif ch in (b"q", b"\x03"):
                sys.stdout.write("\n")
                sys.stdout.flush()
                return None
    finally:
        termios.tcsetattr(fd, termios.TCSADRAIN, old)


def _repo_claim_stats(info: dict, active: str | None) -> dict:
    """Summarize a repo's claims using repo-native, domain-agnostic terms.

    The paper repo is general-purpose: papers hold *claims* (annotations), each
    verified against cited lines on commit. This reports totals plus the
    verification breakdown ([OK]/[X]/[?]) and — data-driven, no hardcoded
    vocabulary — the distribution of any `type` field the claims carry, so a
    caller can see how many of each kind exist without the repo knowing what
    those kinds mean. (The meta-analysis skill maps its "effect size" onto a
    claim of type "effect"; that mapping lives in the skill, not here.)
    """
    import json as _json
    from collections import Counter

    total_claims = 0
    by_type: Counter = Counter()
    verified = failed = errored = unverified = 0

    verification: dict = {}
    if active and info.get("name") == active:
        try:
            from . import repo as _repo

            verification = (
                _repo.load_server_verification(active)
                or _repo.load_verification(active)
                or {}
            )
        except Exception:
            verification = {}

    for pid, pinfo in (info.get("papers") or {}).items():
        anns = pinfo.get("annotations") or []
        vlist = verification.get(pid) or []
        if isinstance(vlist, dict):
            vlist = [vlist]
        by_id = {
            str(v.get("claim_id")): v
            for v in vlist
            if isinstance(v, dict) and v.get("claim_id")
        }
        for i, a in enumerate(anns):
            total_claims += 1
            note = (a.get("note") or "").strip()
            if note.startswith("{"):
                try:
                    t = _json.loads(note).get("type")
                    if t:
                        by_type[str(t)] += 1
                except Exception:
                    pass
            claim_id = _stable_claim_id(pid, note, a)
            verdict = by_id.get(claim_id)
            if verdict is None and i < len(vlist):
                candidate = vlist[i]
                if isinstance(candidate, dict) and candidate.get("claim") == note:
                    verdict = candidate
            if verdict is not None:
                supported = verdict.get("supported")
                if supported is True:
                    verified += 1
                elif supported is None:
                    errored += 1
                else:
                    failed += 1
            else:
                unverified += 1

    return {
        "total_claims": total_claims,
        "by_type": dict(by_type),
        "verified": verified,
        "failed": failed,
        "errored": errored,
        "unverified": unverified,
        "has_verification": bool(verification),
    }


def _render_repo_detail(info: dict, active: str | None) -> None:
    """Render the full detail view for a repo."""
    marker = f"{GREEN}●{RESET} " if info["name"] == active else ""
    click.echo(f"\n  {marker}{BOLD}{info['name']}{RESET}")
    if info["description"]:
        click.echo(f"  {DIM}{info['description']}{RESET}")

    bd = _repo_claim_stats(info, active)
    stats = [
        f"{info['paper_count']} papers",
        f"{info['commit_count']} commits",
        f"{bd['total_claims']} claims",
    ]
    if info["branch_count"] > 1:
        stats.append(
            f"{info['branch_count']} branches (active: {info['active_branch']})"
        )
    else:
        stats.append(f"branch: {info['active_branch']}")
    click.echo(f"  {DIM}{' · '.join(stats)}{RESET}")

    # Verification breakdown — repo-native progress signal (from the last
    # commit's per-claim verification). Domain-agnostic: works for any repo.
    if bd["total_claims"]:
        if bd["has_verification"]:
            vparts = [f"{GREEN}{bd['verified']} verified [OK]{RESET}"]
            if bd["failed"]:
                vparts.append(f"{RED}{bd['failed']} failed [X]{RESET}")
            if bd["errored"]:
                vparts.append(f"{YELLOW}{bd['errored']} errored [!]{RESET}")
            if bd["unverified"]:
                vparts.append(f"{DIM}{bd['unverified']} unverified [?]{RESET}")
            click.echo(f"  {DIM}claims: {' · '.join(vparts)}{RESET}")
        else:
            click.echo(
                f"  {DIM}claims: {bd['unverified']} not yet verified "
                f"— run `paperclip git commit` to verify{RESET}"
            )
        # Data-driven claim-type distribution (whatever `type` values the
        # claims carry; the repo does not assign meaning to them).
        if bd["by_type"]:
            parts = ", ".join(f"{v} {k}" for k, v in sorted(bd["by_type"].items(), key=lambda kv: -kv[1]))
            click.echo(f"  {DIM}by type: {parts}{RESET}")

    if info.get("created_at"):
        created = info["created_at"][:16].replace("T", " ")
        all_ts = [info["created_at"]]
        for pinfo in info.get("papers", {}).values():
            if pinfo.get("added_at"):
                all_ts.append(pinfo["added_at"])
            for a in pinfo.get("annotations", []):
                if a.get("ts"):
                    all_ts.append(a["ts"])
        for srch in info.get("searches", []):
            if srch.get("timestamp"):
                all_ts.append(srch["timestamp"])
        last = max(all_ts)[:16].replace("T", " ")
        if last != created:
            click.echo(f"  {DIM}Created: {created} · Last activity: {last}{RESET}")
        else:
            click.echo(f"  {DIM}Created: {created}{RESET}")

    rule = f"  {DIM}{'─' * 50}{RESET}"

    # ── Commits ──
    commits = info.get("commits", [])
    if commits:
        click.echo(f"\n  {BOLD}Commits{RESET} ({len(commits)})")
        click.echo(rule)
        for c in reversed(commits[-10:]):
            sha = c.get("sha", "?")[:8]
            msg = c.get("message", "")
            ts = c.get("timestamp", "")[:16].replace("T", " ")
            added = c.get("added", [])
            removed = c.get("removed", [])
            delta_parts = []
            if added:
                delta_parts.append(f"{GREEN}+{len(added)}{RESET}")
            if removed:
                delta_parts.append(f"{RED}-{len(removed)}{RESET}")
            delta = f" ({', '.join(delta_parts)})" if delta_parts else ""
            click.echo(f"    {YELLOW}{sha}{RESET}  {msg}{delta}  {DIM}{ts}{RESET}")

    # ── Papers with notes ──
    papers = info.get("papers", {})
    if papers:
        annotated = {pid: p for pid, p in papers.items() if p.get("annotations")}
        matched_count = sum(1 for pid in papers if not pid.startswith("ref_"))
        total_count = len(papers)

        if matched_count < total_count:
            click.echo(
                f"\n  {BOLD}Papers{RESET} ({GREEN}{matched_count}{RESET}/{total_count} linked)"
            )
        else:
            click.echo(f"\n  {BOLD}Papers{RESET} ({total_count})")
        click.echo(rule)

        # Show annotated papers first
        if annotated:
            for pid, pinfo in list(annotated.items())[:15]:
                _render_paper_line(pid, pinfo)
            remaining_annotated = len(annotated) - 15
            if remaining_annotated > 0:
                click.echo(
                    f"    {DIM}... and {remaining_annotated} more with notes{RESET}"
                )

        # Show remaining papers (no notes) as a compact count
        unannotated_count = total_count - len(annotated)
        if unannotated_count > 0 and annotated:
            click.echo(
                f"    {DIM}+ {unannotated_count} more papers without notes{RESET}"
            )
        elif not annotated:
            for pid, pinfo in list(papers.items())[:15]:
                _render_paper_line(pid, pinfo)
            if total_count > 15:
                click.echo(f"    {DIM}... and {total_count - 15} more{RESET}")

    # ── Recent searches ──
    searches = info.get("searches", [])
    if searches:
        recent = searches[-5:]
        click.echo(f"\n  {BOLD}Recent searches{RESET} ({len(searches)} total)")
        click.echo(rule)
        for srch in recent:
            q = srch.get("query", "")
            rid = srch.get("result_id", "")
            ts = srch.get("timestamp", "")[:10]
            rid_str = f" → {CYAN}{rid}{RESET}" if rid else ""
            click.echo(f"    {DIM}{ts}{RESET}  {q}{rid_str}")

    if info["name"] != active:
        click.echo(f"\n  {DIM}Use: paperclip git checkout {info['name']}{RESET}")
    click.echo()


def _render_paper_line(pid: str, pinfo: dict) -> None:
    """Render a single paper line in repo detail view."""
    title = pinfo.get("title", "")
    authors = pinfo.get("authors", "")
    year = pinfo.get("pub_year") or pinfo.get("year")
    added_at = pinfo.get("added_at", "")
    cites = pinfo.get("cited_by_count")
    is_ref = pid.startswith("ref_")
    marker = f"{DIM}○{RESET}" if is_ref else f"{GREEN}✓{RESET}"
    line = f"    {marker} {CYAN}{pid}{RESET}"
    if title:
        line += f"  {title[:40]}"
    # Add author (first author + et al.)
    if authors:
        first_author = authors.split(",")[0].strip().split()[-1]
        author_str = f"{first_author} et al." if "," in authors else first_author
        line += f"  {DIM}·{RESET} {author_str}"
    # Add year
    if year:
        line += f" {DIM}({year}){RESET}"
    # Add added date
    if added_at:
        date_str = added_at[:10] if isinstance(added_at, str) else str(added_at)[:10]
        line += f"  {DIM}· added {date_str}{RESET}"
    tags = []
    anns = pinfo.get("annotations", [])
    if anns:
        tags.append(f"{len(anns)} note{'s' if len(anns) != 1 else ''}")
    if cites:
        tags.append(f"{cites} cites")
    if tags:
        line += f"  {DIM}[{', '.join(tags)}]{RESET}"
    click.echo(line)
    for a in anns[-2:]:
        loc = f" {a['lines']}" if a.get("lines") else ""
        click.echo(f"      {DIM}↳{loc} {a['note'][:60]}{RESET}")


@main.command("library")
@click.argument("paper_id", required=False, default=None)
@click.option(
    "--matched", is_flag=True, help="Show only matched (corpus-linked) papers"
)
@click.option("--unmatched", is_flag=True, help="Show only unmatched papers")
@click.option(
    "--rematch", is_flag=True, help="Re-run corpus matching on unmatched entries"
)
@click.option("--remove", is_flag=True, help="Remove a paper from the library")
@click.option(
    "-s",
    "--search",
    "query",
    default=None,
    help="Search library by keyword (title, authors, journal)",
)
def library_cmd(
    paper_id: str | None,
    matched: bool,
    unmatched: bool,
    rematch: bool,
    remove: bool,
    query: str | None,
):
    """View your personal paper library, or details for a single paper.

    \b
    The library stores every paper you've imported (from .bib/.ris files
    or paper references). Papers matched to the corpus show ✓; unmatched
    entries show ○ with their bib metadata preserved.

    \b
    Examples:
        paperclip library                     # show all imported papers
        paperclip library ref_abd3ed48        # view a specific paper's details
        paperclip library PMC11166971         # view a matched paper
        paperclip library --matched           # only corpus-linked papers
        paperclip library --unmatched         # only unmatched bib entries
        paperclip library -s "fine-tuning"    # search library by keyword
        paperclip library --rematch           # retry matching unmatched entries
        paperclip library --remove PMC123456  # remove a paper from the library
    """  # noqa: D301 — click needs \b for formatting
    if not _is_library_enabled():
        click.echo(f"{RED}[error] Library is not available yet.{RESET}", err=True)
        sys.exit(1)
    from . import repo

    if rematch:
        _library_rematch()
        return

    if remove:
        if not paper_id:
            click.echo(
                f"\n  {RED}Specify a paper ID to remove: paperclip library --remove <paper_id>{RESET}"
            )
            click.echo()
            return
        removed = repo.library_remove_papers([paper_id])
        if removed:
            click.echo(
                f"\n  {GREEN}✓{RESET} Removed {CYAN}{paper_id}{RESET} from library"
            )
        else:
            click.echo(f"\n  {DIM}Paper {paper_id} not found in library.{RESET}")
        click.echo()
        return

    if paper_id:
        _library_show_paper(paper_id)
        return

    info = repo.library_get_info()
    if info is None:
        click.echo(
            f"\n  {RED}[error] Could not load your library. Try again.{RESET}",
            err=True,
        )
        sys.exit(1)
    if info["total"] == 0:
        click.echo(f"\n  {DIM}Your library is empty.{RESET}")
        click.echo(f"  {DIM}Import papers: paperclip import refs.bib{RESET}")
        click.echo()
        return

    click.echo(f"\n  {BOLD}Personal Library{RESET}")
    click.echo(
        f"  {GREEN}{info['matched']}{RESET} matched · "
        f"{DIM}{info['unmatched']}{RESET} unmatched · "
        f"{info['total']} total"
    )

    papers = info.get("papers", {})
    if not papers:
        click.echo()
        return

    if matched:
        papers = {pid: p for pid, p in papers.items() if not pid.startswith("ref_")}
    elif unmatched:
        papers = {pid: p for pid, p in papers.items() if pid.startswith("ref_")}

    if query:
        q = query.lower()
        papers = {
            pid: p
            for pid, p in papers.items()
            if q in (p.get("title") or "").lower()
            or q in (p.get("authors") or "").lower()
            or q in (p.get("journal") or "").lower()
            or q in pid.lower()
        }
        if not papers:
            click.echo(f'\n  {DIM}No results for "{query}" in library.{RESET}')
            click.echo()
            return
        click.echo(f'  {DIM}Search: "{query}" → {len(papers)} results{RESET}')

    if not papers:
        label = "matched" if matched else "unmatched"
        click.echo(f"\n  {DIM}No {label} papers in library.{RESET}")
        click.echo()
        return

    click.echo()
    for i, (pid, pinfo) in enumerate(list(papers.items())[:30], 1):
        title = pinfo.get("title", "")
        authors = pinfo.get("authors", "")
        year = pinfo.get("pub_year") or pinfo.get("year") or ""
        journal = pinfo.get("journal", "")
        doi = pinfo.get("doi", "")
        is_ref = pid.startswith("ref_")
        marker = f"{DIM}○{RESET}" if is_ref else f"{GREEN}✓{RESET}"

        # First-author et al. format
        author_short = ""
        if authors:
            parts = [a.strip() for a in authors.split(" and ")]
            last = (
                parts[0].split(",")[0].strip()
                if "," in parts[0]
                else parts[0].split()[-1]
            )
            if len(parts) > 2:
                author_short = f"{last} et al."
            elif len(parts) == 2:
                last2 = (
                    parts[1].split(",")[0].strip()
                    if "," in parts[1]
                    else parts[1].split()[-1]
                )
                author_short = f"{last} & {last2}"
            else:
                author_short = last

        # "Rafailov et al. (2024). Direct preference optimization... Journal."
        ref_line = f"  {marker} "
        if author_short:
            ref_line += f"{author_short}"
            if year:
                ref_line += f" ({year})"
            ref_line += ". "
        elif year:
            ref_line += f"({year}) "
        if title:
            ref_line += f"{BOLD}{title}{RESET}"
        if journal:
            ref_line += f". {DIM}{journal}{RESET}"
        click.echo(ref_line)
        click.echo(
            f"    {CYAN}{pid}{RESET}" + (f"  {DIM}doi:{doi}{RESET}" if doi else "")
        )

    if len(papers) > 30:
        click.echo(f"\n  {DIM}... and {len(papers) - 30} more{RESET}")

    if info["unmatched"] > 0:
        click.echo(f"\n  {DIM}Re-run matching: paperclip library --rematch{RESET}")
    click.echo()
    if _is_paper_repos_enabled():
        click.echo(f"  {DIM}Add to repo:     paperclip git add --from-library{RESET}")
        click.echo(f"  {DIM}New repo:        paperclip git init <name> --from-library{RESET}")
    click.echo()


def _library_show_paper(paper_id: str):
    """Show full details for a single library paper."""
    from . import repo

    papers = repo.library_get_papers()

    # Support prefix matching for ref_ IDs
    info = papers.get(paper_id)
    resolved_id = paper_id
    if info is None:
        candidates = [pid for pid in papers if pid.startswith(paper_id)]
        if len(candidates) == 1:
            resolved_id = candidates[0]
            info = papers[resolved_id]
        elif len(candidates) > 1:
            click.echo(
                f"{YELLOW}Ambiguous — matches {len(candidates)} entries:{RESET}",
                err=True,
            )
            for c in candidates[:5]:
                click.echo(f"  {CYAN}{c}{RESET}  {papers[c].get('title', '')[:50]}")
            return
        else:
            click.echo(
                f"{RED}[error] '{paper_id}' not found in library.{RESET}", err=True
            )
            return

    is_ref = resolved_id.startswith("ref_")
    marker = f"{DIM}○ unmatched{RESET}" if is_ref else f"{GREEN}✓ corpus-linked{RESET}"

    click.echo(f"\n  {BOLD}{info.get('title') or resolved_id}{RESET}")
    click.echo(f"  {marker}")
    click.echo()

    fields = [
        ("ID", resolved_id),
        ("Authors", info.get("authors", "")),
        ("Journal", info.get("journal", "")),
        ("Year", str(info.get("pub_year") or info.get("year") or "")),
        ("DOI", info.get("doi", "")),
        ("Citations", info.get("cited_by_count", "")),
        ("Cite key", info.get("entry_key", "")),
        ("Source", info.get("import_source", "")),
        ("Added", (info.get("added_at") or "")[:16].replace("T", " ")),
    ]
    for label, value in fields:
        if value:
            val_str = str(value)
            if label == "DOI":
                val_str = f"{val_str}  {DIM}(https://doi.org/{val_str}){RESET}"
            click.echo(f"  {BOLD}{label}:{RESET}  {val_str}")

    if not is_ref:
        click.echo(
            f"\n  {DIM}Full text: paperclip cat /papers/{resolved_id}/meta.json{RESET}"
        )
        click.echo(
            f"  {DIM}Read:      paperclip head -50 /papers/{resolved_id}/content.lines{RESET}"
        )
    click.echo()


def _library_rematch():
    """Re-run corpus matching on unmatched library entries."""
    from . import repo
    from ._citations import match_bib_entries_in_corpus

    papers = repo.library_get_papers()
    unmatched = {pid: p for pid, p in papers.items() if pid.startswith("ref_")}

    if not unmatched:
        click.echo(f"\n  {DIM}No unmatched entries to re-match.{RESET}")
        click.echo()
        return

    click.echo(f"\n  {BOLD}Re-matching {len(unmatched)} unmatched entries...{RESET}\n")

    entries = []
    for pid, pinfo in unmatched.items():
        entries.append(
            {
                "title": pinfo.get("title", ""),
                "doi": pinfo.get("doi", ""),
                "authors": pinfo.get("authors", ""),
                "journal": pinfo.get("journal", ""),
                "year": pinfo.get("year") or pinfo.get("pub_year", ""),
                "entry_key": pinfo.get("entry_key", ""),
                "_original_ref_id": pid,
            }
        )

    def _on_progress(done: int, total: int, phase: str):
        click.echo(f"  {DIM}  Matching: {done}/{total} ({phase}){RESET}", err=True)

    try:
        results = match_bib_entries_in_corpus(entries, on_progress=_on_progress)
    except Exception as e:
        click.echo(f"{RED}[error] Matching failed: {e}{RESET}", err=True)
        return

    newly_matched = [e for e in results if e.get("corpus_id")]
    if not newly_matched:
        click.echo(f"\n  {DIM}No new matches found.{RESET}")
        click.echo()
        return

    new_ids = []
    new_titles: dict[str, str] = {}
    new_dois: dict[str, str] = {}
    new_meta: dict[str, dict] = {}
    old_ref_ids = []

    for e in newly_matched:
        cid = e["corpus_id"]
        old_ref = e.get("_original_ref_id", "")
        new_ids.append(cid)
        if e.get("title"):
            new_titles[cid] = e["title"]
        if e.get("doi"):
            new_dois[cid] = e["doi"]
        if old_ref:
            old_ref_ids.append(old_ref)
            old_info = unmatched.get(old_ref, {})
            new_meta[cid] = {
                "authors": e.get("authors") or old_info.get("authors", ""),
                "journal": e.get("journal") or old_info.get("journal", ""),
                "year": e.get("year")
                or old_info.get("year")
                or old_info.get("pub_year", ""),
                "entry_key": e.get("entry_key") or old_info.get("entry_key", ""),
                "source": "bib_import",
            }
        click.echo(
            f"  {GREEN}✓{RESET} {DIM}{old_ref}{RESET} → {CYAN}{cid}{RESET}  {e.get('title', '')[:50]}"
        )

    repo.library_add_papers(new_ids, titles=new_titles, dois=new_dois)
    if new_meta:
        repo.library_update_metadata(new_ids, new_meta)
    if old_ref_ids:
        repo.library_remove_papers(old_ref_ids)

    click.echo(
        f"\n  {GREEN}✓{RESET} Matched {len(newly_matched)} papers (replaced ref_ IDs with corpus IDs)"
    )
    click.echo()


@repo_cmd.command("checkout")
@click.argument("name", required=True)
def checkout_cmd(name: str):
    """Switch to a paper repo, or deactivate with '-'.

    Prefer ``checkout``. ``git switch`` is also accepted.

    \b
    Examples:
        paperclip git checkout kras-resistance   # activate repo
        paperclip git checkout main              # switch to branch (if active repo has it)
        paperclip git checkout -                 # deactivate (back to global)
    """
    from . import repo

    if name == "-":
        repo.set_active_repo(None)
        click.echo(
            f"{GREEN}✓{RESET} Deactivated repo. Commands now run against the full corpus."
        )
        return

    # Try switching branch first if there's an active repo
    active = repo.get_active_repo()
    if active:
        branches = repo.list_branches()
        branch_names = {b["name"] for b in branches}
        if name in branch_names:
            try:
                result = repo.switch_branch(name)
                click.echo(
                    f"{GREEN}●{RESET} Switched to branch: {BOLD}{result['branch']}{RESET} ({result['paper_count']} papers)"
                )
            except ValueError as e:
                click.echo(f"{RED}[error] {e}{RESET}", err=True)
                sys.exit(1)
            return

    # Otherwise switch repo
    try:
        doc = repo.checkout_repo(name)
        branch = doc.get("active_branch", "main")
        bd = doc.get("branches", {}).get(branch, {})
        n = len(bd.get("papers", {}))
        click.echo(
            f"{GREEN}●{RESET} Active repo: {BOLD}{doc.get('name', name)}{RESET} ({n} papers, branch: {branch})"
        )
        click.echo(
            f"  {DIM}All commands now tagged here. Use --repo-only to restrict search/map.{RESET}"
        )
    except AuthError:
        click.echo(
            f"{RED}[error] Authentication failed (API key invalid).{RESET}", err=True
        )
        sys.exit(1)
    except ValueError as e:
        click.echo(f"{RED}[error] {e}{RESET}", err=True)
        sys.exit(1)


def _validate_structured_claim(body: str) -> dict:
    """Validate a ``--json`` claim body and return the parsed object.

    Domain-agnostic contract for a structured claim: it must be a JSON object
    carrying a non-empty string ``type`` (the discriminator ``repo claims
    --type`` and downstream compile steps filter on). This intentionally does
    NOT inspect any type-specific fields (e.g. ``effect_size``) — enforcing the
    per-type schema is the caller's/skill's job. Raises ``ValueError`` with a
    human-readable reason on any violation so callers can fail loud.
    """
    import json as _json

    try:
        obj = _json.loads(body)
    except _json.JSONDecodeError as exc:
        raise ValueError(f"not valid JSON ({exc})")
    if not isinstance(obj, dict):
        raise ValueError(f"must be a JSON object, got {type(obj).__name__}")
    t = obj.get("type")
    if not isinstance(t, str) or not t.strip():
        raise ValueError('missing required non-empty string field "type"')
    return obj


@repo_cmd.command("add")
@click.argument("paper_ids", nargs=-1, required=False)
@click.option(
    "--lines",
    "lines",
    default=None,
    help="Line range hint for claim verification (e.g. L45-L52).",
)
@click.option(
    "--commit",
    "commit_msg",
    default=None,
    help="Auto-commit after adding papers, with this message.",
)
@click.option(
    "--repo",
    "inline_repo",
    default=None,
    hidden=True,
    help="Alias for global --repo flag (agents sometimes put --repo after add)",
)
@click.option(
    "--from-library",
    "from_library",
    is_flag=True,
    help="Add matched papers from your library to the active repo",
)
@click.option(
    "-s",
    "--search",
    "lib_query",
    default=None,
    help="Filter library papers by keyword (with --from-library)",
)
@click.option(
    "--json",
    "as_json",
    is_flag=True,
    help=(
        "Treat the claim as a structured JSON object and validate it before "
        "storing (must be a JSON object with a non-empty string 'type'). "
        "Fails loudly on malformed JSON instead of storing an unusable claim."
    ),
)
def add_cmd(
    paper_ids: tuple,
    lines: str | None,
    commit_msg: str | None,
    inline_repo: str | None,
    from_library: bool,
    lib_query: str | None,
    as_json: bool,
):
    """Add papers to the active repo, optionally with a verifiable claim.

    \b
    Examples:
        paperclip git add PMC123 bio_456
        paperclip git add PMC123 "Hypertonic saline reduces cold duration by 1.9 days"
        paperclip git add PMC123 "Saline shortens URTI by 1.5 days" --lines L45-L52
        paperclip git add PMC123 --json '{"type":"effect","effect_id":"PMC123#orr","effect_size":0.74}' --lines L45
        paperclip git add PMC123
        paperclip git add --from-library
        paperclip git add --from-library -s "proteomics"

    \b
    When a claim string is provided after the paper ID, it is stored as an
    annotation to be verified on commit. A paper can have multiple claims
    (call add multiple times with the same ID and different claims).
    """
    from . import repo

    if inline_repo:
        repo.set_repo_override(inline_repo)
        try:
            repo.checkout_repo(inline_repo)
        except ValueError:
            pass

    if not repo.get_active_repo():
        click.echo(
            f"{RED}[error] No repo selected. Pass --repo <name> (or export PAPERCLIP_REPO=<name>); create one with: paperclip git init <name>{RESET}", err=True
        )
        sys.exit(1)

    if from_library:
        _add_from_library(lib_query)
        return

    if not paper_ids:
        click.echo(
            f"{RED}[error] Provide paper IDs or use --from-library{RESET}", err=True
        )
        sys.exit(1)

    # Separate paper IDs from an inline claim string.
    # Convention: first arg(s) that look like paper IDs (start with PMC, bio_, med_,
    # arx_, fda_, tri_, or match known patterns) are IDs; the remaining trailing
    # argument is treated as a claim.
    ids: list[str] = []
    claim: str | None = None
    for arg in paper_ids:
        if claim is not None:
            claim += " " + arg
        elif _looks_like_paper_id(arg):
            ids.append(arg)
        else:
            claim = arg

    if not ids:
        click.echo(
            f"{RED}[error] No valid paper IDs found in arguments.{RESET}", err=True
        )
        sys.exit(1)

    # --json: validate the claim body up front so a malformed structured claim
    # fails loudly at collection instead of being silently dropped downstream
    # (an unstructured claim verifies fine but is never compiled/pooled).
    if as_json:
        if not claim:
            click.echo(
                f"{RED}[error] --json requires a claim body after the paper id, "
                f"e.g. paperclip git add {ids[0]} --json '{{\"type\":\"effect\",...}}'{RESET}",
                err=True,
            )
            sys.exit(1)
        try:
            _validate_structured_claim(claim)
        except ValueError as exc:
            click.echo(
                f"{RED}[error] --json claim is invalid: {exc}{RESET}\n"
                f"{DIM}  A structured claim must be a JSON object with a non-empty "
                f'"type" field, e.g. \'{{"type":"effect", ...}}\'.{RESET}',
                err=True,
            )
            sys.exit(1)

    # Parse --lines into a list
    lines_list: list[str] | None = None
    if lines:
        lines_list = [l.strip() for l in lines.replace(",", " ").split() if l.strip()]

    try:
        result = repo.add_papers(ids)
        if result["added"]:
            for pid in result["added"]:
                click.echo(f"  {GREEN}+{RESET} {pid}")
            click.echo(
                f"{DIM}  {len(result['added'])} added, {result['total']} total{RESET}"
            )

            # Fetch DOIs + citation counts in one call (internal OpenAlex DB)
            try:
                enrichment = repo.lookup_citations(result["added"])
                new_dois = enrichment.get("dois") or {}
                counts = enrichment.get("counts") or {}
                if new_dois:
                    repo.update_paper_dois(new_dois)
                if counts:
                    repo.update_paper_citations(
                        {pid: {"paper_id": pid, "cited_by_count": c} for pid, c in counts.items()}
                    )
                    top_pid = max(counts, key=counts.get)
                    click.echo(
                        f"{DIM}  {len(new_dois)} DOIs + {len(counts)} citation counts"
                        f"  (top: {counts[top_pid]:,} cites){RESET}"
                    )
                elif new_dois:
                    click.echo(f"{DIM}  {len(new_dois)} DOIs stored{RESET}")
            except Exception:
                pass
        else:
            click.echo(
                f"{DIM}  Already in repo ({result['total']} total){RESET}"
            )

        # Annotate with claim if provided — always annotate all requested IDs,
        # not just newly added ones, so re-adding with a new claim works.
        if claim:
            target_ids = ids

            def _attach(pid: str):
                try:
                    repo.annotate_paper(pid, claim, lines=lines_list)
                    return (pid, None)
                except ValueError as exc:
                    return (pid, exc)

            # Attaching the same claim to many papers is independent per paper
            # (distinct entries, row-locked server-side), so fan out when there's
            # more than one. ex.map preserves input order for stable output.
            if len(target_ids) > 1:
                import os as _os
                from concurrent.futures import ThreadPoolExecutor as _TPE

                try:
                    add_jobs = int(_os.getenv("PAPERCLIP_ADD_JOBS", "8"))
                except ValueError:
                    add_jobs = 8
                add_jobs = max(1, min(add_jobs, len(target_ids)))
                with _TPE(max_workers=add_jobs) as _ex:
                    attach_results = list(_ex.map(_attach, target_ids))
            else:
                attach_results = [_attach(pid) for pid in target_ids]

            for pid, exc in attach_results:
                if exc is None:
                    lines_hint = f" {DIM}({lines}){RESET}" if lines else ""
                    click.echo(
                        f"  {DIM}↳ {pid}: \"{claim[:80]}\"{lines_hint}{RESET}"
                    )
                else:
                    # Never drop a claim silently — a swallowed failure here
                    # means the claim is never verified and never pooled.
                    click.echo(
                        f"  {RED}[warn] could not attach claim to {pid}: {exc}{RESET}",
                        err=True,
                    )

        if commit_msg:
            try:
                commit_result = repo.commit(commit_msg)
                click.echo(
                    f"  {DIM}committed: {commit_msg} "
                    f"[{commit_result.get('sha', '')[:8]}]{RESET}"
                )
            except Exception:
                pass
    except AuthError:
        click.echo(
            f"{RED}[error] Authentication failed (API key invalid).{RESET}", err=True
        )
        sys.exit(1)
    except ValueError as e:
        click.echo(f"{RED}[error] {e}{RESET}", err=True)
        sys.exit(1)


def _looks_like_paper_id(arg: str) -> bool:
    """Heuristic: return True if arg looks like a paper/document ID."""
    prefixes = ("PMC", "bio_", "med_", "arx_", "fda_", "tri_", "NCT")
    if any(arg.startswith(p) for p in prefixes):
        return True
    # UUID (e.g. bioRxiv document_id resolved from DOI)
    if re.match(r"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$", arg):
        return True
    # Pure numeric (PMID) or alphanumeric with underscores (custom IDs)
    if re.match(r"^[A-Za-z0-9_-]+$", arg) and not " " in arg and len(arg) <= 30:
        return True
    return False


def _add_from_library(query: str | None = None) -> None:
    """Add matched library papers to the active repo, optionally filtered by keyword."""
    from . import repo

    papers = repo.library_get_papers()
    if not papers:
        click.echo(
            f"  {DIM}Library is empty. Import a .bib file first: paperclip import refs.bib{RESET}"
        )
        return

    corpus_papers = {pid: p for pid, p in papers.items() if not pid.startswith("ref_")}
    if query:
        q = query.lower()
        corpus_papers = {
            pid: p
            for pid, p in corpus_papers.items()
            if q in (p.get("title", "") or "").lower()
            or q in (p.get("authors", "") or "").lower()
            or q in (p.get("journal", "") or "").lower()
        }

    if not corpus_papers:
        filter_msg = f' matching "{query}"' if query else ""
        unmatched = sum(1 for pid in papers if pid.startswith("ref_"))
        click.echo(f"  {DIM}No matched library papers{filter_msg}.{RESET}")
        if unmatched:
            click.echo(
                f"  {DIM}{unmatched} unmatched entries — try: paperclip library --rematch{RESET}"
            )
        return

    titles = {pid: p["title"] for pid, p in corpus_papers.items() if p.get("title")}
    dois = {pid: p["doi"] for pid, p in corpus_papers.items() if p.get("doi")}
    result = repo.add_papers(list(corpus_papers.keys()), titles=titles, dois=dois)

    meta = {}
    for pid, p in corpus_papers.items():
        m = {}
        for k in (
            "authors",
            "journal",
            "year",
            "pub_year",
            "cited_by_count",
            "entry_key",
            "source",
        ):
            if p.get(k):
                m[k] = p[k]
        if m:
            meta[pid] = m
    if meta:
        repo.update_paper_metadata(meta)

    if result["added"]:
        click.echo(
            f"  {GREEN}+{RESET} Added {len(result['added'])} papers from library ({result['total']} total in repo)"
        )
        for pid in result["added"][:10]:
            title = titles.get(pid, "")
            line = f"    {CYAN}{pid}{RESET}"
            if title:
                line += f"  {title[:50]}"
            click.echo(line)
        if len(result["added"]) > 10:
            click.echo(f"    {DIM}... and {len(result['added']) - 10} more{RESET}")
    else:
        click.echo(
            f"  {DIM}All library papers already in repo ({result['total']} total){RESET}"
        )


@main.command("import")
@click.argument("source")
@click.option("--doi", default=None, help="Paper DOI (skips DOI lookup if provided)")
@click.option("--limit", "-n", default=None, type=int, help="Max references to add")
@click.option(
    "--min-cites",
    default=0,
    type=int,
    help="Only include refs with at least N citations",
)
@click.option("--dry-run", is_flag=True, help="Show matches without adding to repo")
@click.option(
    "--init", "init_repo_name", default=None,
    help="Create a new repo from the file",
    hidden=not _is_paper_repos_enabled(),
)
@click.option(
    "--add-to-repo", is_flag=True,
    help="Also add imported papers to the active repo",
    hidden=not _is_paper_repos_enabled(),
)
@click.option(
    "--into", "into_clipboard",
    default=None,
    help="Import into a clipboard folder as corpus links (e.g. --into /clipboard/thesis-refs)",
)
def import_cmd(
    source: str,
    doi: str | None,
    limit: int | None,
    min_cites: int,
    dry_run: bool,
    init_repo_name: str | None,
    add_to_repo: bool,
    into_clipboard: str | None,
):
    """Import from PDFs, a .bib/.ris file, or a paper's references.

    \b
    From PDF files (uploads to your personal library):
        paperclip import paper.pdf
        paperclip import ~/papers/              # all PDFs in directory (recursive)
        paperclip import ~/papers/ --dry-run
        paperclip import ~/papers/ --add-to-repo
        paperclip import ~/papers/ --init my-review

    \b
    From a bibliography file (imports to your personal library):
        paperclip import refs.bib
        paperclip import refs.ris
        paperclip import refs.bib --dry-run
        paperclip import refs.bib --init my-review
        paperclip import refs.bib --add-to-repo
        paperclip import refs.bib --into /clipboard/thesis-refs

    \b
    From a paper (via Semantic Scholar):
        paperclip import PMC11282385
        paperclip import PMC11282385 --min-cites 50
        paperclip import PMC11282385 --dry-run

    Papers go into your personal library first. Use --add-to-repo to also
    add them to the active repo, or --init to create a new repo and add
    papers to both library and repo. Use --into to create corpus links
    in a clipboard folder (matched papers become symbolic links, unmatched
    become metadata-only entries).
    Matched entries get their corpus paper ID. Unmatched entries are
    still stored with all available metadata (title, authors,
    year, DOI, journal) so you can search and export them.
    """
    if not _is_library_enabled():
        click.echo(f"{RED}[error] Import is not available yet.{RESET}", err=True)
        sys.exit(1)

    repos_enabled = _is_paper_repos_enabled()
    if not repos_enabled and (init_repo_name or add_to_repo):
        click.echo(
            f"{RED}[error] --init and --add-to-repo require paper repositories.{RESET}",
            err=True,
        )
        click.echo(
            f"{DIM}Run {RESET}{BOLD}paperclip repos-feature enable{RESET}"
            f"{DIM}, then try again.{RESET}",
            err=True,
        )
        sys.exit(2)

    source_path = Path(source).expanduser()

    if source_path.is_dir() or source.lower().endswith(".pdf"):
        _import_pdfs(
            source_path,
            dry_run=dry_run,
            init_name=init_repo_name,
            add_to_repo=add_to_repo,
        )
    elif source.endswith(".bib") or source.endswith(".ris"):
        _import_bib_file(
            source,
            dry_run=dry_run,
            init_name=init_repo_name,
            limit=limit,
            add_to_repo=add_to_repo,
            into_clipboard=into_clipboard,
        )
    else:
        if not repos_enabled:
            click.echo(
                f"{RED}[error] Importing a paper's references requires paper repositories.{RESET}",
                err=True,
            )
            click.echo(
                f"{DIM}BibTeX, RIS, and PDF imports still work without repositories. "
                f"To enable this mode, run {RESET}{BOLD}paperclip repos-feature enable{RESET}{DIM}.{RESET}",
                err=True,
            )
            sys.exit(2)
        if init_repo_name:
            click.echo(f"{RED}[error] --init is only for file imports{RESET}", err=True)
            sys.exit(1)
        _import_from_paper(
            source, doi=doi, limit=limit, min_cites=min_cites, dry_run=dry_run
        )


def _import_from_paper(
    paper_id: str, *, doi: str | None, limit: int | None, min_cites: int, dry_run: bool
):
    """Original import: seed a repo from a paper's Semantic Scholar references."""
    from . import repo
    from ._citations import get_paper_references, match_references_in_corpus

    if not dry_run and not repo.get_active_repo():
        click.echo(
            f"{RED}[error] No repo selected. Pass --repo <name> (or export PAPERCLIP_REPO=<name>); create one with: paperclip git init <name>{RESET}", err=True
        )
        sys.exit(1)

    click.echo(f"  {DIM}Fetching references for {paper_id}...{RESET}", err=True)
    try:
        refs = get_paper_references(paper_id, known_doi=doi)
    except ValueError as e:
        click.echo(f"{RED}[error] {e}{RESET}", err=True)
        sys.exit(1)

    if not refs:
        click.echo(f"{DIM}No references found for {paper_id}.{RESET}")
        return

    click.echo(
        f"  {DIM}Found {len(refs)} references. Matching against corpus...{RESET}",
        err=True,
    )

    try:
        refs = match_references_in_corpus(refs)
    except Exception as e:
        click.echo(f"{RED}[error] Matching failed: {e}{RESET}", err=True)
        sys.exit(1)

    if min_cites > 0:
        refs = [r for r in refs if r.get("citation_count", 0) >= min_cites]

    matched = [r for r in refs if r.get("corpus_id")]
    unmatched = [r for r in refs if not r.get("corpus_id")]

    if not matched:
        click.echo(
            f"\n  {DIM}No references found in the corpus (out of {len(refs)} total).{RESET}"
        )
        if unmatched[:5]:
            click.echo(f"\n  {BOLD}Top unmatched references:{RESET}")
            for r in sorted(
                unmatched, key=lambda x: x.get("citation_count", 0), reverse=True
            )[:5]:
                cites = r.get("citation_count", 0)
                title = r.get("title", "")[:60]
                click.echo(f"    {DIM}{cites:>5} cites{RESET}  {title}")
        return

    matched.sort(key=lambda x: x.get("citation_count", 0), reverse=True)
    if limit:
        matched = matched[:limit]

    click.echo(
        f"\n  {BOLD}Matched {len(matched)}{RESET} of {len(refs)} references in corpus\n"
    )

    for r in matched:
        cites = r.get("citation_count", 0)
        title = r.get("title", "")[:55]
        year = r.get("year") or "?"
        cid = r["corpus_id"]
        click.echo(
            f"  {GREEN}+{RESET} {CYAN}{cid}{RESET}  {cites:>5} cites  {year}  {title}"
        )

    if unmatched:
        click.echo(
            f"\n  {DIM}{len(unmatched)} references not in corpus (preprints, books, older papers){RESET}"
        )

    if dry_run:
        click.echo(
            f"\n  {DIM}Dry run — no papers added. Remove --dry-run to add.{RESET}"
        )
        return

    ids_to_add = [r["corpus_id"] for r in matched]
    titles_map = {r["corpus_id"]: r.get("title", "") for r in matched}
    dois_map = {r["corpus_id"]: r["doi"] for r in matched if r.get("doi")}

    # Write to personal library first
    try:
        repo.library_add_papers(
            ids_to_add, titles=titles_map, dois=dois_map, source_file=f"refs:{paper_id}"
        )
    except Exception:
        pass

    try:
        result = repo.add_papers(ids_to_add, titles=titles_map, dois=dois_map)
        added = result.get("added", [])
        click.echo(
            f"\n  {GREEN}✓{RESET} Added {len(added)} papers ({result['total']} total in repo)"
        )
        if len(ids_to_add) > len(added):
            click.echo(f"  {DIM}{len(ids_to_add) - len(added)} already in repo{RESET}")

        try:
            cite_data = {}
            for r in matched:
                if r.get("corpus_id"):
                    cite_data[r["corpus_id"]] = {
                        "paper_id": r["corpus_id"],
                        "cited_by_count": r.get("citation_count", 0),
                        "title": r.get("title", ""),
                        "pub_year": r.get("year"),
                        "doi": r.get("doi", ""),
                        "s2_id": r.get("s2_id", ""),
                    }
            if cite_data:
                repo.update_paper_citations(cite_data)
        except Exception:
            pass

    except ValueError as e:
        click.echo(f"{RED}[error] {e}{RESET}", err=True)
        sys.exit(1)


# ── PDF import ────────────────────────────────────────────────────

_MAX_PDF_BATCH_FILES = 20
# Batches POST as one multipart request through Cloud Run's HTTP/1 ingress,
# which caps requests at 32 MiB — keep batches safely under that.
_MAX_PDF_BATCH_BYTES = 30 * 1024 * 1024  # 30 MB


def _collect_pdfs(source: Path) -> list[Path]:
    """Collect PDF file paths from a single file or directory (recursive)."""
    if source.is_file():
        if not source.suffix.lower() == ".pdf":
            click.echo(f"{RED}[error] Not a PDF file: {source}{RESET}", err=True)
            sys.exit(1)
        return [source]

    if not source.is_dir():
        click.echo(f"{RED}[error] Path not found: {source}{RESET}", err=True)
        sys.exit(1)

    pdfs = sorted(source.rglob("*.pdf"))
    pdf_lower = sorted(source.rglob("*.PDF"))
    seen = {p.resolve() for p in pdfs}
    for p in pdf_lower:
        if p.resolve() not in seen:
            pdfs.append(p)
            seen.add(p.resolve())
    return pdfs


def _batch_pdfs(
    paths: list[Path],
) -> list[list[Path]]:
    """Split paths into batches respecting server limits."""
    batches: list[list[Path]] = []
    current: list[Path] = []
    current_size = 0

    for p in paths:
        size = p.stat().st_size
        if current and (
            len(current) >= _MAX_PDF_BATCH_FILES
            or current_size + size > _MAX_PDF_BATCH_BYTES
        ):
            batches.append(current)
            current = []
            current_size = 0
        current.append(p)
        current_size += size

    if current:
        batches.append(current)
    return batches


def _import_pdfs(
    source: Path,
    *,
    dry_run: bool,
    init_name: str | None,
    add_to_repo: bool = False,
):
    """Import PDF files into the personal library."""
    from . import repo

    if not repo.validate_auth():
        click.echo(
            f"{RED}[error] Authentication failed (invalid credentials).{RESET}",
            err=True,
        )
        sys.exit(1)

    pdfs = _collect_pdfs(source)
    if not pdfs:
        click.echo(f"{DIM}No PDF files found in {source}{RESET}")
        return

    total_bytes = sum(p.stat().st_size for p in pdfs)
    label = f"from {source.name}/" if source.is_dir() else source.name
    click.echo(
        f"\n  {BOLD}Found {len(pdfs)} PDF{'s' if len(pdfs) != 1 else ''}{RESET}"
        f" {DIM}({total_bytes / 1024 / 1024:.1f} MB, {label}){RESET}\n"
    )

    for i, p in enumerate(pdfs[:20], 1):
        size_kb = p.stat().st_size / 1024
        click.echo(f"    {CYAN}{i:>3}.{RESET} {p.name}  {DIM}({size_kb:.0f} KB){RESET}")
    if len(pdfs) > 20:
        click.echo(f"    {DIM}... and {len(pdfs) - 20} more{RESET}")

    if dry_run:
        click.echo(
            f"\n  {DIM}Dry run — no files uploaded. Remove --dry-run to import.{RESET}"
        )
        return

    batches = _batch_pdfs(pdfs)
    client = _get_client()

    total_added = 0
    total_matched = 0
    total_skipped = 0
    all_errors: list[str] = []
    all_added_refs: list[dict] = []

    for batch_idx, batch in enumerate(batches):
        if len(batches) > 1:
            click.echo(
                f"\n  {DIM}Uploading batch {batch_idx + 1}/{len(batches)}"
                f" ({len(batch)} files)...{RESET}",
                err=True,
            )
        else:
            click.echo(
                f"\n  {DIM}Uploading {len(batch)} file{'s' if len(batch) != 1 else ''}...{RESET}",
                err=True,
            )

        files_data: list[tuple[str, bytes]] = []
        for p in batch:
            files_data.append((p.name, p.read_bytes()))

        try:
            start_resp = client.library.upload_pdfs(files_data)
        except AuthError:
            click.echo(
                f"{RED}[error] Authentication failed (API key invalid).{RESET}",
                err=True,
            )
            sys.exit(1)
        except (ServerError, RequestTimeoutError) as e:
            click.echo(f"{RED}[error] Upload failed: {e}{RESET}", err=True)
            sys.exit(1)

        job_id = str(start_resp.get("job_id", ""))
        if not job_id:
            click.echo(f"{RED}[error] Server did not return a job ID.{RESET}", err=True)
            sys.exit(1)

        last_pct = -1

        def _on_progress(processed: int, total: int) -> None:
            # Carriage-return progress is for a TTY; suppress under MCP so the
            # control characters don't pollute the returned output.
            if _is_mcp_mode():
                return
            nonlocal last_pct
            pct = int(100 * processed / total) if total else 0
            if pct != last_pct:
                last_pct = pct
                click.echo(
                    f"\r  {DIM}Processing… {processed}/{total} ({pct}%){RESET}",
                    nl=False,
                    err=True,
                )

        try:
            result = client.library.poll_import_job(job_id, on_progress=_on_progress)
        except (ServerError, RequestTimeoutError) as e:
            click.echo(f"\n{RED}[error] Import failed: {e}{RESET}", err=True)
            sys.exit(1)
        finally:
            click.echo("", err=True)

        total_added += int(result.get("papers_added", 0))
        total_skipped += int(result.get("papers_skipped", 0))
        batch_errors = result.get("errors") or []
        all_errors.extend(batch_errors)
        added_papers = result.get("added_papers") or []
        all_added_refs.extend(added_papers)

    click.echo(
        f"\n  {GREEN}✓{RESET} {BOLD}{total_added} paper{'s' if total_added != 1 else ''} imported{RESET}"
    )
    if total_skipped:
        click.echo(f"  {DIM}{total_skipped} skipped (already in library){RESET}")

    if all_errors:
        click.echo(
            f"\n  {RED}{len(all_errors)} error{'s' if len(all_errors) != 1 else ''}:{RESET}"
        )
        for err in all_errors[:10]:
            click.echo(f"    {DIM}{err}{RESET}")
        if len(all_errors) > 10:
            click.echo(f"    {DIM}... and {len(all_errors) - 10} more{RESET}")

    # Add to repo if requested
    if init_name:
        try:
            repo.init_repo(init_name, f"Imported PDFs from {source.name}")
            click.echo(f"  {GREEN}✓{RESET} Created repo: {BOLD}{init_name}{RESET}")
        except ValueError as e:
            click.echo(f"{RED}[error] {e}{RESET}", err=True)
            sys.exit(1)

    active = repo.get_active_repo()
    if active and (add_to_repo or init_name) and all_added_refs:
        paper_ids = [r.get("paper_id", "") for r in all_added_refs if r.get("paper_id")]
        titles_map = {
            r["paper_id"]: r["title"]
            for r in all_added_refs
            if r.get("paper_id") and r.get("title")
        }
        dois_map = {
            r["paper_id"]: r["doi"]
            for r in all_added_refs
            if r.get("paper_id") and r.get("doi")
        }
        if paper_ids:
            try:
                result = repo.add_papers(paper_ids, titles=titles_map, dois=dois_map)
                added_count = len(result.get("added", []))
                click.echo(
                    f"  {GREEN}✓{RESET} Also added {added_count} to repo"
                    f" '{active}' ({result['total']} total)"
                )
            except ValueError:
                pass
    elif active and not add_to_repo and not init_name and all_added_refs:
        if _is_paper_repos_enabled():
            click.echo(
                f"  {DIM}Tip: Use --add-to-repo to also add to repo '{active}'{RESET}"
            )
    elif not active and not init_name and all_added_refs:
        if _is_paper_repos_enabled():
            click.echo(
                f"  {DIM}Tip: paperclip git init <name> to create a repo, then paperclip git add --from-library{RESET}"
            )

    click.echo(f"\n  {DIM}View: paperclip library{RESET}")


def _import_bib_file(
    filepath: str,
    *,
    dry_run: bool,
    init_name: str | None,
    limit: int | None,
    add_to_repo: bool = False,
    into_clipboard: str | None = None,
):
    """Import papers from a .bib or .ris file into the personal library."""
    from . import repo
    from ._bibparse import make_ref_id, parse_file
    from ._citations import match_bib_entries_in_corpus

    # Validate authentication before any work
    if not repo.validate_auth():
        click.echo(
            f"{RED}[error] Authentication failed (invalid credentials).{RESET}",
            err=True,
        )
        sys.exit(1)

    # Parse the file
    try:
        entries = parse_file(filepath)
    except (ValueError, FileNotFoundError, OSError) as e:
        click.echo(f"{RED}[error] {e}{RESET}", err=True)
        sys.exit(1)

    if not entries:
        click.echo(f"{DIM}No entries found in {filepath}.{RESET}")
        return

    fname = Path(filepath).name
    click.echo(f"\n  {BOLD}Parsed {len(entries)} entries{RESET} from {fname}\n")

    # Match against corpus
    def _on_progress(done: int, total: int, phase: str):
        click.echo(f"  {DIM}  Matching: {done}/{total} ({phase}){RESET}", err=True)

    click.echo(f"  {DIM}Matching against paper corpus...{RESET}", err=True)
    try:
        entries = match_bib_entries_in_corpus(entries, on_progress=_on_progress)
    except Exception as e:
        click.echo(f"{RED}[error] Matching failed: {e}{RESET}", err=True)
        sys.exit(1)

    matched = [e for e in entries if e.get("corpus_id")]
    unmatched = [e for e in entries if not e.get("corpus_id")]

    if limit:
        matched = matched[:limit]
        unmatched = unmatched[: max(0, limit - len(matched))]

    # Display results
    click.echo(
        f"\n  {BOLD}Results:{RESET} {GREEN}{len(matched)} matched{RESET}, "
        f"{YELLOW}{len(unmatched)} unmatched{RESET} of {len(entries)} entries\n"
    )

    if matched:
        click.echo(f"  {BOLD}Matched (full text available):{RESET}")
        for e in matched[:20]:
            title = e.get("title", "")[:50]
            year = e.get("year", "?")
            click.echo(
                f"    {GREEN}✓{RESET} {CYAN}{e['corpus_id']}{RESET}  {year}  {title}"
            )
        if len(matched) > 20:
            click.echo(f"    {DIM}... and {len(matched) - 20} more{RESET}")

    if unmatched:
        click.echo(f"\n  {BOLD}Unmatched (metadata only, no full text):{RESET}")
        for e in unmatched[:10]:
            title = e.get("title", "")[:50]
            year = e.get("year", "?")
            ref_id = make_ref_id(e)
            click.echo(f"    {YELLOW}○{RESET} {DIM}{ref_id}{RESET}  {year}  {title}")
        if len(unmatched) > 10:
            click.echo(f"    {DIM}... and {len(unmatched) - 10} more{RESET}")

    if dry_run:
        click.echo(
            f"\n  {DIM}Dry run — no papers added. Remove --dry-run to add.{RESET}"
        )
        return

    # ── Write to personal library ──
    all_ids = []
    all_titles: dict[str, str] = {}
    all_dois: dict[str, str] = {}
    all_meta: dict[str, dict] = {}

    for e in matched:
        cid = e["corpus_id"]
        all_ids.append(cid)
        if e.get("title"):
            all_titles[cid] = e["title"]
        if e.get("doi"):
            all_dois[cid] = e["doi"]
        if e.get("authors") or e.get("journal"):
            all_meta[cid] = {
                "authors": e.get("authors", ""),
                "journal": e.get("journal", ""),
                "year": e.get("year", ""),
                "entry_key": e.get("entry_key", ""),
                "source": "bib_import",
            }

    for e in unmatched:
        ref_id = make_ref_id(e)
        all_ids.append(ref_id)
        if e.get("title"):
            all_titles[ref_id] = e["title"]
        if e.get("doi"):
            all_dois[ref_id] = e["doi"]
        all_meta[ref_id] = {
            "authors": e.get("authors", ""),
            "journal": e.get("journal", ""),
            "year": e.get("year", ""),
            "entry_key": e.get("entry_key", ""),
            "source": "bib_import",
        }

    try:
        lib_result = repo.library_add_papers(
            all_ids,
            titles=all_titles,
            dois=all_dois,
            source_file=fname,
        )
    except AuthError:
        click.echo(
            f"{RED}[error] Authentication failed (API key invalid).{RESET}", err=True
        )
        sys.exit(1)
    except PaperclipError as exc:
        click.echo(
            f"{RED}[error] Could not add papers to the library: {exc}{RESET}",
            err=True,
        )
        sys.exit(1)
    if all_meta:
        repo.library_update_metadata(list(all_meta.keys()), all_meta)

    click.echo(
        f"\n  {GREEN}✓{RESET} Added {len(lib_result['added'])} papers to library ({lib_result['total']} total)"
    )
    click.echo(
        f"    {GREEN}{len(matched)}{RESET} full-text papers + {YELLOW}{len(unmatched)}{RESET} metadata-only entries"
    )
    click.echo(f"\n  {DIM}View: paperclip library{RESET}")

    # ── Also add to repo if --add-to-repo or --init was used ──
    if init_name:
        try:
            desc = f"Imported from {fname}"
            repo.init_repo(init_name, desc)
            click.echo(f"  {GREEN}✓{RESET} Created repo: {BOLD}{init_name}{RESET}")
        except ValueError as e:
            click.echo(f"{RED}[error] {e}{RESET}", err=True)
            sys.exit(1)

    active = repo.get_active_repo()
    if active and (add_to_repo or init_name):
        try:
            result = repo.add_papers(all_ids, titles=all_titles, dois=all_dois)
            added_count = len(result.get("added", []))
            if all_meta:
                repo.update_paper_bib_metadata(all_meta)
            click.echo(
                f"  {GREEN}✓{RESET} Also added {added_count} to repo '{active}' ({result['total']} total)"
            )
        except ValueError:
            pass
    elif active and not add_to_repo and not init_name:
        if _is_paper_repos_enabled():
            click.echo(
                f"  {DIM}Tip: Use --add-to-repo to also add to repo '{active}'{RESET}"
            )
    elif not active and not init_name:
        if _is_paper_repos_enabled():
            click.echo(
                f"  {DIM}Tip: paperclip git init <name> to create a repo, then paperclip git add <id> to curate{RESET}"
            )

    # ── Create corpus links in clipboard folder if --into was specified ──
    if into_clipboard and not dry_run:
        _import_bib_to_clipboard(into_clipboard, matched, unmatched, fname)


def _import_bib_to_clipboard(
    folder_path: str,
    matched: list[dict],
    unmatched: list[dict],
    source_filename: str,
):
    """Create corpus links in a clipboard folder for bib-imported papers.

    Matched papers become corpus_link entries (symbolic links to /papers/),
    unmatched become metadata-only entries.
    """
    import httpx

    from ._bibparse import make_ref_id

    folder = folder_path.strip().rstrip("/")
    for prefix in ("/clipboard/", "clipboard/"):
        if folder.startswith(prefix):
            folder = folder[len(prefix):]
            break

    base_url = config.get_base_url()
    headers = {}
    try:
        from ..client.auth import get_auth
        auth = get_auth()
        headers = auth.apply()
    except Exception:
        pass

    # Create the folder via MCP (mkdir)
    click.echo(f"\n  {DIM}Creating clipboard folder: /clipboard/{folder}{RESET}")
    try:
        with httpx.Client(base_url=base_url, headers=headers, timeout=30.0) as client:
            resp = client.post("/api/user/mcp/bash", json={"command": f"mkdir /clipboard/{folder}"})
            if resp.status_code not in (200, 409):
                logger.debug("mkdir response: %s %s", resp.status_code, resp.text[:200])
    except Exception as e:
        logger.debug("mkdir failed: %s", e)

    # Create corpus links for matched papers
    linked = 0
    meta_only = 0

    with httpx.Client(base_url=base_url, headers=headers, timeout=30.0) as client:
        for entry in matched:
            corpus_id = entry.get("corpus_id", "")
            if not corpus_id:
                continue
            try:
                resp = client.post(
                    "/api/user/mcp/bash",
                    json={"command": f"cp /papers/{corpus_id} /clipboard/{folder}/"},
                )
                if resp.status_code == 200:
                    linked += 1
            except Exception as e:
                logger.debug("cp failed for %s: %s", corpus_id, e)

        # Create metadata-only entries for unmatched papers
        for entry in unmatched:
            ref_id = make_ref_id(entry)
            title = entry.get("title", ref_id)
            bib_meta = {
                "authors": entry.get("authors", ""),
                "journal": entry.get("journal", ""),
                "year": entry.get("year", ""),
                "doi": entry.get("doi", ""),
                "entry_key": entry.get("entry_key", ""),
            }
            try:
                resp = client.post(
                    "/api/user/documents",
                    json={
                        "title": title,
                        "filename": ref_id,
                        "folder_path": folder,
                        "source_type": "bib",
                        "link_type": "uploaded",
                        "bib_meta": bib_meta,
                    },
                )
                if resp.status_code in (200, 201):
                    meta_only += 1
            except Exception as e:
                logger.debug("metadata entry failed for %s: %s", ref_id, e)

    click.echo(
        f"  {GREEN}✓{RESET} Clipboard /clipboard/{folder}: "
        f"{GREEN}{linked}{RESET} corpus links + {YELLOW}{meta_only}{RESET} metadata entries"
    )
    click.echo(f"    {DIM}View: paperclip ls /clipboard/{folder}{RESET}")


