@repo_cmd.command("remove-claim")
@click.argument("claim_ids", nargs=-1)
@click.option(
    "--from-file",
    "claims_file",
    type=click.Path(exists=True, dir_okay=False, path_type=Path),
    help="JSON/JSONL file containing claim_id values.",
)
@click.option("--dry-run", is_flag=True, help="Preview matches without removing claims.")
@click.option(
    "--expected-count",
    type=click.IntRange(min=0, max=5000),
    default=None,
    help="Required safety check for destructive removal.",
)
@click.option("--reason", default=None, help="Audit reason for the removal.")
@click.option("--json", "json_output", is_flag=True, help="Emit machine-readable JSON.")
def remove_claim_cmd(
    claim_ids: tuple[str, ...],
    claims_file: Path | None,
    dry_run: bool,
    expected_count: int | None,
    reason: str | None,
    json_output: bool,
):
    """Remove claims by clm_ ID while retaining their papers."""
    from . import repo

    requested = [str(value).strip() for value in claim_ids if str(value).strip()]
    if claims_file:
        text = claims_file.read_text().strip()
        if text:
            try:
                parsed = json.loads(text)
                if isinstance(parsed, dict):
                    parsed = parsed.get("claim_ids", parsed.get("removed_claims", []))
                if not isinstance(parsed, list):
                    raise ValueError("claims file JSON must contain a list")
                for item in parsed:
                    value = item.get("claim_id") if isinstance(item, dict) else item
                    if value:
                        requested.append(str(value).strip())
            except json.JSONDecodeError:
                for line in text.splitlines():
                    item = json.loads(line)
                    value = item.get("claim_id") if isinstance(item, dict) else item
                    if value:
                        requested.append(str(value).strip())

    requested = list(dict.fromkeys(requested))
    if not requested:
        raise click.UsageError("Provide claim IDs or --from-file.")
    if not dry_run and expected_count is None:
        raise click.UsageError("--expected-count is required unless --dry-run is used.")
    if not dry_run and not str(reason or "").strip():
        raise click.UsageError("--reason is required unless --dry-run is used.")

    try:
        result = repo.remove_claims(
            requested,
            dry_run=dry_run,
            expected_count=expected_count,
            reason=reason,
        )
    except (AuthError, ValueError, PaperclipError) as exc:
        click.echo(f"{RED}[error] {exc}{RESET}", err=True)
        raise click.exceptions.Exit(1) from exc

    if json_output:
        click.echo(json.dumps(result, indent=2))
        return
    action = "Matched" if dry_run else "Removed"
    click.echo(
        f"  {GREEN}{action} {result.get('matched_count', 0)} claims{RESET}; "
        f"{result.get('retained_claim_count', 0)} retained across "
        f"{result.get('papers_touched', 0)} touched papers."
    )
    not_found = result.get("not_found") or []
    if not_found:
        click.echo(f"  {YELLOW}{len(not_found)} requested IDs were not found.{RESET}")


def _unresolved_verification_count(verification: dict | None) -> int:
    """Count claim checks that did not produce a conclusive verdict."""
    unresolved = 0
    for claims in (verification or {}).values():
        entries = claims if isinstance(claims, list) else [claims]
        unresolved += sum(
            1
            for entry in entries
            if not isinstance(entry, dict)
            or entry.get("supported") not in (True, False)
        )
    return unresolved


@repo_cmd.command("commit")
@click.option(
    "-m",
    "--message",
    required=True,
    help="Commit message — explain what you found and what's missing",
)
@click.option(
    "-r", "--rationale", default=None, help="Extended rationale (appended to message)"
)
@click.option(
    "--verify/--no-verify",
    default=True,
    help="Verify claim against papers before committing (default: verify)",
)
@click.option(
    "-j",
    "--jobs",
    type=int,
    default=None,
    help="Concurrent verify calls to fan out (default: PAPERCLIP_VERIFY_JOBS or 8). "
    "Papers and claims within each paper are verified concurrently; stable claim "
    "IDs preserve alignment regardless of completion order. "
    "Higher is faster up to the server per-user cap; 429s are retried, so "
    "over-shooting the cap is safe.",
)
@click.option(
    "--verifier-context",
    type=str,
    default=None,
    help="Extra guidance appended to every verifier prompt. Use this to tell "
    "the verifier which parts of a structured claim to check (e.g. "
    "'Focus on the as_reported fields; ignore card_id and sha256.').",
)
def commit_cmd(message: str, rationale: str | None, verify: bool, jobs: int | None, verifier_context: str | None):
    """Snapshot the current repo state with a commit message.

    \b
    The commit message is the audit trail — explain what papers were
    added/removed and why, what you found, and what's still missing.

    Before committing, each paper's claim (annotation) is verified by a
    subagent against the paper's content. Use --no-verify to skip.

    Examples:
        paperclip git commit -m "initial resistance papers"
        paperclip git commit -m "Found 3 phase-2 trials" -r "Added spleen LNP data, still need phase-3."
        paperclip git commit -m "quick snapshot" --no-verify
    """
    from . import repo

    full_message = f"{message}\n\n{rationale}" if rationale else message

    # Capture active repo name ONCE at the start to prevent race conditions
    # where concurrent agents change the .active file mid-operation.
    active_name = repo.get_active_repo() or ""

    try:
        verification = None
        if verify:
            verification = _run_commit_verification(
                full_message,
                repo_name=active_name,
                jobs=jobs,
                verifier_context=verifier_context,
            )
            unresolved = _unresolved_verification_count(verification)
            if unresolved:
                click.echo(
                    f"{RED}[error] Verification remained unresolved for "
                    f"{unresolved} claim(s); no commit was created.{RESET}\n"
                    f"{DIM}Retry the same command. Completed claim checks will "
                    f"be reused.{RESET}",
                    err=True,
                )
                sys.exit(1)

        entry = repo.commit(full_message)

        click.echo(f"  {GREEN}[{entry['sha']}]{RESET} {message}")
        if entry.get("added"):
            click.echo(f"  {DIM}+{len(entry['added'])} added{RESET}", nl=False)
        if entry.get("removed"):
            click.echo(f"  {DIM}-{len(entry['removed'])} removed{RESET}", nl=False)
        click.echo(f"  {DIM}{entry['paper_count']} papers committed{RESET}")

        _persist_and_echo_verification(active_name, verification)
    except AuthError:
        click.echo(
            f"{RED}[error] Authentication failed (API key invalid).{RESET}", err=True
        )
        sys.exit(1)
    except ValueError as e:
        click.echo(f"{RED}[error] {e}{RESET}", err=True)
        sys.exit(1)


def _persist_and_echo_verification(active_name: str, verification: dict | None) -> None:
    """Save, push, and print claim verdicts from a commit verification run."""
    from . import repo

    if not verification:
        return
    repo.save_verification(active_name, verification)
    full_cache = repo.load_verification(active_name) or verification
    repo.push_verification_to_server(full_cache)

    click.echo()
    for doc_id, claims_list in verification.items():
        if isinstance(claims_list, dict):
            claims_list = [claims_list]
        for v in claims_list:
            supported = v.get("supported")
            if supported is True:
                mark = f"{GREEN}[OK]{RESET}"
            elif supported is None:
                mark = f"{YELLOW}[!]{RESET}"
            else:
                mark = f"{RED}[X]{RESET}"
            claim = v.get("claim", "")
            click.echo(f"  {mark} {doc_id}: {claim}")
            reason = v.get("reason", "")
            if reason:
                click.echo(f"    {DIM}evidence: {reason}{RESET}")
            vlines = v.get("lines", [])
            if vlines:
                click.echo(f"    {DIM}lines: {_format_line_refs(vlines)}{RESET}")


def _format_line_refs(line_nums: list) -> str:
    """Collapse consecutive line numbers into ranges: [1,2,3,5,7,8,9] -> 'L1-L3, L5, L7-L9'."""
    if not line_nums:
        return ""
    # Verification results normally contain integer line numbers, but an MCP
    # verifier can occasionally return metadata such as "N" / "N/A" in the
    # same field. Rendering a completed commit must not fail because one result
    # contains malformed display metadata. Keep valid positive line references
    # (including numeric and L-prefixed strings) and ignore everything else.
    parsed: set[int] = set()
    for raw in line_nums:
        if isinstance(raw, bool):
            continue
        if isinstance(raw, int):
            n = raw
        elif isinstance(raw, float) and raw.is_integer():
            n = int(raw)
        elif isinstance(raw, str):
            token = raw.strip()
            if token[:1].lower() == "l":
                token = token[1:]
            if not token.isdigit():
                continue
            n = int(token)
        else:
            continue
        if n > 0:
            parsed.add(n)

    nums = sorted(parsed)
    if not nums:
        return ""
    ranges: list[str] = []
    start = prev = nums[0]
    for n in nums[1:]:
        if n == prev + 1:
            prev = n
        else:
            ranges.append(f"L{start}" if start == prev else f"L{start}-L{prev}")
            start = prev = n
    ranges.append(f"L{start}" if start == prev else f"L{start}-L{prev}")
    return ", ".join(ranges)


def _parse_verify_output(output: str) -> dict:
    """Parse the JSON object from a ``verify`` command's output.

    When the ``verify`` command runs over the MCP execute path (API-key auth),
    the spawned CLI appends a human-readable footer line (e.g. ``[7.9s]``) after
    the JSON payload. A plain ``json.loads`` then fails with "Extra data", which
    would record every claim as a false failure even though verification
    succeeded server-side. Decode only the leading JSON value and ignore any
    trailing footer text.
    """
    import json as _json

    text = (output or "").strip()
    if not text:
        return {}
    start = text.find("{")
    if start == -1:
        # Surface the original error for the caller's except handler.
        return _json.loads(text)
    obj, _ = _json.JSONDecoder().raw_decode(text, start)
    return obj if isinstance(obj, dict) else {}


def _run_commit_verification(
    commit_message: str,
    repo_name: str = "",
    jobs: int | None = None,
    verifier_context: str | None = None,
) -> dict | None:
    """Run claim verification against all papers in the active repo.

    Each paper's annotation (claim) is verified against the paper's content
    by a dedicated subagent. Papers without annotations are skipped.
    Papers with multiple annotations get each claim verified independently.

    Args:
        commit_message: The commit message (unused currently, reserved).
        repo_name: Pinned repo name to use for caching (avoids re-reading
            the .active file which may race with concurrent agents).

    Returns the verification dict:
        {doc_id: [{claim, supported, reason, lines}, ...]}
    Each paper maps to a *list* of per-claim verification results.
    """
    import json as _json
    import os as _os
    from concurrent.futures import (
        ThreadPoolExecutor as _ThreadPoolExecutor,
        as_completed as _as_completed,
    )

    from . import repo

    # Client-side verify concurrency: fan out up to `jobs` verify calls at once.
    # This is NOT the throughput ceiling — the real limiter is the SERVER's
    # per-user long-running cap (default 8, internal 32, liftable to 64 for a
    # trusted run via the X-Paperclip-Long-Cap override). The client fans out
    # freely and 429s are retried with full jitter, so `jobs` can safely exceed
    # the cap; extra calls just queue behind it. Default 8 (matches the default
    # server cap so a single run fully utilizes it); raise via --jobs or
    # PAPERCLIP_VERIFY_JOBS for internal / cap-lifted runs (higher = faster, up
    # to the server cap — measured ~2x from jobs=8 to jobs=32 at N=300).
    if jobs is None:
        try:
            jobs = int(_os.getenv("PAPERCLIP_VERIFY_JOBS", "8"))
        except ValueError:
            jobs = 8
    jobs = max(1, jobs)

    # Retry budget for transient 429s (per-user cap collisions). More attempts
    # help when many agents share one cap; full jitter (in _verify_call) keeps
    # them from retrying in lockstep. Override with PAPERCLIP_VERIFY_RETRIES.
    try:
        _VERIFY_RETRIES = max(1, int(_os.getenv("PAPERCLIP_VERIFY_RETRIES", "8")))
    except ValueError:
        _VERIFY_RETRIES = 8

    # Max documents per single verify call. Single-claim papers are batched into
    # one verify call to amortize overhead (the server verifies the batch's docs
    # in parallel internally), but the batch must stay SMALL: total concurrent
    # server-side work is roughly jobs x batch, and pushing that too high makes
    # heavy calls exceed the gateway timeout and return 5xx/HTML instead of a
    # verdict (observed: ~38 docs/call x 8 concurrent floods the verifier). Cap
    # the batch so each call stays light and a single failure poisons few docs.
    # Override with PAPERCLIP_VERIFY_BATCH.
    try:
        _VERIFY_BATCH = max(1, int(_os.getenv("PAPERCLIP_VERIFY_BATCH", "12")))
    except ValueError:
        _VERIFY_BATCH = 12

    # Claims within one paper can now be verified concurrently by one backend
    # request. Keep this separate from `jobs` (concurrent requests/papers) so
    # total verifier pressure remains bounded at roughly jobs * claim_jobs.
    try:
        _CLAIM_JOBS = max(
            1, int(_os.getenv("PAPERCLIP_VERIFY_CLAIM_JOBS", "4"))
        )
    except ValueError:
        _CLAIM_JOBS = 4

    # Bound one paper's serialized claim payload. Large structured extractions
    # can contain hundreds of verbose, path-pinned claims; sending all of them
    # in one shell-routed request can exceed parser/gateway budgets and trigger
    # the legacy one-at-a-time fallback.
    try:
        _CLAIM_BATCH = max(
            1, int(_os.getenv("PAPERCLIP_VERIFY_CLAIM_BATCH", "25"))
        )
    except ValueError:
        _CLAIM_BATCH = 25

    # Bound total verifier pressure, not just HTTP request count. Raising
    # --jobs without accounting for documents/claims per request previously
    # multiplied server work until otherwise healthy requests returned empty
    # or timed out. Trusted deployments may raise this explicit budget.
    try:
        _MAX_INFLIGHT = max(
            1, int(_os.getenv("PAPERCLIP_VERIFY_MAX_INFLIGHT", "96"))
        )
    except ValueError:
        _MAX_INFLIGHT = 96
    per_request_work = max(_VERIFY_BATCH, _CLAIM_JOBS)
    jobs = min(jobs, max(1, _MAX_INFLIGHT // per_request_work))

    status = repo.get_status()
    papers = status.get("papers", {})
    if not papers:
        return None

    # Skip already-verified claims. Merge the SERVER-merged verdicts with the
    # local cache so that when MULTIPLE agents commit to the same repo, each one
    # skips claims a PEER already verified and pushed — not just its own. Local
    # wins on conflict (it holds this agent's freshest, possibly un-pushed
    # verdicts); the server fills in every peer's papers. This turns N concurrent
    # subagents from "each re-verifies the whole repo" into "each verifies mostly
    # what's still outstanding". (For the cleanest split — subagents ADD, one
    # final commit verifies — there are no peers mid-commit and this is a no-op.)
    existing_verification = repo.load_verification(repo_name) or {}
    try:
        server_v = repo.load_server_verification(repo_name) or {}
        for pid, lst in server_v.items():
            if pid not in existing_verification:
                existing_verification[pid] = lst
    except Exception as exc:
        logger.debug("Could not merge server verification for skip-check: %s", exc)

    def _is_conclusive(prev: dict, claim_text: str) -> bool:
        """A previous result is conclusive if it has a real True/False verdict
        AND the claim text hasn't changed since it was verified."""
        if prev.get("supported") is None:
            return False
        if prev.get("claim") != claim_text:
            return False
        reason = prev.get("reason", "")
        if isinstance(reason, str) and reason.startswith("error:"):
            return False
        return True

    # Build per-paper verification PLANS. Each plan carries the FULL ordered
    # claim list plus which claim indices still need verifying, so every task
    # emits a COMPLETE, position-aligned result list.
    #
    # Skip granularity is per-CLAIM: a claim with a conclusive prior result
    # (True/False with matching claim text) is never re-submitted — but its
    # verdict is REUSED in place. Emitting a compacted list of only the
    # newly-verified claims would misalign a multi-claim paper on re-commit,
    # because save_verification (and compile) align per-claim results to
    # annotations BY INDEX.
    paper_plans: dict[str, dict] = {}
    for pid, info in papers.items():
        annots = info.get("annotations") or info.get("_annotations") or []
        note = info.get("note") or ""

        claims: list[str] = []
        if annots:
            for ann in annots:
                ann_note = ann.get("note", "")
                if ann_note:
                    claims.append(ann_note)
        elif note:
            claims.append(note)

        if not claims:
            continue

        prev_results = existing_verification.get(pid, [])
        if isinstance(prev_results, dict):
            prev_results = [prev_results]

        claim_ids = [
            _stable_claim_id(
                pid,
                claim_text,
                annots[ci] if ci < len(annots) else None,
            )
            for ci, claim_text in enumerate(claims)
        ]
        # New verdicts carry claim_id, so a reordered annotation list cannot
        # misattach a prior result. Positional lookup remains as a compatibility
        # fallback for caches written by older clients.
        prev_by_id = {
            str(item.get("claim_id")): item
            for item in prev_results
            if isinstance(item, dict) and item.get("claim_id")
        }
        aligned_prev: list[dict | None] = []
        need_idx: list[int] = []
        for ci, (claim_text, claim_id) in enumerate(zip(claims, claim_ids)):
            prev = prev_by_id.get(claim_id)
            if prev is None and ci < len(prev_results):
                candidate = prev_results[ci]
                if isinstance(candidate, dict) and candidate.get("claim") == claim_text:
                    prev = candidate
            aligned_prev.append(prev)
            if not (isinstance(prev, dict) and _is_conclusive(prev, claim_text)):
                need_idx.append(ci)

        if need_idx:
            paper_plans[pid] = {
                "claims": claims,
                "claim_ids": claim_ids,
                "annots": annots,
                "prev": aligned_prev,
                "need": set(need_idx),
            }

    if not paper_plans:
        click.echo(f"  {DIM}all claims already verified — skipping{RESET}")
        return None

    # Single-claim papers (exactly one total claim) batch efficiently — one
    # verify call covers many. Multi-claim papers each get their own task that
    # verifies only the still-needed claims but rebuilds the FULL ordered list.
    single_claim_papers: dict[str, str] = {}
    single_claim_annots: dict[str, list[dict]] = {}
    single_claim_ids: dict[str, str] = {}
    multi_claim_plans: dict[str, dict] = {}

    for pid, plan in paper_plans.items():
        if len(plan["claims"]) == 1:
            single_claim_papers[pid] = plan["claims"][0]
            single_claim_ids[pid] = plan["claim_ids"][0]
            if plan["annots"]:
                single_claim_annots[pid] = plan["annots"]
        else:
            multi_claim_plans[pid] = plan

    client = _get_client()
    all_results: dict[str, list[dict]] = {}

    # Incremental persistence: save verification marks every few papers so a
    # large commit (hundreds of claims, verified with up to `jobs` concurrent
    # calls) is RESUMABLE — a timeout or crash loses at most _PERSIST_EVERY
    # papers' worth of progress instead of everything. save_verification merges,
    # and a re-commit only re-verifies still-[?] claims, so partial progress
    # compounds. Called only from the main thread as futures complete, so a
    # simple snapshot keeps it consistent.
    _active_repo = repo_name or repo.get_active_repo() or ""
    _PERSIST_EVERY = 10
    _since_persist = 0

    def _persist_progress(force: bool = False) -> None:
        nonlocal _since_persist
        _since_persist += 1
        if not _active_repo or not all_results:
            return
        if force or _since_persist >= _PERSIST_EVERY:
            _since_persist = 0
            snapshot = {k: list(v) for k, v in all_results.items()}
            try:
                repo.save_verification(_active_repo, snapshot)
                full_cache = repo.load_verification(_active_repo) or snapshot
                repo.push_verification_to_server(full_cache)
            except Exception as exc:
                logger.debug("Incremental verification persist failed: %s", exc)

    def _has_conclusive_verdicts(payload: dict) -> bool:
        keyed = payload.get("claim_results")
        if isinstance(keyed, dict):
            entries = list(keyed.values())
        else:
            entries = []
            for value in payload.values():
                if isinstance(value, list):
                    entries.extend(value)
                elif isinstance(value, dict):
                    entries.append(value)
        return bool(entries) and all(
            isinstance(entry, dict)
            and isinstance(entry.get("supported"), bool)
            and isinstance(entry.get("reason"), str)
            for entry in entries
        )

    def _verify_call(v_args: list[str]):
        """Run a verify, retrying transient failures (rate limit / gateway / timeout).

        `verify` is a long-running command capped per user (default 8; higher
        for internal users or when a trusted caller raises it). Two classes of
        transient failure must be retried — NOT recorded as a false [X] that
        drops a good effect:

        1. 429 (RateLimitError): the per-user concurrency cap rejected the call
           BEFORE it ran. Happens when several agents commit at once, or one
           agent fans out past the cap.
        2. 5xx / timeout / network (ServerError>=500, RequestTimeoutError,
           NetworkError): under heavy concurrent load the gateway or verifier
           returns an HTML error page or times out. These poison a whole batch
           if not retried (observed at ~300 papers).

        Retry with FULL JITTER (sleep in [0, backoff]) so concurrent retriers
        decorrelate instead of thundering the cap in lockstep. A real
        verification "failure" comes back as a normal result with
        supported=False, never as one of these exceptions, so retrying them is
        always safe.
        """
        import time as _t
        import random as _r

        def _wait_before_retry(attempt: int, reason: str) -> None:
            delay = _r.uniform(0.0, min(30.0, 2.0 * (2**attempt)))
            click.echo(
                f"[waiting] {reason}; retry "
                f"{attempt + 2}/{_VERIFY_RETRIES} in {delay:.1f}s",
                err=True,
            )
            _t.sleep(delay)

        for i in range(_VERIFY_RETRIES):
            try:
                result = client.execute("verify", v_args, timeout=300)
                if result and getattr(result, "exit_code", 0) != 0:
                    detail = str(result.output or "").strip()
                    raise RuntimeError(
                        f"verifier command failed with exit code {result.exit_code}"
                        + (f": {detail}" if detail else "")
                    )
                if not result or not str(result.output or "").strip():
                    raise RuntimeError("verifier returned an empty response")
                parsed = _parse_verify_output(str(result.output))
                if not parsed:
                    raise RuntimeError("verifier returned an empty JSON object")
                if not _has_conclusive_verdicts(parsed):
                    raise RuntimeError(
                        "verifier returned no conclusive structured verdicts"
                    )
                return result
            except RuntimeError:
                if i == _VERIFY_RETRIES - 1:
                    raise
                _wait_before_retry(i, "verifier returned an invalid response")
            except RateLimitError:
                if i == _VERIFY_RETRIES - 1:
                    raise
                _wait_before_retry(i, "verifier request was rate-limited")
            except RequestTimeoutError:
                if i == _VERIFY_RETRIES - 1:
                    raise
                _wait_before_retry(i, "verifier request timed out")
            except NetworkError:
                if i == _VERIFY_RETRIES - 1:
                    raise
                _wait_before_retry(i, "verifier network error")
            except ServerError as exc:
                # Only 5xx is transient; a 4xx ServerError is a real problem.
                sc = getattr(exc, "status_code", None)
                if sc is not None and sc < 500:
                    raise
                if i == _VERIFY_RETRIES - 1:
                    raise
                reason = f"HTTP {sc}" if sc is not None else "server error"
                _wait_before_retry(i, f"verifier {reason}")

    # ---- Fan out verification, bounded by `jobs` ------------------------------
    # Each work item owns a DISJOINT set of doc_ids and returns a complete,
    # ordered per-claim result list for each. Multi-claim papers submit all
    # pending claims together; the backend verifies up to _CLAIM_JOBS at once
    # and returns a stable claim_id-keyed map. The client reconstructs current
    # annotation order by ID, so out-of-order completion cannot corrupt
    # alignment. Because no two items touch the same pid, paper results are
    # still merged in the main thread without shared-state locking.
    def _verify_single_claim(pid: str, claim_text: str) -> list[dict]:
        """Retry one claim independently so a bad batch cannot poison peers."""
        args = [
            "--claims", _json.dumps({pid: claim_text}),
            "--document-ids", pid,
        ]
        if pid in single_claim_annots:
            args.extend([
                "--annotations",
                _json.dumps({pid: single_claim_annots[pid]}),
            ])
        if verifier_context:
            args.extend(["--verifier-context", verifier_context])
        try:
            result = _verify_call(args)
            raw = _parse_verify_output(result.output or "")
            value = raw.get(pid)
            if isinstance(value, list):
                entries = value
            elif isinstance(value, dict):
                entries = [value]
            else:
                raise RuntimeError("verify returned no result for document")
            if not entries or not all(isinstance(entry, dict) for entry in entries):
                raise RuntimeError("verify returned an invalid result for document")
            for entry in entries:
                entry.setdefault("claim_id", single_claim_ids[pid])
                entry.setdefault("document_id", pid)
                entry.setdefault("claim", claim_text)
            return entries
        except Exception as exc:
            return [{
                "claim_id": single_claim_ids[pid],
                "document_id": pid,
                "claim": claim_text,
                "supported": None,
                "reason": f"error: {exc}",
            }]

    def _batch_task(chunk: dict[str, str]) -> dict[str, list[dict]]:
        """Verify a batch of single-claim papers in one call. chunk: pid -> claim."""
        args = [
            "--claims", _json.dumps(chunk),
            "--document-ids", ",".join(chunk.keys()),
        ]
        annots_sub = {
            pid: single_claim_annots[pid] for pid in chunk if pid in single_claim_annots
        }
        if annots_sub:
            args.extend(["--annotations", _json.dumps(annots_sub)])
        if verifier_context:
            args.extend(["--verifier-context", verifier_context])
        out: dict[str, list[dict]] = {}
        try:
            result = _verify_call(args)
            output = (result.output or "") if result else ""
            raw = _parse_verify_output(output) if output.strip() else {}
            missing: list[tuple[str, str]] = []
            for pid, claim_text in chunk.items():
                v = raw.get(pid)
                if isinstance(v, list):
                    entries = v
                elif isinstance(v, dict):
                    entries = [v]
                else:
                    missing.append((pid, claim_text))
                    continue
                for entry in entries:
                    if isinstance(entry, dict):
                        entry.setdefault("claim_id", single_claim_ids[pid])
                        entry.setdefault("document_id", pid)
                out[pid] = entries
            for pid, claim_text in missing:
                out[pid] = _verify_single_claim(pid, claim_text)
        except Exception as exc:
            logger.warning(
                "Batch verify failed for %s (%s); retrying each claim independently",
                list(chunk.keys()),
                exc,
            )
            for pid, claim_text in chunk.items():
                out[pid] = _verify_single_claim(pid, claim_text)
        return out

    def _paper_task(pid: str, plan: dict) -> dict[str, list[dict]]:
        """Verify a multi-claim paper, emitting the FULL ordered per-claim list:
        still-needed claims are submitted together and keyed by stable claim ID;
        already-conclusive claims are reused. The backend may finish claims in
        any order without risking verdict/annotation misalignment."""
        claims = plan["claims"]
        claim_ids = plan["claim_ids"]
        annots = plan["annots"]
        prev = plan["prev"]
        need = plan["need"]
        entries: list[dict | None] = [None] * len(claims)

        # Preserve already-conclusive entries, upgrading legacy positional
        # results with stable IDs as they pass through.
        for ci, claim_text in enumerate(claims):
            if ci not in need:
                entry = dict(prev[ci])
                entry.setdefault("claim_id", claim_ids[ci])
                entry.setdefault("document_id", pid)
                entries[ci] = entry

        claim_items = []
        for ci in sorted(need):
            item = {
                "claim_id": claim_ids[ci],
                "claim": claims[ci],
            }
            if ci < len(annots) and annots[ci].get("lines"):
                item["lines"] = annots[ci]["lines"]
            if ci < len(annots) and annots[ci].get("source_locations"):
                item["source_locations"] = annots[ci]["source_locations"]
            claim_items.append(item)

        def _unknown(ci: int, reason: str) -> dict:
            return {
                "claim_id": claim_ids[ci],
                "document_id": pid,
                "claim": claims[ci],
                "supported": None,
                "reason": reason,
            }

        def _legacy_verify_one(ci: int) -> dict:
            """Compatibility path for a pre-claim-ID backend during rollout."""
            args = [
                "--claims", _json.dumps({pid: claims[ci]}),
                "--document-ids", pid,
            ]
            if ci < len(annots):
                args.extend(["--annotations", _json.dumps({pid: [annots[ci]]})])
            if verifier_context:
                args.extend(["--verifier-context", verifier_context])
            try:
                result = _verify_call(args)
                output = result.output or ""
                if output.strip():
                    raw = _parse_verify_output(output)
                    v = raw.get(pid)
                    if isinstance(v, dict):
                        entry = v
                    elif isinstance(v, list) and v:
                        entry = v[0]
                    else:
                        entry = None
                    if isinstance(entry, dict):
                        entry.setdefault("claim_id", claim_ids[ci])
                        entry.setdefault("document_id", pid)
                        entry.setdefault("claim", claims[ci])
                        return entry
                    return _unknown(ci, "error: verify returned unparseable result")
                return _unknown(ci, "error: verify returned empty output")
            except Exception as exc:
                logger.warning("Legacy verify failed for %s claim %s: %s", pid, ci, exc)
                return _unknown(ci, f"error: {exc}")

        if claim_items:
            claim_index_by_id = {
                claim_ids[ci]: ci
                for ci in sorted(need)
            }
            for start in range(0, len(claim_items), _CLAIM_BATCH):
                batch = claim_items[start : start + _CLAIM_BATCH]
                batch_indexes = [
                    claim_index_by_id[item["claim_id"]]
                    for item in batch
                ]
                args = [
                    "--claims", _json.dumps({pid: batch}),
                    "--document-ids", pid,
                    "--max-concurrent", str(_CLAIM_JOBS),
                ]
                if verifier_context:
                    args.extend(["--verifier-context", verifier_context])
                try:
                    result = _verify_call(args)
                    output = result.output or ""
                    raw = _parse_verify_output(output) if output.strip() else {}
                    by_claim_id = raw.get("claim_results")
                    if isinstance(by_claim_id, dict):
                        for ci in batch_indexes:
                            item = by_claim_id.get(claim_ids[ci])
                            if isinstance(item, dict):
                                entry = dict(item)
                                entry.setdefault("claim_id", claim_ids[ci])
                                entry.setdefault("document_id", pid)
                                entry.setdefault("claim", claims[ci])
                                entries[ci] = entry
                            else:
                                entries[ci] = _unknown(
                                    ci,
                                    "error: verify returned no result for claim_id",
                                )
                    else:
                        # A server running the previous protocol may accept the
                        # object payload but return the legacy per-document shape.
                        for ci in batch_indexes:
                            entries[ci] = _legacy_verify_one(ci)
                except Exception as exc:
                    logger.warning(
                        "Concurrent claim verify unavailable for %s batch %s-%s "
                        "(%s); falling back to legacy one-at-a-time protocol",
                        pid,
                        start + 1,
                        start + len(batch),
                        exc,
                    )
                    for ci in batch_indexes:
                        entries[ci] = _legacy_verify_one(ci)

        return {
            pid: [
                entry
                if isinstance(entry, dict)
                else _unknown(ci, "error: missing verification entry")
                for ci, entry in enumerate(entries)
            ]
        }

    # Assemble the work items (each a zero-arg callable returning {pid: [...]}).
    tasks: list = []
    if single_claim_papers:
        pids = list(single_claim_papers.keys())
        # Chunk by a fixed MAX BATCH SIZE (not by `jobs`). This keeps each verify
        # call light regardless of corpus size — the old `min(jobs, len(pids))`
        # scheme made batches grow without bound (300 papers / 8 jobs = ~38
        # docs/call), and heavy concurrent calls overwhelmed the gateway. Now the
        # number of chunks scales with N while `jobs` independently bounds how
        # many run at once, so total server load stays ~= jobs x batch.
        n_chunks = max(1, -(-len(pids) // _VERIFY_BATCH))  # ceil(len/batch)
        chunks: list[dict[str, str]] = [{} for _ in range(n_chunks)]
        for i, pid in enumerate(pids):
            chunks[i % n_chunks][pid] = single_claim_papers[pid]
        for ch in chunks:
            if ch:
                tasks.append(lambda ch=ch: _batch_task(ch))
    for pid, plan in multi_claim_plans.items():
        tasks.append(lambda pid=pid, plan=plan: _paper_task(pid, plan))

    if not tasks:
        _persist_progress(force=True)
        return all_results or None

    if jobs <= 1 or len(tasks) <= 1:
        for task in tasks:
            all_results.update(task())
            _persist_progress()
    else:
        with _ThreadPoolExecutor(max_workers=jobs) as ex:
            futures = [ex.submit(task) for task in tasks]
            for fut in _as_completed(futures):
                try:
                    all_results.update(fut.result())
                except Exception as exc:  # a task itself should never raise, but be safe
                    logger.warning("verify worker crashed: %s", exc)
                _persist_progress()

    _persist_progress(force=True)
    return all_results or None


@repo_cmd.command("status")
def status_cmd():
    """Show current repo state: papers, claims, and verification results.

    \b
    Like `git status` - shows where you are right now.
    Verification marks ([OK]/[X]) come from the last `paperclip git commit`.

    Examples:
        paperclip git status
    """
    from . import repo

    active = repo.get_active_repo()
    if not active:
        click.echo(
            f"No active repo. Use: paperclip git init <name>"
        )
        return

    try:
        s = repo.get_status()
    except AuthError:
        click.echo(
            f"{RED}[error] Authentication failed (API key invalid).{RESET}", err=True
        )
        sys.exit(1)

    branch = s.get("active_branch", "main")
    papers = s.get("papers", {})
    commit_count = s.get("commit_count", 0)

    click.echo(f"\n  {BOLD}On repo {active}{RESET}  {DIM}branch {branch}{RESET}")
    click.echo(
        f"  {DIM}{len(papers)} paper{'s' if len(papers) != 1 else ''}, "
        f"{commit_count} commit{'s' if commit_count != 1 else ''}{RESET}\n"
    )

    if not papers:
        click.echo(f"  {DIM}No papers yet. Use: paperclip git add <id> \"claim\"{RESET}\n")
        return

    verification = (
        s.get("verification")
        or repo.load_server_verification()
        or repo.load_verification()
        or {}
    )

    has_unverified = False
    for pid, info in papers.items():
        title = info.get("title", "")
        year = info.get("year") or info.get("pub_year")
        annots = info.get("annotations") or []
        note = info.get("note") or ""

        # Collect all claims: prefer annotations list, fall back to note
        claim_annotations: list[dict] = []
        if annots:
            for ann in annots:
                ann_note = ann.get("note", "")
                if ann_note:
                    claim_annotations.append(ann)
        elif note:
            claim_annotations.append({"note": note, "lines": None})
        claims = [str(ann.get("note") or "") for ann in claim_annotations]

        # Get verification results (list format from new multi-claim verification)
        v_list = verification.get(pid)
        if isinstance(v_list, dict):
            v_list = [v_list]
        v_list = v_list or []
        v_by_id = {
            str(verdict.get("claim_id")): verdict
            for verdict in v_list
            if isinstance(verdict, dict) and verdict.get("claim_id")
        }
        claim_verdicts: list[dict | None] = []
        for ci, annotation in enumerate(claim_annotations):
            claim_text = str(annotation.get("note") or "")
            claim_id = _stable_claim_id(pid, claim_text, annotation)
            verdict = v_by_id.get(claim_id)
            if verdict is None and ci < len(v_list):
                candidate = v_list[ci]
                if (
                    isinstance(candidate, dict)
                    and candidate.get("claim") == claim_text
                ):
                    verdict = candidate
            claim_verdicts.append(verdict)

        # Determine paper-level mark from claims
        if claims and all(verdict is not None for verdict in claim_verdicts):
            all_supported = all(
                verdict and verdict.get("supported") is True
                for verdict in claim_verdicts
            )
            any_rejected = any(
                verdict and verdict.get("supported") is False
                for verdict in claim_verdicts
            )
            any_errored = any(
                verdict and verdict.get("supported") is None
                for verdict in claim_verdicts
            )
            if all_supported:
                paper_mark = f"{GREEN}[OK]{RESET}"
            elif any_rejected:
                paper_mark = f"{RED}[X]{RESET}"
            elif any_errored:
                paper_mark = f"{YELLOW}[!]{RESET}"
                has_unverified = True
            else:
                paper_mark = f"{DIM}[?]{RESET}"
        elif claims:
            paper_mark = f"{DIM}[?]{RESET}"
            has_unverified = True
        else:
            paper_mark = f"{DIM}[?]{RESET}"

        header = f"  {paper_mark} {CYAN}{pid}{RESET}"
        if title:
            header += f"  {title[:50]}"
        if year:
            header += f" {DIM}({year}){RESET}"
        click.echo(header)

        if not claims:
            continue

        # Display each claim with its own verification result
        for ci, claim_text in enumerate(claims):
            v = claim_verdicts[ci]
            if v is not None:
                s = v.get("supported")
                if s is True:
                    c_mark = f"{GREEN}[OK]{RESET}"
                elif s is None:
                    c_mark = f"{YELLOW}[!]{RESET}"
                else:
                    c_mark = f"{RED}[X]{RESET}"
            else:
                c_mark = f"{DIM}[?]{RESET}"
                has_unverified = True

            # For single-claim papers, use simpler formatting
            if len(claims) == 1:
                click.echo(f"    {DIM}claim: {claim_text}{RESET}")
            else:
                click.echo(f"    {c_mark} {DIM}claim: {claim_text}{RESET}")

            if v:
                reason = v.get("reason", "")
                if reason:
                    click.echo(f"    {DIM}evidence: {reason}{RESET}")
                vlines = v.get("lines", [])
                if vlines:
                    click.echo(f"    {DIM}lines: {_format_line_refs(vlines)}{RESET}")

    if has_unverified and papers:
        click.echo(
            f"\n  {DIM}[?] = not yet checked; [!] = verifier/system error. "
            f"Retry: paperclip git commit -m \"message\"{RESET}"
        )
    click.echo()


@repo_cmd.command("claims")
@click.option(
    "--verified-only",
    is_flag=True,
    help="Only emit claims verified [OK] on the last commit",
)
@click.option(
    "--type",
    "type_filter",
    default=None,
    help="Only emit claims whose 'type' equals this (e.g. effect, context)",
)
def claims_cmd(verified_only: bool, type_filter: str | None):
    """Emit repo claims as a JSON array — the machine-readable claim store.

    \b
    This is the source of truth for inspecting or exporting generic repo
    claims. Each element is the claim's JSON body augmented with
    fields that live OUTSIDE that body and are therefore lost when scraping
    `repo status` text:
      paperclip_doc_id  - the paper the claim is attached to
      paperclip_lines   - the exact source line pin from `repo add --lines`
      verified          - true iff the last commit marked this claim [OK]
    Domain-agnostic: the claim body is passed through untouched, so it works
    for any claim schema (medical effects, ML benchmark scores, etc.).

    \b
    Examples:
        paperclip git claims                                  # all claims
        paperclip git claims --verified-only --type effect    # progress/inspection
        paperclip git claims --verified-only --type context   # progress/inspection

    Specialized workflows may require their own compiler and validation gates.
    Do not substitute this diagnostic export for those workflow artifacts.
    """
    from . import repo

    if not repo.get_active_repo():
        click.echo("[]")
        return

    status = repo.get_status()
    # Parallel workers push disjoint verification subsets into the server-merged
    # store. A local cache only represents the current process/config directory,
    # so prefer the authoritative server view and fall back for offline repos.
    verification = (
        repo.load_server_verification()
        or repo.load_verification()
        or {}
    )
    papers = status.get("papers", {})

    out: list[dict] = []
    for pid, info in papers.items():
        annots = info.get("annotations") or []
        note = info.get("note") or ""
        # Keep each complete annotation so stable claim IDs can align verdicts
        # independently of annotation or verifier completion order.
        entries: list[dict] = []
        if annots:
            for ann in annots:
                n = ann.get("note", "")
                if n:
                    entries.append(ann)
        elif note:
            entries.append({"note": note, "lines": None})

        v_list = verification.get(pid)
        if isinstance(v_list, dict):
            v_list = [v_list]
        v_by_id = {
            str(v.get("claim_id")): v
            for v in (v_list or [])
            if isinstance(v, dict) and v.get("claim_id")
        }

        for ci, ann in enumerate(entries):
            note_text = ann.get("note", "")
            lines = ann.get("lines")
            claim_id = _stable_claim_id(pid, note_text, ann)
            v = v_by_id.get(claim_id)
            # Compatibility with caches written before claim IDs existed. Only
            # accept a positional verdict when its claim text also matches.
            if v is None and v_list and ci < len(v_list):
                candidate = v_list[ci]
                if (
                    isinstance(candidate, dict)
                    and candidate.get("claim") == note_text
                ):
                    v = candidate
            is_verified = bool(v and v.get("supported"))
            if verified_only and not is_verified:
                continue
            claim: dict
            if "{" in note_text:
                try:
                    parsed = json.loads(note_text[note_text.index("{"):])
                    claim = parsed if isinstance(parsed, dict) else {"note": note_text}
                except json.JSONDecodeError:
                    claim = {"note": note_text}
            else:
                claim = {"note": note_text}
            if type_filter and claim.get("type") != type_filter:
                continue
            claim["paperclip_doc_id"] = pid
            if lines:
                claim["paperclip_lines"] = lines
            claim["claim_id"] = claim_id
            claim["verified"] = is_verified
            out.append(claim)

    click.echo(json.dumps(out, indent=2))


@repo_cmd.command("citations")
@click.argument("paper_ids", nargs=-1, required=False)
@click.option(
    "--graph", is_flag=True, help="Show citation relationships between papers"
)
@click.option(
    "--refresh", is_flag=True, help="Force fresh lookup from Semantic Scholar"
)
def citations_cmd(paper_ids: tuple, graph: bool, refresh: bool):
    """Citation counts and relationships for repo papers.

    \b
    Defaults to citation counts; use --graph for relationships.

    Examples:
        paperclip git citations                          # counts for all repo papers
        paperclip git citations --refresh                # force fresh from S2
        paperclip git citations --graph                  # citation relationships
        paperclip git citations PMC9170150 PMC11748609   # specific papers
    """
    from . import repo

    ids = list(paper_ids) if paper_ids else repo.get_repo_paper_ids()
    if not ids:
        click.echo(
            f"{RED}[error] No paper IDs. Provide IDs or activate a repo.{RESET}",
            err=True,
        )
        sys.exit(1)

    if graph:
        _show_cite_graph(ids, repo)
    else:
        _show_cite_counts(ids, repo, refresh=refresh)


def _show_cite_counts(ids: list[str], repo, *, refresh: bool) -> None:
    cached = repo.get_repo_citations()
    cached_ids = set(cached.keys())
    requested = set(ids)

    if not refresh and requested <= cached_ids:
        results = [cached[pid] for pid in ids if pid in cached]
    else:
        known_dois = repo.get_repo_dois()
        try:
            from ._citations import get_citation_counts

            results = get_citation_counts(ids, known_dois=known_dois or None)
        except Exception as e:
            click.echo(f"{RED}[error] {e}{RESET}", err=True)
            sys.exit(1)

        if not results:
            click.echo(f"{DIM}No citation data found for these papers.{RESET}")
            return

        try:
            new_dois = {r["paper_id"]: r["doi"] for r in results if r.get("doi")}
            if new_dois:
                repo.update_paper_dois(new_dois)
            repo.update_paper_citations({r["paper_id"]: r for r in results})
        except Exception:
            pass

    results.sort(key=lambda r: r["cited_by_count"] or 0, reverse=True)

    click.echo(f"Citation counts ({len(results)} papers, sorted by citations):\n")
    for r in results:
        cited = r["cited_by_count"] or 0
        year = r.get("pub_year") or "?"
        title = r.get("title", "")
        click.echo(f"  {r['paper_id']}  {cited} cites  {year}  {title}")

    total = sum(r["cited_by_count"] or 0 for r in results)
    avg = total / len(results) if results else 0
    unmatched = len(ids) - len(results)
    click.echo(
        f"\nTotal: {total:,} citations | Avg: {avg:,.0f} | Matched: {len(results)}/{len(ids)}"
    )
    if unmatched:
        matched_ids = {r["paper_id"] for r in results}
        missing = [pid for pid in ids if pid not in matched_ids]
        click.echo(
            f"Not found: {', '.join(missing[:5])}{'...' if len(missing) > 5 else ''}"
        )


def _show_cite_graph(ids: list[str], repo) -> None:
    if len(ids) < 2:
        click.echo(f"{DIM}Need at least 2 papers to build a citation graph.{RESET}")
        return

    known_dois = repo.get_repo_dois()

    click.echo(
        f"{DIM}  Querying Semantic Scholar for {len(ids)} papers...{RESET}", err=True
    )

    try:
        from ._citations import get_citation_graph

        graph = get_citation_graph(ids, known_dois=known_dois or None)
    except Exception as e:
        click.echo(f"{RED}[error] {e}{RESET}", err=True)
        sys.exit(1)

    nodes = graph.get("nodes", [])
    edges = graph.get("edges", [])

    if not nodes:
        click.echo(f"{DIM}No papers resolved. Check that papers have DOIs.{RESET}")
        return

    new_dois = {n["id"]: n["doi"] for n in nodes if n.get("doi")}
    if new_dois:
        try:
            repo.update_paper_dois(new_dois)
        except Exception:
            pass

    titles = {n["id"]: n.get("title", "")[:50] for n in nodes}
    cites = {n["id"]: n.get("cited_by_count", 0) for n in nodes}

    click.echo(
        f"\n  {BOLD}Citation Graph{RESET} ({len(nodes)} papers, {len(edges)} connections)\n"
    )

    if not edges:
        click.echo(f"  {DIM}No citation links found between these papers.{RESET}")
        click.echo(f"  {DIM}(Papers may not reference each other directly.){RESET}\n")
        for n in sorted(nodes, key=lambda x: x["cited_by_count"], reverse=True):
            click.echo(
                f"  {CYAN}{n['id']:>16}{RESET}  {cites[n['id']]:>5} cites  {DIM}{titles[n['id']]}{RESET}"
            )
        click.echo()
        return

    edge_by_source: dict[str, list[dict]] = {}
    incoming: dict[str, int] = {n["id"]: 0 for n in nodes}
    outgoing: dict[str, int] = {n["id"]: 0 for n in nodes}
    for e in edges:
        edge_by_source.setdefault(e["source"], []).append(e)
        outgoing[e["source"]] = outgoing.get(e["source"], 0) + 1
        incoming[e["target"]] = incoming.get(e["target"], 0) + 1

    for src_id in sorted(edge_by_source, key=lambda x: cites.get(x, 0), reverse=True):
        src_title = titles.get(src_id, "")
        click.echo(f"  {CYAN}{src_id}{RESET}  {DIM}{src_title}{RESET}")
        for e in edge_by_source[src_id]:
            marker = f"{YELLOW}★{RESET}" if e.get("influential") else " "
            tgt = e["target"]
            click.echo(
                f"    {marker} cites → {CYAN}{tgt}{RESET}  {DIM}{titles.get(tgt, '')}{RESET}"
            )
        click.echo()

    if incoming:
        top = sorted(incoming.items(), key=lambda x: x[1], reverse=True)
        cited_in_repo = [(pid, cnt) for pid, cnt in top if cnt > 0]
        if cited_in_repo:
            click.echo(f"  {BOLD}Most cited within repo:{RESET}")
            for pid, cnt in cited_in_repo[:5]:
                click.echo(
                    f"    {CYAN}{pid}{RESET}  ← {cnt} repo paper{'s' if cnt > 1 else ''}  "
                    f"{DIM}({cites.get(pid, 0)} total cites){RESET}"
                )
            click.echo()

    click.echo(
        f"  {DIM}★ = influential citation  |  {len(edges)} links among {len(nodes)} papers{RESET}\n"
    )


@repo_cmd.command("branch")
@click.argument("name", required=False, default=None)
def branch_cmd(name: str | None):
    """List or create branches on the active repo.

    \b
    Examples:
        paperclip git branch                   # list branches
        paperclip git branch clinical-data     # create + switch to new branch
    """
    from . import repo

    if name:
        try:
            result = repo.create_branch(name)
            click.echo(
                f"{GREEN}✓{RESET} Created branch: {BOLD}{result['branch']}{RESET} ({result['papers']} papers)"
            )
            click.echo(f"  {DIM}Forked from current branch with all papers.{RESET}")
        except ValueError as e:
            click.echo(f"{RED}[error] {e}{RESET}", err=True)
            sys.exit(1)
        return

    branches = repo.list_branches()
    if not branches:
        click.echo(f"{DIM}No active repo or no branches.{RESET}")
        return

    active_repo = repo.get_active_repo()
    click.echo(f"\n  {BOLD}Branches{RESET} ({active_repo})\n")
    for b in branches:
        marker = f"{GREEN}●{RESET}" if b["active"] else f"{DIM}○{RESET}"
        click.echo(
            f"  {marker} {BOLD}{b['name']}{RESET}  "
            f"{DIM}({b['paper_count']} papers, {b['commit_count']} commits){RESET}"
        )
    click.echo()


@repo_cmd.command("merge")
@click.argument("source_branch")
def merge_cmd(source_branch: str):
    """Merge papers from another branch into the current branch.

    \b
    Combines papers (union). If both branches have the same paper,
    the current branch's version is kept. Records a merge commit.

    Examples:
        paperclip git merge clinical-data
    """
    from . import repo

    try:
        result = repo.merge_branch(source_branch)
        if result["merged"] > 0:
            click.echo(
                f"  {GREEN}✓{RESET} Merged {BOLD}{result['merged']}{RESET} papers from '{result['source']}' into '{result['target']}'"
            )
            for pid in result["added"][:10]:
                click.echo(f"    {GREEN}+{RESET} {pid}")
            if len(result["added"]) > 10:
                click.echo(f"    {DIM}... and {len(result['added']) - 10} more{RESET}")
            click.echo(f"  {DIM}{result['total']} papers total{RESET}")
        else:
            click.echo(
                f"  {DIM}Nothing to merge — '{result['target']}' already has all papers from '{result['source']}'{RESET}"
            )
    except AuthError:
        click.echo(
            f"{RED}[error] Authentication failed (API key invalid).{RESET}", err=True
        )
        sys.exit(1)
    except ValueError as e:
        click.echo(f"{RED}[error] {e}{RESET}", err=True)
        sys.exit(1)


@repo_cmd.command("log")
@click.option("-n", "--limit", default=20, type=int, help="Max commits to show")
@click.option("--branch", "-b", default=None, help="Show log for a specific branch")
@click.option("--json", "as_json", is_flag=True, help="Output as JSON")
def log_cmd(limit: int, branch: str | None, as_json: bool):
    """Show commit log for the active repo.

    \b
    Like `git log` — shows the commit history with SHAs, messages,
    and paper counts.

    Examples:
        paperclip git log
        paperclip git log -n 5
        paperclip git log --branch safety-concerns
    """
    import json as json_mod

    from . import repo

    active = repo.get_active_repo()
    if not active:
        click.echo("No active repo. Use: paperclip git init <name>")
        return

    commits = repo.get_log(branch=branch, limit=limit)

    if as_json:
        click.echo(json_mod.dumps(commits, indent=2, default=str))
        return

    if not commits:
        click.echo(f"{DIM}No commits yet. Use: paperclip git commit -m \"message\"{RESET}")
        return

    active_branch = branch or repo._get_active_branch_name()
    click.echo(f"\n  {BOLD}Commit log{RESET} ({active}/{active_branch})\n")

    for c in commits:
        sha = c.get("sha", "?")[:8]
        parent = c.get("parent_sha", "")
        msg = c.get("message", "").split("\n")[0]
        count = c.get("paper_count", 0)
        ts = str(c.get("timestamp", ""))[:19].replace("T", " ")

        click.echo(f"  {YELLOW}{sha}{RESET} {msg}")
        click.echo(f"    {DIM}{count} papers  {ts}{RESET}")
        if parent:
            click.echo(f"    {DIM}parent: {parent[:8]}{RESET}")
        click.echo()


@repo_cmd.command("history")
@click.option("--tool", "-t", default=None, help="Filter by tool name (e.g. search_papers)")
@click.option("--page", "-p", default=1, type=int, help="Page number")
@click.option("--per-page", "-n", default=20, type=int, help="Results per page")
@click.option("--json", "as_json", is_flag=True, help="Output as JSON")
def history_cmd(tool: str | None, page: int, per_page: int, as_json: bool):
    """Show command audit trail for the active repo.

    \b
    Examples:
        paperclip git history
        paperclip git history -t search_papers
        paperclip git history -n 10
        paperclip git history --json
    """
    from . import repo as repo_module
    import json as json_mod

    active = repo_module.get_active_repo()
    if not active:
        click.echo("No active repo. Use: paperclip git init <name>")
        return

    result = repo_module.get_history(
        tool_name=tool,
        page=page,
        per_page=per_page,
    )
    entries = result.get("entries", [])
    total = result.get("total", 0)

    if as_json:
        click.echo(json_mod.dumps(result, indent=2, default=str))
        return

    if not entries:
        click.echo(f"{DIM}No command history found.{RESET}")
        return

    click.echo(f"\n  {BOLD}Command history{RESET} ({active}) — {total} total\n")

    for e in entries:
        ts = str(e.get("created_at", ""))[:19].replace("T", " ")
        tool_name = e.get("tool_name", "?")
        cmd = e.get("command", "")
        doc_ids = e.get("document_ids", [])
        exit_c = e.get("exit_code", 0)

        mark = f"{GREEN}✓{RESET}" if exit_c == 0 else f"{RED}✗{RESET}"
        click.echo(f"  {mark} {CYAN}{tool_name}{RESET}  {DIM}{ts}{RESET}")

        if cmd:
            display_cmd = cmd[:120] + ("..." if len(cmd) > 120 else "")
            click.echo(f"    {display_cmd}")

        if doc_ids:
            click.echo(f"    {DIM}docs: {', '.join(doc_ids[:5])}{RESET}")
            if len(doc_ids) > 5:
                click.echo(f"    {DIM}      ... and {len(doc_ids) - 5} more{RESET}")

        summary = e.get("result_summary", "")
        if summary:
            display = summary[:200] + ("..." if len(summary) > 200 else "")
            click.echo(f"    {DIM}→ {display}{RESET}")
        click.echo()

    if total > page * per_page:
        click.echo(f"  {DIM}Page {page}/{(total + per_page - 1) // per_page} — use -p {page + 1} for next{RESET}\n")


