# ── Timeline ──────────────────────────────────────────────────────


# ── Server-proxied commands ───────────────────────────────────────
# search, lookup, sql, bash, grep, cat, head, etc. are all handled by
# _PaperclipGroup's catch-all proxy — no explicit registration needed.


# ── Results helpers ───────────────────────────────────────────────


def _strip_ansi(text: str) -> str:
    return _ANSI_RE.sub("", text)


def _parse_papers_from_output(output: str) -> list[dict]:
    """Parse formatted search/lookup output into paper records for CSV."""
    text = _strip_ansi(output)
    records: list[dict] = []

    entries = re.split(r"\n(?=\s+\d+\.\s)", text)
    for entry in entries:
        lines = entry.strip().split("\n")
        if not lines:
            continue
        m = re.match(r"\s*(\d+)\.\s+(.+)", lines[0])
        if not m:
            continue

        record: dict = {"title": m.group(2).strip()}
        remaining = [ln.strip() for ln in lines[1:] if ln.strip()]

        for line in remaining:
            if line.startswith("https://"):
                record.setdefault("url", line)
            elif line.startswith("doi:"):
                record.setdefault("url", f"https://doi.org/{line[4:]}")
            elif line.startswith('"'):
                record["abstract"] = line.strip('"')
            elif "\u00b7" in line or "·" in line:
                sep = "\u00b7" if "\u00b7" in line else "·"
                parts = [p.strip() for p in line.split(sep)]
                if parts:
                    record["id"] = parts[0]
                if len(parts) >= 2:
                    record["source"] = parts[1]
                if len(parts) >= 3:
                    record["date"] = parts[2]
            elif "authors" not in record:
                record["authors"] = line

        records.append(record)
    return records


def _paper_url_from_record(record: dict) -> str:
    doc_id = str(record.get("document_id") or record.get("id") or "")
    source = str(record.get("source") or "").lower()
    doi = str(record.get("doi") or "")

    if doc_id.startswith("PMC"):
        return f"https://www.ncbi.nlm.nih.gov/pmc/articles/{doc_id}/"
    if source == "arxiv" or doc_id.startswith(("arx_", "arxiv_")):
        arxiv_id = re.sub(r"^(arx|arxiv)_", "", doc_id)
        for category in (
            "astro-ph",
            "cond-mat",
            "cs",
            "gr-qc",
            "hep-ex",
            "hep-lat",
            "hep-ph",
            "hep-th",
            "math",
            "nlin",
            "nucl-ex",
            "nucl-th",
            "physics",
            "q-bio",
            "quant-ph",
            "stat",
        ):
            suffix = arxiv_id[len(category) :] if arxiv_id.startswith(category) else ""
            if suffix and suffix[0].isdigit():
                arxiv_id = f"{category}/{suffix}"
                break
        return f"https://arxiv.org/abs/{arxiv_id}"
    if doi:
        return f"https://doi.org/{doi}"
    return ""


def _format_full_papers_result(data: dict) -> str | None:
    result_data = data.get("result_data")
    if not isinstance(result_data, dict):
        return None
    if result_data.get("kind") in {"map_manifest", "map_result"}:
        return None
    papers = result_data.get("papers")
    if not isinstance(papers, list):
        papers = result_data.get("results")
    if not isinstance(papers, list):
        return None

    rid = data.get("result_id", "")
    is_patents = any(
        (p.get("source") or "").lower() == "patents"
        or p.get("publication_number")
        or re.match(r"^[A-Z]{2}-\d", str(p.get("document_id") or ""))
        for p in papers[:3]
    )
    noun = "patents" if is_patents else "papers"
    lines = [f"Found {len(papers)} {noun}" + (f"  [{rid}]" if rid else ""), ""]
    for i, paper in enumerate(papers, 1):
        title = paper.get("title") or "Untitled"
        authors = paper.get("authors") or ""
        doc_id = (
            paper.get("publication_number")
            or paper.get("document_id")
            or paper.get("id")
            or "?"
        )
        source = paper.get("source") or ""
        date = (
            paper.get("publication_date")
            or paper.get("pub_date")
            or paper.get("pub_year")
            or paper.get("month_year")
            or ""
        )
        abstract = (
            paper.get("content")
            or paper.get("abstract_snippet")
            or paper.get("abstract")
            or paper.get("snippet")
            or ""
        )
        url = _paper_url_from_record(paper)
        path = paper.get("path") or ""
        line_number = paper.get("line_number")

        lines.append(f"  {BOLD}{i}. {title}{RESET}")
        if authors and not is_patents:
            short = str(authors)[:100] + ("..." if len(str(authors)) > 100 else "")
            lines.append(f"     {short}")
        meta = [str(doc_id)]
        if source and not is_patents:
            meta.append(str(source))
        if date:
            meta.append(str(date))
        if is_patents:
            matched = paper.get("matched_publication_number")
            if matched and matched != doc_id:
                meta.append(f"matched via {matched}")
            family_size = paper.get("family_size") or 0
            if family_size and int(family_size) > 1:
                meta.append(f"family ×{int(family_size)}")
            family_countries = paper.get("family_countries") or []
            if family_countries:
                meta.append(f"family countries {','.join(family_countries)}")
        lines.append(f"     {DIM}{' · '.join(meta)}{RESET}")
        if is_patents and line_number and path:
            lines.append(f"     {CYAN}{path}#L{line_number}{RESET}")
        elif is_patents and path:
            lines.append(f"     {CYAN}{path}{RESET}")
        elif url:
            lines.append(f"     {CYAN}{url}{RESET}")
        if abstract:
            snippet = str(abstract).strip().replace("\n", " ")
            if len(snippet) > 220:
                snippet = snippet[:217] + "..."
            lines.append(f'     {DIM}"{snippet}"{RESET}')
        lines.append("")
    return "\n".join(lines)


def _format_result_sample(data: dict) -> str:
    papers = data.get("papers") or []
    total = data.get("count", len(papers))
    seed = data.get("seed")
    rid = data.get("result_id") or ""
    lines = [
        f"Random sample of {len(papers)} from {total} papers"
        + (f"  [{rid}]" if rid else "")
        + f"  (seed: {seed})",
        "",
    ]
    for index, paper in enumerate(papers, 1):
        title = paper.get("title") or "Untitled"
        document_id = (
            paper.get("document_id") or paper.get("id")
            or paper.get("paper_id") or "?"
        )
        metadata = [str(document_id)]
        for value in (paper.get("source"), paper.get("year")):
            if value not in (None, ""):
                metadata.append(str(value))
        lines.append(f"  {BOLD}{index}. {title}{RESET}")
        lines.append(f"     {DIM}{' · '.join(metadata)}{RESET}")
        abstract = paper.get("abstract") or paper.get("abstract_snippet") or ""
        if abstract:
            snippet = " ".join(str(abstract).split())
            if len(snippet) > 220:
                snippet = snippet[:217] + "..."
            lines.append(f'     {DIM}"{snippet}"{RESET}')
        evidence = paper.get("match_evidence") or paper.get("matches") or []
        if isinstance(evidence, list):
            for match in evidence[:3]:
                if not isinstance(match, dict):
                    continue
                snippet = " ".join(
                    str(match.get("snippet") or match.get("text") or "").split()
                )
                if not snippet:
                    continue
                if len(snippet) > 300:
                    snippet = snippet[:297] + "..."
                context = [
                    str(value)
                    for value in (match.get("section"), match.get("block_type"))
                    if value
                ]
                label = f" ({' · '.join(context)})" if context else ""
                lines.append(f"     {CYAN}match{label}:{RESET} {snippet}")
        lines.append("")
    return "\n".join(lines)


def _format_full_map_result(data: dict) -> str | None:
    """Render full per-paper answers from a durable map result."""
    manifest = data.get("result_data")
    if (
        not isinstance(manifest, dict)
        or manifest.get("kind") not in {"map_manifest", "map_result"}
    ):
        return None
    map_id = manifest.get("map_id") or data.get("result_id") or ""
    inputs = manifest.get("inputs") if isinstance(manifest.get("inputs"), dict) else {}
    query = str(inputs.get("query") or data.get("raw_input") or "").strip()
    results = manifest.get("results")
    if not isinstance(results, list):
        results = [
            task.get("result")
            for task in manifest.get("tasks") or []
            if isinstance(task, dict) and isinstance(task.get("result"), dict)
        ]
    lines = [f"Map results  [{map_id}]" if map_id else "Map results"]
    if query:
        lines.append(f"Query: {query}")
    lines.append("")
    for index, result in enumerate(results, 1):
        if not isinstance(result, dict):
            continue
        title = result.get("title") or result.get("path") or f"Paper {index}"
        document_id = result.get("document_id") or ""
        status = result.get("status") or "unknown"
        lines.append(f"--- [{index}] [{status}] {title} ---")
        if document_id:
            lines.append(f"doc_id: {document_id}")
        error = str(result.get("error") or "").strip()
        if error:
            lines.append(f"error: {error}")
        answer = result.get("response")
        if answer in (None, ""):
            answer = result.get("output")
        if answer not in (None, ""):
            lines.append(str(answer))
        lines.append("")
    return "\n".join(lines).rstrip()


def _results_picker(rows: list[dict]) -> int | None:
    """Interactive paginated picker for saved results."""
    if not sys.stdin.isatty():
        return None
    try:
        import termios
        import tty
    except (ImportError, AttributeError):
        return None

    n = len(rows)
    page_size = min(_RESULTS_PAGE_SIZE, n)
    total_pages = (n + page_size - 1) // page_size
    idx = 0
    fd = sys.stdin.fileno()
    old = termios.tcgetattr(fd)
    redraw_lines = page_size

    def _desc(r: dict) -> str:
        raw = r.get("raw_input", r.get("command", ""))
        return raw[:45] + ("..." if len(raw) > 45 else "")

    def _ts(r: dict) -> str:
        return (r.get("created_at") or "")[:16].replace("T", " ")

    def render(first: bool = False) -> None:
        page = idx // page_size
        start = page * page_size
        end = min(start + page_size, n)

        if not first:
            sys.stdout.write(f"\033[{redraw_lines}A\r")

        for i in range(start, start + page_size):
            if i < end:
                r = rows[i]
                rid = r.get("result_id", "?")
                desc = _desc(r)
                ts = _ts(r)
                if i == idx:
                    sys.stdout.write(
                        f"{CLR}  {CYAN}\u203a {rid}{RESET}  {desc}  {DIM}{ts}{RESET}\n"
                    )
                else:
                    sys.stdout.write(
                        f"{CLR}    {DIM}{rid}{RESET}  {desc}  {DIM}{ts}{RESET}\n"
                    )
            else:
                sys.stdout.write(f"{CLR}\n")

        pg = f"page {page + 1}/{total_pages}" if total_pages > 1 else ""
        paging = "n/p page \u00b7 " if total_pages > 1 else ""
        sys.stdout.write(
            f"{CLR}  {DIM}\u2191/\u2193 navigate \u00b7 enter save \u00b7 {paging}q quit  {pg}{RESET}"  # noqa: E501
        )
        sys.stdout.flush()

    click.echo(f"\n  {BOLD}Paperclip Results{RESET}")
    rule = "\u2500" * 40
    click.echo(f"  {DIM}{rule}{RESET}")
    click.echo(f"  {n} saved result{'s' if n != 1 else ''}\n")
    render(first=True)

    try:
        tty.setcbreak(fd)
        while True:
            ch = os.read(fd, 1)
            if ch == b"\x1b":
                b = os.read(fd, 1)
                if b == b"[":
                    arrow = os.read(fd, 1)
                    if arrow == b"A":
                        idx = (idx - 1) % n
                    elif arrow == b"B":
                        idx = (idx + 1) % n
                render()
            elif ch in (b"\r", b"\n"):
                sys.stdout.write("\n\n")
                sys.stdout.flush()
                return idx
            elif ch == b"n" and total_pages > 1:
                page = idx // page_size
                if page < total_pages - 1:
                    idx = (page + 1) * page_size
                    render()
            elif ch == b"p" and total_pages > 1:
                page = idx // page_size
                if page > 0:
                    idx = (page - 1) * page_size
                    render()
            elif ch in (b"q", b"\x03"):
                sys.stdout.write("\n")
                sys.stdout.flush()
                return None
    finally:
        termios.tcsetattr(fd, termios.TCSADRAIN, old)


# ── results command ───────────────────────────────────────────────


@main.command()
@click.argument("result_id", required=False, default=None)
@click.option("--list", "list_all", is_flag=True, help="Non-interactive list")
@click.option(
    "--save",
    "save_path",
    default=None,
    help="Export search metadata or full per-paper map answers",
)
@click.option("--export-bundle", default=None, help="Export a portable cohort bundle directory")
@click.option("--import-bundle", default=None, help="Import a portable cohort bundle directory")
@click.option("--save-as", default=None, help="Alias for an imported bundle")
@click.option(
    "--sample", "sample_count", type=click.IntRange(1, 100), default=None,
    help="Randomly sample up to 100 papers from a saved result",
)
@click.option("--seed", type=int, default=None, help="Reproduce a random sample")
def results(
    result_id: str | None, list_all: bool, save_path: str | None,
    export_bundle: str | None, import_bundle: str | None, save_as: str | None,
    sample_count: int | None, seed: int | None,
):
    """View and export saved search or map results.

    \b
    View a specific result:
        paperclip results s_4a2b61f6

    Export to CSV:
        paperclip results s_4a2b61f6 --save results.csv

    Export full map answers:
        paperclip results m_4a2b61f6 --save map-results.txt

    Export or import a portable cohort bundle:
        paperclip results s_4a2b61f6 --export-bundle cohort/
        paperclip results --import-bundle cohort/ --save-as restored_cohort

    Sample a cohort (repeatable with the same seed):
        paperclip results s_4a2b61f6 --sample 20 --seed 42

    List all saved results:
        paperclip results --list
    """
    client = _get_client()

    if seed is not None and sample_count is None:
        raise click.UsageError("--seed requires --sample")
    if sample_count is not None and not result_id:
        raise click.UsageError("--sample requires a result ID or alias")
    if import_bundle:
        if result_id or save_path or export_bundle or list_all or sample_count is not None:
            raise click.UsageError(
                "--import-bundle cannot be combined with a result ID, --save, "
                "--export-bundle, --sample, or --list"
            )
        from .cohort_bundle import BundleError, load_bundle

        try:
            papers, manifest = load_bundle(import_bundle)
            imported = client.results.import_bundle(
                papers,
                provenance={
                    "original_result_id": manifest.get("result_id"),
                    "original_config_hash": manifest.get("config_hash"),
                    "bundle_schema_version": manifest.get("schema_version"),
                },
                save_as=save_as,
            )
        except (BundleError, OSError, PaperclipError) as exc:
            raise click.ClickException(str(exc)) from exc
        suffix = f" (alias: {save_as})" if save_as else ""
        click.echo(
            f"  {GREEN}\u2713{RESET} Loaded {imported['count']} papers as "
            f"{BOLD}{imported['result_id']}{RESET}{suffix}"
        )
        return
    if save_as:
        raise click.UsageError("--save-as requires --import-bundle")
    if export_bundle and not result_id:
        raise click.UsageError("--export-bundle requires a result ID or alias")
    if save_path and export_bundle:
        raise click.UsageError("--save and --export-bundle cannot be combined")
    if sample_count is not None and (save_path or export_bundle or list_all):
        raise click.UsageError(
            "--sample cannot be combined with --save, --export-bundle, or --list"
        )

    def _fetch_result(rid: str) -> dict | None:
        try:
            data = client.results.get(rid)
        except NetworkError:
            click.echo(f"{RED}[error] Could not reach the server.{RESET}", err=True)
            click.echo(
                f"{DIM}       If this persists, try: paperclip login{RESET}", err=True
            )
            return None
        except PaperclipError as exc:
            if "not found" in str(exc).lower():
                click.echo(f"{RED}[error] Result {rid} not found.{RESET}", err=True)
            else:
                click.echo(
                    f"{RED}[error] Something went wrong. Please try again.{RESET}",
                    err=True,
                )
            return None
        return data.raw or {
            "result_id": data.result_id,
            "output": data.output,
            "command": data.command,
            "raw_input": data.raw_input,
            "created_at": data.created_at,
            "latency_ms": data.latency_ms,
        }

    def _export(rid: str, data: dict, dest_path: str) -> None:
        map_output = _format_full_map_result(data)
        if map_output is not None:
            dest = Path(dest_path).expanduser().resolve()
            dest.write_text(_strip_ansi(map_output))
            click.echo(f"  {GREEN}\u2713{RESET} Saved to {BOLD}{dest}{RESET}")
            return
        output = data.get("output", "")
        records = _parse_papers_from_output(output)
        dest = Path(dest_path).expanduser().resolve()

        if not records or dest.suffix != ".csv":
            dest.write_text(_strip_ansi(output))
            click.echo(f"  {GREEN}\u2713{RESET} Saved to {BOLD}{dest}{RESET}")
            return

        fieldnames = ["title", "authors", "id", "source", "date", "url", "abstract"]
        with open(dest, "w", newline="") as handle:
            writer = csv.DictWriter(handle, fieldnames=fieldnames, extrasaction="ignore")
            writer.writeheader()
            writer.writerows(records)

        click.echo(
            f"  {GREEN}\u2713{RESET} Saved {len(records)} papers to {BOLD}{dest}{RESET}"
        )

    if result_id:
        if sample_count is not None:
            try:
                sample = client.results.sample(
                    result_id, count=sample_count, seed=seed
                )
            except PaperclipError as exc:
                raise click.ClickException(str(exc)) from exc
            click.echo(_format_result_sample(sample))
            return
        if export_bundle:
            from .cohort_bundle import (
                BundleError,
                export_bundle as export_cohort_bundle,
            )

            try:
                dest, manifest = export_cohort_bundle(client, result_id, export_bundle)
            except (BundleError, OSError, PaperclipError) as exc:
                raise click.ClickException(str(exc)) from exc
            click.echo(
                f"  {GREEN}\u2713{RESET} Exported {manifest['paper_count']} papers "
                f"to {BOLD}{dest}{RESET}"
            )
            return
        data = _fetch_result(result_id)
        if not data:
            return
        if save_path:
            _export(result_id, data, save_path)
            return
        output = data.get("output", "")
        raw_input = data.get("raw_input", data.get("command", ""))
        if raw_input:
            click.echo(f"  {DIM}Query: {raw_input}{RESET}")
        map_output = _format_full_map_result(data)
        if map_output is not None:
            click.echo(map_output)
            return
        full_output = _format_full_papers_result(data)
        if full_output:
            click.echo(full_output)
        elif output:
            click.echo(output)
        return

    try:
        rows = client.results.list()
    except NetworkError:
        click.echo(f"{RED}[error] Could not reach the server.{RESET}", err=True)
        click.echo(
            f"{DIM}       If this persists, try: paperclip login{RESET}", err=True
        )
        sys.exit(1)
    except PaperclipError:
        click.echo(
            f"{RED}[error] Something went wrong. Please try again.{RESET}", err=True
        )
        sys.exit(1)

    if not rows:
        click.echo(f"{DIM}No saved results. Run a search or map first.{RESET}")
        return

    rows_as_dicts = [r.raw or _resultrow_to_dict(r) for r in rows]

    if list_all or not sys.stdin.isatty():
        click.echo(f"{BOLD}Recent results ({len(rows_as_dicts)}):{RESET}\n")
        for r in rows_as_dicts:
            rid = r.get("result_id", "?")
            raw = r.get("raw_input", r.get("command", ""))
            ts = (r.get("created_at") or "")[:16].replace("T", " ")
            click.echo(f"  {rid}  {DIM}{raw}  {ts}{RESET}")
        return

    choice = _results_picker(rows_as_dicts)
    if choice is None:
        return

    selected = rows_as_dicts[choice]
    rid = selected["result_id"]
    data = _fetch_result(rid)
    if data:
        output = data.get("output", "")
        records = _parse_papers_from_output(output)
        default_ext = ".csv" if records else ".txt"
        path = click.prompt("  Save to", default=f"./{rid}{default_ext}")
        _export(rid, data, path)


def _resultrow_to_dict(r: ResultRow) -> dict:
    """Fallback translation for ResultRow → dict when ``raw`` is empty."""
    return {
        "result_id": r.result_id,
        "command": r.command,
        "raw_input": r.raw_input,
        "latency_ms": r.latency_ms,
        "created_at": r.created_at,
    }


